quests[12542] = { id = 12542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Kreuzzugs", description = "{class}! Der Argentumkreuzzug sucht nach fähigen Soldaten, die gewillt sind, ihre Differenzen beiseite zu legen und gemeinsam gegen die Streitkräfte des Lichkönigs in den Krieg zu ziehen. Werdet Ihr für unsere Sache kämpfen?\n\nGeht nach Norden zur Lichtwarte, falls Ihr Interesse haben solltet, und sprecht mit Kreuzritter Valus.\n\nDie Warte befindet sich inmitten der Ruinen der gebrandschatzten Trollstadt von Jintha'kalar an der Grenze zu Zul'Drak.\n\nLebt wohl.", sourceObjective = "Meldet Euch bei Kreuzritter Valus in der Lichtwarte in der Drachenöde.", completion = "Das Reich der Drakkari befindet sich nur ein paar Schritt weit entfernt.\n\n<Valus deutet nach Osten.>\n\nÜber Tausende Jahre hinweg hielten sich die Drakkari vom Rest der Welt fern und zogen es vor, innerhalb der Grenzen ihrer riesigen Tempelstädte und Ziggurats zu bleiben. Angesichts dessen war es überraschend, auf diese Trümmer hier zu stoßen. Etwas höher, jenseits der Treppen, die Nach Zul'Drak führen und von denen eine drohende Gefahr ausgeht, befinden sich die Ruinen der Feste Drak'Tharon. Der gesamte erste Ring von Zul'Drak ist zerstört...\n\nWieso greift die Geißel erst jetzt an?", sourceObjectiveStatus = "unverified-source-field" }
quests[12543] = { id = 12543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Opfergabe für Soo-rahm", description = "Wir nicht kennen Euch, <Fremder/Fremde>, aber wir wissen, Ihr wollt etwas.\n\nWir sprechen mit Knochen von Nozronn für Euch, aber Ihr müsst bringen Opfergaben für uns. Wir brauchen mächtige Kaiserkobragiftzähne, um unsere Orakelhalskette fertig zu stellen.\n\nIhr geht zum Wildwuchsmangal, nordöstlich unserer Hütte, findet Kobras und bringt beste Giftzähne wieder. Dann wir bringen Knochen zum Sprechen für Euch.", sourceObjective = "Bringt dem Orakel Soo-rahm in der Nähe der Knochen von Nozronn 5 Intakte Kobragiftzähne.", progress = "Wir müssen wissen, bringt Ihr Giftzähne?", completion = "<Das Orakel inspiziert die Giftzähne.>\n\nWir gutheißen! Knochen von Nozronn werden mit {name} sprechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12544] = { id = 12544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen von Nozronn", description = "Knochen von Nozronn, Orakel Soo-rahm schickt {name} zu Euch!\n\nWir haben Weihrauch für Euch vorbereitet. Zündet es an und platziert es neben Nozronns Kopf und Ihr werdet seine Stimme hören.\n\n<Verwirrt weist Ihr Soo-rahm darauf hin, dass Ihr ihm bisher noch nicht einmal Eure Frage genannt habt.>\n\nStimmt, wir nicht wissen, aber mächtiger Nozronn kennt sie. Zweifelt nicht. Nozronn wird Frage beantworten, die Euch auf dem Herzen liegt.\n\nGeht. Nozronn nicht warten.", sourceObjective = "Benutzt Soo-rahms Weihrauch in der Nähe der Knochen von Nozronn, kehrt dann mit den Informationen, die Ihr in Erfahrung gebracht habt, zu Hemet Nesingwary in Nesingwarys Basislager zurück.", completion = "<Hemet hört zu, während Ihr beschreibt, was Ihr in Erfahrung gebracht habt.>\n\nWeiter so, Junge. Kein totes Rhinozeros wird Hemet Nesingwary erzählen, wo und was er jagen darf. Wir werden es diesem Knochenhaufen zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12545] = { id = 12545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säuberung von Jintha'kalar", description = "Wir mussten diesen uralten Drakkaritempel einem ganzen Schwarm von einmarschierenden Dienern der Geißel abringen. Nur etwa einhundert Schritt von uns entfernt befindet sich die in Ruinen liegende Stadt von Jintha'kalar. Dort laufen Totenbeschwörer der Geißel Amok und verwandeln die verbliebenen lebenden Drakkaritrolle in Diener des Lichkönigs.\n\nFür das Licht sind sie alle verloren. Sie müssen alle beseitigt werden.\n\n<Valus sieht Euch streng an.>\n\nAlle.", sourceObjective = "Kreuzritter Valus bei der Lichtwarte in der Drachenöde möchte, dass Ihr 15 Anhänger der Geißel von Jintha'kalar tötet.", progress = "Lasst nichts zurück, was der Lichkönig wiederbeleben könnte!", completion = "Wie Ihr sehen könnt, befindet sich die Kriegsmaschinerie der Geißel auf dem Vormarsch, und trotzdem sind die Armeen der Allianz und Horde gespalten, was sie zu leichter Beute macht. Aus diesem Grund müssen wir zusammenhalten.\n\n<Valus wirkt einen Moment lang gedankenverloren.>\n\nDer Argentumkreuzzug hat Verwendung für einen Mann wie Euch. Wäret Ihr womöglich daran interessiert, Euch unserer Sache zu widmen und Seite an Seite mit dem Aschenbringer in die Schlacht zu ziehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12546] = { id = 12546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergewinnung", description = "Es ist soweit, {name}. Der Etymidian ist eine der zerstörerischsten Kräfte, die jemals von den Titanen erschaffen wurden, und ich lasse ihn nur ungern auf meine Lande los.\n\nDoch habe ich keine Wahl. Unsere Feinde zwingen mich dazu und der Zorn der Titanen wird alle vernichten.", sourceObjective = "Geht zur Lawine im Sholazarbecken und verwendet die Omegarune, um den Etymidian zu aktivieren. Tötet mit ihm 200 Diener der Geißel, Bythius den Fleischformer, Urgreth von den Tausend Gräbern und Hagel'skorn.\n\nSprecht mit dem Avatar von Freya im Sholazarbecken, sobald Ihr diese Aufgabe abgeschlossen habt.", progress = "Die, die das Leben bedrohen... habt Ihr Euch um sie gekümmert?", completion = "Ich bin dankbar für Eure Hilfe, {name}. Es ist meine Pflicht, über diese Lande und alles Leben in ihnen zu wachen.\n\nDank Euch wird dieses Leben weiter bestehen, um aufzublühen, während die Streitkräfte des Todes in den Grenzregionen Krieg führen.\n\nEure Taten werden niemals vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12547] = { id = 12547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aktivierungsrune", description = "Dieses kolossale Wesen scheint nicht aktiviert zu sein. Ihr bemerkt auf der Brust einen leeren Spalt in Runenform.\n\nVielleicht gelingt es Euch, die fehlende Rune im nahegelegenen Aussichtspunkt zu finden.", sourceObjective = "Besorgt die Omegarune von der Terrasse des Formers und bringt sie zu Etymidian.", progress = "<Der runenförmige Spalt auf der Brust des Etymidians scheint mit einer schwachen Energie zu leuchten.>", completion = "<Ihr hört das polternde Geräusch von reibendem Stein, während Etymidians Gliedmaßen mit Leben durchströmt werden.>\n\nIch werde gebraucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[12548] = { id = 12548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Etymidian", description = "Der Moment ist gekommen, {name}. Das Tor wurde zum ersten Mal seit sieben Jahrhunderten wieder aktiviert. Schreitet hindurch und es wird Euch dorthin bringen, wo sich unsere letzte Hoffnung befindet.\n\nBereiten wir jenen ein Ende, die den Makel der Untoten in dieses unberührte Land zu bringen versuchen. Entfesseln wir den Etymidian.", sourceObjective = "Durchschreitet das Tor am südlichen Ende des Sholazarbeckens und sucht auf der anderen Seite nach der Waffe, die der Etymidian genannt wird.", completion = "<Als Ihr die Inschrift auf diesem Steinkoloss lest, wird Euch klar, dass dies die Waffe ist, von der Freya sprach. Dies ist der Etymidian.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12549] = { id = 12549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Schreckenssäblerjagd: Zum Raubtier werden", description = "Falls Ihr schon einmal mit Hemet auf der Jagd gewesen seid, dann wisst Ihr, dass er sein Können schon an vielen großen Katzen erprobt hat, doch die Schreckenssäbler hier im Sholazarbecken gehören nicht dazu. Sie können Wild von einer Größe zu Fall bringen, wie ich es bei anderen Katzen noch nie erlebt habe. Solch ein Raubtier in den Griff zu bekommen, ist ein Zeichen dafür, dass man ein echter Jäger ist.\n\nFalls Ihr also beweisen wollt, dass Ihr der Herausforderung gewachsen seid, dann testet Euer Können an einem Schreckenssäbler. Sie leben in der Gegend um das Lager herum und südlich des Flusses.", sourceObjective = "Tötet 15 Schreckenssäbler und kehrt anschließend zu Buck Cantwell in Nesingwarys Basislager zurück.", completion = "Nun, Ihr habt bewiesen, dass Ihr ein fähiger Jäger seid; doch wie würdet Ihr als Fährtenleser abschneiden?", sourceObjectiveStatus = "unverified-source-field" }
quests[12550] = { id = 12550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Schreckenssäblerjagd: Der Beute auf der Spur", description = "Ich habe gehört, dass die Eingeborenen Geschichten von einem riesigen Schreckenssäbler erzählen, den sie Shango nennen. Ich habe bisher keine Beweise seiner Existenz gesehen, aber meine Wunden haben mich davon abgehalten, mich aus dem Lager zu wagen.\n\nWenn Ihr Euch für so etwas wie einen Fährtenleser haltet, seid Ihr vielleicht in der Lage, die Wahrheit über Shango herauszufinden. Debaar sagte, sie sah bei ihrem letzten Ausflug einige breite Spuren. Geht nach Norden in Richtung des Bittertidensees und sucht am Südufer nach den Abdrücken.", sourceObjective = "Buck Cantwell in Nesingwarys Basislager möchte, dass Ihr 3 Shangofährten aus den Schreckenssäblerfährten nahe des Bittertidensees herauslest.", completion = "<Buck hört Euch zu, während Ihr über Euren Fund berichtet.>\n\nIch glaube, Ihr habt womöglich die Beweise gefunden, die wir für diesen Shango brauchen. Und ich glaube, ich habe eine Idee, wo wir ihn finden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12551] = { id = 12551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Krokiliskenjagd: Die Prüfung", description = "Ich warne Euch, Fremdling - keine Kommentare über den Schiffsbruch. Ich muss mir schon genug vom Rest der Expedition anhören.\n\nWenn Ihr Euch aber am Jagen versuchen wollt, solltet Ihr Eure Fähigkeiten an den gerissenen Mangalkrokilisken erproben. Sie leben entlang des Flusses im Süden und im Wildwuchsmangal im Osten. Beweist, dass Ihr ihnen gewachsen seid, und wir sprechen uns wieder, Jäger.", sourceObjective = "Tötet 15 Mangalkrokilisken und kehrt zu Debaar in Nesingwarys Basislager zurück.", completion = "Beeindruckend, {class}. Seid Ihr sicher, dass Ihr kein Mitglied der Expedition seid?\n\nNein, ausgeschlossen. Ihr hättet sonst irgendwann einen Witz über den Unfall gerissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12552] = { id = 12552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Nekromagiern", description = "Kolramas ist gleich hier im Südosten abgestürzt, nachdem die Trolle es vom Himmel geholt haben. Unglücklicherweise sind bei dem Absturz nicht alle Diener der Geißel vernichtet worden.\n\nNun lassen sie unsere Männer wieder von den Toten auferstehen und verwenden sie gegen uns!\n\nDies muss ein Ende haben. Ihr werdet dafür sorgen, dass ihre Nekromagier getötet werden! Haben wir uns da verstanden?", sourceObjective = "Unteroffizier Mondsplitter in Drak'Sotra möchte, dass Ihr 8 Nekromagier von Hath'ar vernichtet.", completion = "Es ist nicht genug!\n\n<Die Stimme des Unteroffiziers versagt. Er trauert um seine gefallenen Kameraden, die nun in Diener der Geißel verwandelt wurden.>\n\nDiese Männer haben mehr Respekt von uns verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[12553] = { id = 12553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seglerspinndrüsen", description = "Wieso muss ich mich immer mit den schweren Aufgaben herumschlagen?\n\nDie Diener der Geißel bei Kolramas sind mit Seuchensprühern ausgerüstet und kommen uns gefährlich nahe. Ihr wollt gar nicht erst wissen, was passieren würde, wenn sie sich auf den Weg hierher machen sollten!\n\nIch habe eine Idee, wie wir sie runterholen könnten, doch dazu brauchen wir zuerst etwas... etwas von ihren eigenen Kreaturen.\n\nDie Segler der Hath'ar spinnen ein sehr starkes Netz, das wir gut gebrauchen können. Beschafft Euch ein paar ihrer Spinndrüsen.", sourceObjective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr 5 intakte Seglerspinndrüsen beschafft.", progress = "Diese Spinndrüsen müssen noch intakt sein, wenn ich aus ihnen ein Gerät bauen soll, das auch funktioniert.", completion = "Die werden reichen!\n\nNun werden wir ein paar Rohteile besorgen müssen, damit ich das Abschussgerät für Euch zusammenstellen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12554] = { id = 12554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malas der Verderber", description = "{name}, geht noch einmal dort hin!\n\nDer Anführer von Kolramas, Malas der Verderber, steht ganz oben auf der abgestürzten Nekropole.\n\nTötet ihn und bringt mir seinen Kopf!", sourceObjective = "Unteroffizier Mondsplitter in Drak'Sotra besteht darauf, dass Ihr ihm den Kopf des Verderbers bringt.", progress = "Ich freue mich schon darauf, seinen Kopf auf einen Spieß zu stecken. Dann soll er mal sehen, wie er sich davon wieder erholen will!", completion = "Ihr seid der Held der Stunde, {name}.\n\n\n\nIhr verdient unseren tiefsten Respekt und mehr als das, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12555] = { id = 12555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wirrgespinst", description = "Fertig! Ein Wirrgespinstwerfer, der nur so darauf wartet, dass Ihr mit ihm die Seuchensprüher vom Himmel holt.\n\nIhr müsst nur zielen und feuern. Das Gewebe sollte ihre Schwebezauber lange genug blockieren, um sie genauso wie Kolramas zum Absturz zu bringen.\n\nIrgendwie poetisch. Ich mag das!", sourceObjective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr mithilfe des Wirrgespinstwerfers 5 Seuchensprüher zerstört.", completion = "Juhu! Ihr seid der Beste, {name}!\n\nIch habe mich nicht wirklich danach gesehnt, von dem Geißelzeugs besprüht zu werden, so viel steht fest! Ich schätze mal, dass es diesen dummen Nerubern jetzt schwer fallen wird, ihr Böses weiterhin zu verbreiten!\n\nWie wär's, wenn ich Euch etwas dafür gebe, dass Ihr meine Haut gerettet habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[12556] = { id = 12556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Rhinozerosjagd: Der Todesstoß", description = "Nun, da wir wissen, wo wir Farunn finden können, bleibt uns nur noch der Kampf gegen diese edle Kreatur. Seid Ihr bereit, Euch diesem Rhinozeros zu stellen, {name}? So, wie der Geist tobte, bin ich mir sicher, dass er die Wahrheit über die Stärke des Tiers sagte.\n\nWenn Ihr bereit seid, ihm entgegenzutreten, dann geht nach Norden vorbei an der Sonnenstrahlsäule und sucht nach Farunn am Nordostufer des Bittertidensees. Womöglich hält er sich aber auch an der Schimmersäule auf. Bringt sein Horn zurück, um Eures Sieges zu gedenken.", sourceObjective = "Bringt Farunns Horn zu Hemet Nesingwary in Nesingwarys Basislager.", progress = "Habt Ihr die wilde Kreatur getötet?", completion = "<Hemet untersucht das Horn.>\n\nEine wundersame Trophäe von einem erstaunlichen Tier! {name}, mir sind Gerüchte über sogar noch größeres, grimmigeres Wild in den nördlichen Regionen des Beckens zu Ohren gekommen und ich hätte gerne, dass Ihr uns dabei helft, es aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12557] = { id = 12557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laborarbeit", description = "Die Tatsache, dass Ihr mich unterbrecht, lässt mich darauf schließen, dass Ihr unter denjenigen sein möchtet, die ich für eine Lehrstelle in Erwägung ziehe.\n\nEin lobenswertes Bestreben...\n\nSollte ich eines Tages Eurem Gesuch entgegenkommen, muss ich sicher sein, dass Ihr Euch in meinem Labor auch auskennt. Hier gibt es viele Reagenzien und Zutaten; einige gibt es in Hülle und Fülle, andere wiederum ganz und gar nicht.\n\nLasst Euch Zeit, {class}. Sucht nach einer schlammigen Moormade, einem getrockneten Fledermausflügel, einem Bernsteinsamen und nach ein wenig gekühltem Schlangenschleim.\n\nFindet diese Zutaten und ich werde wissen, dass Euer Anliegen ernst zu nehmen ist.", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr in sein Labor geht und ihm eine schlammige Moormade, einen getrockneten Fledermausflügel, einen Bernsteinsamen und ein wenig gekühlten Schlangenschleim beschafft.", progress = "Habt Ihr Euch schon an mein Labor gewöhnt, {class}?", completion = "Ja, ja, das ist ein guter Anfang.\n\nSollte Ich Euch dazu auffordern, mir bei einem echten Rezept zu helfen, dann werdet Ihr die Zutaten recht zügig finden müssen.\n\nMerkt Euch das, {class}.\n\nLebet wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[12558] = { id = 12558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Schreckenssäblerjagd: Bereit zum Angriff", description = "Shango wartet, {name}. Wenn Ihr bei Eurer Spurensuche erfolgreich wart, dann wird er nicht wissen, dass Ihr ihn verfolgt - und Ihr braucht diesen Vorteil.\n\nEr soll größer, stärker und wilder als alle anderen Schreckenssäbler des Beckens sein. Reist nach Norden, zum Westufer des Bittertidensees und nahe der Wasserfälle, die ihn speisen, und kämpft mit Shango. Kehrt nach Eurem Sieg mit dem Pelz zurück.", sourceObjective = "Bringt Shangos Pelz zu Buck Cantwell in Nesingwarys Basislager.", progress = "Habt Ihr Euch Shangos angenommen?", completion = "Was für ein exquisiter Pelz von solch einem noblen Tier! Es ermutigt mich, dass die Gerüchte über Shango tatsächlich wahr waren, {name}. Eure Jagd auf diese Kreatur war makellos. Ihr seid ein wahrer Jäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[12559] = { id = 12559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladen des Tors - Hort der Schöpfer", description = "Es ist nun also soweit. Lasst uns das Tor aktivieren.\n\nIhr findet den ersten Schalter im Hort der Schöpfer, am westlichen Rand des Beckens.\n\nHütet Euch, {name}. Die Titanen nutzten den Hort, um ihre Werke zu überwachen. Viele ihrer Steindiener bewachen diesen Ort nach wie vor.", sourceObjective = "Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr Euch zum Hort der Schöpfer begebt und den Aktivierungsschalter Gamma betätigt.", progress = "Ihr seid zurück, kleines Wesen. Ich begann, mich um Euer Wohlergehen zu sorgen.", completion = "Wir haben die Hälfte geschafft, {name}. Ein weiterer Schalter muss aktiviert werden, ehe wir den Etymidian erlangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12560] = { id = 12560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Krokiliskenjagd: Der Plan", description = "Der Mangalkrokilisk ist ein Meister des Hinterhalts und ich habe vor, bei dieser Großwildjagd die Besten diesbezüglich zu übertreffen. Daher müssen wir für Euch eine überzeugende Tarnung zusammenstellen. Wir werden Pflanzen verwenden, die im sandigen Boden der Fluss- und Seeufer wachsen.\n\nDer Sandfarn ist am besten für unsere Zwecke geeignet; er wächst im sandigen Gebiet nahe der Ufer des Meeresklammstroms genau südlich von hier, am Bittertidensee und bei den Bittertidenfällen im Norden sowie an den Rändern des Flussnabels, dem großen See jenseits des Mangal im Osten.", sourceObjective = "Bringt Debaar in Nesingwarys Basislager 5 Sandfarnwedel.", progress = "Bringt Ihr mir alle Farne, die wir brauchen?", completion = "<Debaar nimmt die Sandfarnwedel und beginnt, sie um Euren Körper zu binden.>\n\nJa, das sollte funktionieren. Haltet still! Wir wollen doch einen Busch aus Euch machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12561] = { id = 12561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vertrauensfrage", description = "Das hätte niemals passieren dürfen. Die untoten Streitkräfte erstürmen die Wiege des Lebens!\n\nWenn Ihr nicht hier seid, um die Diener des Lichkönigs zu vernichten, dann verlasst diesen Ort sofort. Lenkt mich nicht von meinen Pflichten ab, wenn Ihr nicht meinen Zorn auf Euch ziehen wollt.", sourceObjective = "Gewinnt Freyas Vertrauen, indem Ihr 6 verseuchte Leichname und 10 Knochensensenverheerer in den Verlorenen Landen vernichtet.", progress = "Vergeudet nicht meine Zeit, Sterblicher. Die Kreationen der Titanen müssen verteidigt werden!", completion = "Also gut, {race}. Ich bin zufrieden, dass Ihr nicht einer von des Lichkönigs Dienern seid... vielleicht gibt es doch etwas, das Ihr für uns tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12562] = { id = 12562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drakkari brauchen keine Wasserelementare!", description = "Unsere Spione berichten uns, dass, seitdem diese Wasserelementare auf den Feldern von Drak'Sotra aufgetaucht sind, sich eine Anzahl von Schamanen der Drakkari von den höheren Bereichen Zul'Draks dort eingefunden hat, um die Kontrolle über sie zu erlangen.\n\nIch kann nicht genug betonen, <Herr/holde Dame>, welche Gefahr dies für uns darstellen könnte. Wir wollen auf keinen Fall, dass ihnen Wasserelementare zur Verfügung stehen.\n\nDer Hauptmann hat befohlen, dass diese Wasserbinder der Drakkari die Klinge zu spüren bekommen sollen. Geht in Richtung Süden, wenn Ihr bereit seid.", sourceObjective = "Unterleutnant Jax in der Argentumwache möchte, dass Ihr 10 Wasserbinder der Drakkari tötet.", completion = "Ausgezeichnete Arbeit, mein Herr!\n\nIch werde mich darum kümmern, dass der Hauptmann über Eure Missionsresultate in Kenntnis gesetzt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12563] = { id = 12563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille", description = "Zieht Eure Waffe, {race}. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", sourceObjective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok.", completion = "Nun ja, {name}, zumindest habt Ihr es in einem Stück wieder zurückgeschafft. Ich vermute mal, dass das schon etwas wert ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12564] = { id = 12564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Etwas gegen die Schmerzen", description = "So tapfer meine Männer auch sein mögen, sie sind noch immer sterblich.\n\nWunden und Schmerz vermindern Ihre Fähigkeit, ihre Missionen durchzuführen. Diese natürliche Sache kann nicht geändert werden, egal wie viel man trainiert.\n\nGlücklicherweise hat einer unserer Alchemisten ein Rezept für eine Salbe entwickelt, die auf unsere Bandagen geschmiert werden kann und den Schmerz unserer Soldaten erheblich lindert.\n\nFür die Salbe benötigt man eine besondere Mohnblume, die von den Trollen gleich westlich von hier angebaut wird. Geht zu den Feldern von Drak'Sotra und sammelt ein paar von ihnen, bevor unsere Vorräte zu Ende gehen.", sourceObjective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt.", progress = "Habt Ihr den Wassermohn gesammelt, {name}?", completion = "Ausgezeichnete Exemplare, {name}.\n\nIm Namen meiner Soldaten möchte ich mich bei Euch bedanken.\n\nHauptmann Rupert wird wahrscheinlich der nächste Halt auf Eurer Patrouille sein. Er ist an der Wand gleich östlich von hier stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12565] = { id = 12565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Abwa", description = "Es macht mir Mut zu sehen, mit welchem Eifer sich der Argentumkreuzzug der Geißel entgegenstellt, {race}. Ich würde Euch gerne in dieser Sache unterstützen.\n\nDie Drakkaritrolle dieser einst prächtigen Stadt brachten ihren Göttern regelmäßig Opfergaben dar. Heute jedoch werden sie von den Drakkari vernachlässigt oder müssen Schlimmeres erfahren.\n\nFalls Ihr den Göttern etwas opfern solltet, würden sie sich dafür erkenntlich zeigen.\n\nZim'Abwas Statue befindet sich gleich gen Südwesten. Zim'Abwa würde Eure Gaben, die Drakkariartefakte, dankbar entgegennehmen und Euch somit für einen Beschützer von Zul'Drak halten.", sourceObjective = "Verhexer Ubungo in der Argentumwache möchte, dass Ihr der Statue von Zim'Abwa 10 Drakkariopfergaben darbringt.", progress = "<Zim'Abwa starrt gen Norden und Süden. Sein Blick ist unergründlich.>", completion = "<Wenn Zim'Abwa der Mimik fähig wäre, dann würde er ein böses Grinsen aufsetzen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12566] = { id = 12566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für das Lager der Winterhufe", description = "Ich bin Fernläufer Nanik von den Taunka und wurde vom Häuptling des Lagers der Winterhufe ausgesandt, um Verbündete für den Kampf gegen die Vrykul zu gewinnen. Sie sind westlich und südlich unseres Dorfes aufmarschiert; doch obwohl wir für jeden unserer Toten Zehn von ihnen erschlagen, können wir nicht standhalten.\n\nApotheker Scyllis hat uns versprochen, zu unserer Unterstützung viele mutige <Helden/Heldinnen> wie Euch nach Nordosten zu entsenden. Werdet Ihr meinem Volk dabei helfen, die Angriffe der Vrykul abzuwehren?\n\nFolgt der Straße nach Nordwesten und überquert den Fluss. Das Lager der Winterhufe liegt im Vorgebirge.", sourceObjective = "Sprecht mit Häuptling Aschtotem im Lager der Winterhufe.", completion = "So, so, Nanik hat also Hilfe gefunden? Sagt mir, {name}, wie kommt es, dass Ihr ohne ihn hierher gefunden habt? Niemand kennt dieses Land besser als die Taunka.", sourceObjectiveStatus = "unverified-source-field" }
quests[12567] = { id = 12567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Abwa", progress = "<Ihr habt das Gefühl, als würde Zim'Abwas steinernes Antlitz durch Euch durch und in Eure Seele blicken.\n\nZim'Abwa ist erfreut, möchte jedoch, dass Ihr ihm mehr Dankbarkeit und Respekt entgegenbringt, indem Ihr ihm mehr Drakkariopfergaben darbringt.\n\nEr wird Euch angemessen belohnen.>", completion = "<Ihr spürt Zim'Abwas Zustimmung. Aus irgendeinem Grund wisst Ihr, dass Zim'Abwa mehr Tribut verlangt!>" }
quests[12568] = { id = 12568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: todsicher gehen", description = "Glaubt mir, {race}. Ich weiß...\n\nDer ständige Gestank von verbranntem Fleisch macht selbst mich krank - mich, einen Verlassenen. Nichtsdestotrotz ist es unsere heilige Pflicht, dafür zu sorgen, dass unsere Brüder niemals Teil der Geißel werden.\n\nGießt dieses Öl über die Leichen unserer Gefallenen, um sicherzugehen, dass wir ihnen auf dem Schlachtfeld nicht als Feinde begegnen müssen.", sourceObjective = "Hauptmann Rupert möchte, dass Ihr das einäschernde Öl über 5 besiegte Argentumfußsoldaten gießt.", completion = "Habt Dank, {name}.\n\nEs ist zwar nicht die glorreichste Aufgabe, die es auf dem Schlachtfeld zu tun gibt, doch getan werden muss sie. Eure Unterstützung wird in meinem Bericht erwähnt werden.\n\nHauptmann Grondel wird höchstwahrscheinlich in nordöstlicher Richtung auf Euch warten, gleich außerhalb des Amphitheaters.", sourceObjectiveStatus = "unverified-source-field" }
quests[12569] = { id = 12569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Krokiliskenjagd: Der Hinterhalt", description = "Der größte Krokilisk im Becken, aufgrund seines Geschicks zum Hinterhalt landläufig bekannt als \"Buschräuber\", sonnt sich gerne im flachen Wasser des Flussnabels. Das ist der große See in der Mitte des Beckens, östlich unseres Lagers.\n\nIch möchte, dass Ihr die Tarnung nehmt, die ich vorbereitet habe, und Euch am Westufer des Flussnabels versteckt, um Buschräuber aufzulauern und dann zuzuschlagen, sobald er sich zeigt. Bringt mir seinen mächtigen Kiefer zurück, falls es Euch gelingt, ihn zu überwältigen.", sourceObjective = "Bringt Buschräubers Kiefer zu Debaar in Nesingwarys Basislager.", progress = "Hat der Plan geklappt?", completion = "<Debaar hört zu, während Ihr das Versagen der Tarnung beschreibt.>\n\nWas meint Ihr damit, dass unser Plan nicht so geklappt hat wie geplant?\n\nNun, zu Eurer Ehre habt Ihr es immerhin geschafft, ihn zu töten. Seht Euch die Größe dieses Kiefers an! Hemet wird stolz darauf sein, was wir geleistet haben. Dieser Krokilisk war wahrhaftig ein Monstrum.", sourceObjectiveStatus = "unverified-source-field" }
quests[12570] = { id = 12570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glückliche Missverständnisse", description = "Tut leid! Ich nicht wollen dir Ärger machen!\n\n<Das verwundete Orakel starrt Euch eine Weile lang leer an.>\n\nDu mich retten! Wir danken. Wir gehen zurück zu Dorf jetzt. Du auch kommen... du bei uns bleiben können! Wauwaumenschen irgendwie immer gemein.\n\nMir sagen, wenn fertig zum Aufbruch, ja?", sourceObjective = "Geleitet das verletzte Orakel der Regenrufer sicher zum Baldachin der Regenrufer und sprecht mit dem Hochorakel Soo-say.", completion = "Du uns helfen? Du dann willkommen, Trockenhaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[12571] = { id = 12571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mach böse Schlangen fort", description = "Wir lange hier vor Wauwaumenschen. Das hier sehr heiliger Ort - wir nicht werden gehen.\n\nDu aussehen, als ob vielleicht gut sein, aber Lafoo bleiben bei dir nur für alle Fälle. Du verstehst, denken wir.\n\nGibt Schlangendinger, die versuchen, unsere Jungen zu essen. Geh mit Lafoo und mach, dass sie aufhören, ja? Besonders großes Ding nahe Wasserfall im Nordosten.", sourceObjective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Giftspitze und 10 Kaiserkobras tötet.\n\nWenn Ihr Lafoos Käfertasche verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Schlangen weg?\n\nGut, {race}. Wir dir danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[12572] = { id = 12572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götter wollen Glitzerglitzer", description = "Soo-say sagt zu uns, wir mit dir gehen. Du nett sein, okay?\n\nOoh, ooh! Wir wissen! Wir können Soo-say glücklich machen, wenn wir mehr Opferdinge zum Schrein bringen! Wir nicht müssen weit gehen, es um Dorf herum immer Sachen zum Ausgraben geben... du suchen einfach nach Funkeln in Erde!\n\nGehen wir! Gehen wir! Mehr Opferdinge für Schrein!", sourceObjective = "Sammelt 6 von den Schätzen, die Lafoo ausgräbt, und bringt sie zum Hochorakel Soo-say auf dem Baldachin der Regenrufer.\n\nSprecht mit dem Hochorakel Soo-say auf dem Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet.", progress = "Hallo Trockenhaut. Du mit Lafoo gut auskommen?", completion = "Glitzerglitzer für den großen Regenstein! Gut! Gut!\n\nWir diese gleich vor den Altar legen. Lafoo daran gedacht haben, ja? Er sein ein sehr kluger Regenrufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12573] = { id = 12573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden schließen", description = "Wir haben großartige Idee. Du waren Freund mit Wauwaumenschen, vielleicht sie auf dich hören.\n\nWir wollen, dass du geben Opferdinger zu Schamane Vekjik. Er im Südwesten, wo Fluss zu Wasserfall wird. Sag Wauwaumann, dass wir nicht wollen kämpfen. Sag ihm, wir jetzt nett.\n\nDu gut, {race}. Wir wissen, dass du das richtig machen.", sourceObjective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Schamanen Vekjik ein Friedensangebot unterbreitet und anschließend mit seiner Antwort wieder zurückkehrt.\n\nSprecht mit dem Hochorakel Soo-say im Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet.", progress = "Wauwaumenschen sind jetzt nett zu uns?", completion = "So gemein! Wir sind nur nett und sie sind nur gemein.\n\nSie spielen immer mit großen Steinen rum... vielleicht sie nicht wissen, dass große Steine heilig.", sourceObjectiveStatus = "unverified-source-field" }
quests[12574] = { id = 12574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon zurück?", description = "<Das Hochorakel Soo-say starrt eine Weile auf Eure Stirn, bevor er zu sprechen beginnt.>\n\nSoo-gan nach Hilfe fragen. Wir glauben, sie vielleicht wieder von den Wauwauleuten angegriffen.\n\nWir dich und Jaloot schicken, um zu helfen... Folgen dem Fluss westwärts bis zu Zuflucht der Nebelflüsterer. Tun, was Soo-gan sagen... Wauwauleuten auf die Nase hauen, wenn sie werden böse, sie das nicht mögen.\n\n<Das Hochorakel Soo-say beginnt, wieder auf Eure Stirn zu starren, als Ihr ihn verlasst.>", sourceObjective = "Reist zur Zuflucht der Nebelflüsterer und sprecht mit Nebelrufer Soo-gan.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Wir glauben, dich schon mal gesehen. Du Nebelflüstererdorf schon einmal besucht?\n\nSoo-say sagt, du gut. Soo-say schlau, also wir dir auch trauen.\n\n<Nebelrufer Soo-gan schenkt Euch ein unbeholfenes, breites Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12575] = { id = 12575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schatz der Nebelflüsterer", description = "Also ein paar Wauwaumenschen kommen und zerschlagen blaue Kristalle am großen Nebelstein! Viel Regen und Blitz und Böses... blau ist falscher Kristall für großen Nebelstein! Dumme Wauwaumenschen.\n\nNach Blitz Wauwaumenschen gestohlen großen Schatz, wir im See gefunden. Wir brauchen Schatz zurück, um dem großen Nebelstein zu geben! Nebelstein ist wütend, nach dem, was die Wauwaumenschen getan!\n\nEiner von denen, die stehlen, heißt Tarter... nein, Tiktak... nein, nein... Tartek. Das es ist: Tartek! Er ging zum Lagerding im Norden. Geh' und hol' Schatz zurück!", sourceObjective = "Tötet Kriegsfürst Tartek und bringt den Schatz der Nebelflüsterer für Soo-gan in der Zuflucht der Nebelflüsterer zurück.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Dumme Wauwaudiebe.", completion = "Du es geschafft! Du stark und nett! Gut Freund von Nebelflüsterern!\n\n<Nebelrufer Soo-gan zeigt ein großes, zähnereiches Grinsen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12576] = { id = 12576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit harter Hand", description = "Wir versuchen, nett zu Wauwaumenschen sein, seit sie ankamen, aber sie einfach nur gemein.\n\nUns egal, dass sie dumm - sie nicht viel Schaden machen. Jetzt sie aber heilige Schreine verwüstet. Heilige Schreine nicht zum Verwüsten da. Große Steine hier, seit uns die Großen vor langer, langer Zeit erschaffen.\n\nWir nicht wüssten, was zu tun, wenn große Nebelsteine zerstört. Geh zu ihrem Lager im Norden... mach, dass Wauwaumenschen aufhören und nicht zurückkommen!", sourceObjective = "Tötet 8 Speerträger der Wildherzen und 6 Strauchdiebe der Wildherzen für Nebelrufer Soo-gan in der Zuflucht der Nebelflüsterer.\n\nWenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", completion = "Du gut zuschlagen. Danke für helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12577] = { id = 12577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hausezeit!", description = "Du gute Trockenhaut. Nebelflüsterer sicher, Schatz sicher und Wauwaumenschen uns jetzt auf jeden Fall in Ruhe lassen.\n\nDu gehen zurück zu Baldachin der Regenrufer und sagen Soo-say, du gute Arbeit gemacht.", sourceObjective = "Kehrt zum Baldachin der Regenrufer zurück.", completion = "Du schon so bald zurück!\n\nGut gelaufen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12578] = { id = 12578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wütende Gorloc", description = "Ich nicht glaube, dass du rechzeitig zurück, um wieder zu gehen, aber ich falsch. Ich sende Moodle zu nahen Mooswandlerfreunden, um dumme Mooswandler zu knuffen, weil nicht kommen Schrein sehen. Ihr Dorf ist östlich, den Hügel hoch, nordöstlich von kaputter Säule.\n\nDu gehst mit Moodle! Er besonders schlauer Regenrufer... du ihm gut zuhören.", sourceObjective = "Reist ins Mooswandlerdorf und sprecht gleich nach Eurer Ankunft mit Moodle.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Soo-say ist etwas ungeschickt, aber nicht dumm. Ich denke allerdings, dass er viel zu schnell vergibt... die Wauwaumenschen werden nicht einhalten oder uns in Frieden lassen. Der einzige Weg, sie aufzuhalten, ist, sie zu töten... es gibt keinen \"Frieden\".\n\n<Moodle drückt die Brust raus und deutet auf sich selbst.>\n\nDarin bin ich gut.", completion = "Bevor Ihr etwas sagt, haltet mich nicht für so töricht wie die meisten Orakel, die Ihr getroffen habt. Ich war ein wenig in der Welt unterwegs, ich habe Eure Sprache gelernt und ich lasse mich nicht so schnell überlisten.\n\nIch wusste bereits vor unserer Ankunft, dass die Mooswandler tot sind, obwohl ich nicht ahnte, dass dahinter die Untoten steckten.\n\nSie dürften gar nicht in der Lage sein, dieses Land zu betreten... die Zerstörung der Lebensblutsäule muss es ihnen irgendwie gestattet haben. Wir müssen dafür sorgen, dass sie verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12579] = { id = 12579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensblut des Mooswandlerschreins", description = "Ich habe schon immer vermutet, dass die Säulen die Hauptursache für unser Wetter und die Abgeschiedenheit von den Untoten sind... das gibt mir ein wenig Bestätigung.\n\nVor nicht allzu langer Zeit hörten wir, wie die Lebensblutsäule in einer großen Explosion umkippte. Das Wetter änderte sich fast schlagartig für die Mooswandler... Es begann zu schneien, etwas, das wir nie zuvor erlebt hatten.\n\nIndem sie mehr Lebensblutkristalle zum großen Moosstein brachten, gelang es ihnen, das Schneien zu beenden. Wenn wir ebenso verfahren, hilft es vielleicht auch dabei, die Untoten fernzuhalten.", sourceObjective = "Moodle möchte, dass Ihr 10 Lebensblutscherben sammelt, aber haltet Euch von der Höhle innerhalb der Säule selbst fern.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Die Mooswandler waren gute Leute... sie verdienten all das nicht.", completion = "Womöglich ist es zu spät, um noch etwas mit den Scherben zu ändern, aber unsere Möglichkeiten sind eben begrenzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12580] = { id = 12580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retter der Mooswandler", description = "Es besteht die schwache Hoffnung, dass die Mooswandler noch nicht alle tot sind... und sie verdienen es bei Weitem nicht, derart abgeschlachtet zu werden.\n\nLasst uns Rache nehmen für dieses Blutbad und sehen, ob wir dabei noch einige von ihnen retten können.", sourceObjective = "Moodle möchte, dass Ihr 6 Mooswandleropfer im Mooswandlerdorf rettet, obwohl manche von ihnen vielleicht bereits nicht mehr länger leben.\n\nWenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer.", progress = "Ich wünschte, ich hätte früher gewusst, wie wichtig die Säulen und Steine sind... vielleicht hätte ich dies verhindern können.", completion = "Ich bin sehr froh, dass einige gerettet werden konnten... mit ein wenig Glück kehren sie sicher zum Baldachin der Regenrufer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[12581] = { id = 12581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bürde eines Helden", description = "Vielleicht wehren die Kristalle die Untoten allmählich ab, aber es gibt immer noch eine Sache, die erledigt werden muss.\n\nWir müssen den Anführer dieser Untoten aufspüren und töten, um sicherzugehen, dass niemand diese Ungeheuer zu uns zurücktreibt. Wenn ich richtig vermute, hält er sich irgendwo innerhalb der umgestürzten Säule, der Versprengten Scherbe, auf.\n\nDie dorthin verschleppten Leichen deuten jedenfalls darauf hin.\n\nIch platziere die Splitter und informiere Soo-say. Um den Rest müsst Ihr Euch kümmern.", sourceObjective = "Tötet Artruis den Herzlosen.\n\nMoodle wird Euch bei dieser Aufgabe nicht begleiten können.", progress = "<Das Phylakterium ruht bedrohlich neben Artruis' toter Hülle auf dem Boden.>", completion = "<Innerhalb von Artruis' Phylakterium erkennt Ihr etwas, das wie endlose Leere wirkt... und Ihr glaubt, von irgendwo dort drin Schreie aus der Ferne zu vernehmen.>\n\n<Als Ihr gerade gehen wollt, seht Ihr, wie ein Objekt in die Leere gleitet, knapp außer Reichweite.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12582] = { id = 12582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Wildherzen", sourceObjective = "Ich wusste, du bist kein Verräter, wie die anderen behaupten. Wir zusammen gejagt... Ich dich kennen besser als alle anderen. Danke, dass du mich gerettet.\n\nVielleicht klingt komisch... ich Großzungen nicht besonders mögen... aber selbst ich fühle schlecht, weil Großzunge so gestorben... sie gut genug kämpfen, um gerechten Kampf zu verdienen.\n\nDu wieder willst Freund mit Wildherz sein? Ich glaube, ich kann sie überzeugen, dass du mich gerettet und es den Großzungen gut gegeben. Ich aber nicht möchte, dass du mich dumm dastehen lässt - du also sicher, dass du nichts mehr mit Großzungen zu tun haben willst?", sourceObjectiveStatus = "unverified-source-field" }
quests[12583] = { id = 12583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgestürzter Seuchensprüher", description = "Ich weiß, dass einer dieser Seuchensprüher irgendwo in Drak'Sotra westlich von uns abgestürzt ist.\n\nSeht doch einmal nach, ob Ihr die Stelle finden könnt. Ich kann die Teile des Sprühers dazu benutzen, um ein Gerät herzustellen, mit dem wir diese Dinger vom Himmel holen werden!", sourceObjective = "Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr Seuchensprüherteile sammelt.", progress = "Habt Ihr die Teile? Hm? Habt Ihr sie?", completion = "<Die Spezialistin weicht einen Schritt zurück, als sie die Teile sieht.>\n\nBäh, die Dinger sind einfach nur widerwärtig!\n\nOkay, okay, gebt sie mir und ich werde sehen, was sich machen lässt. Ich hätte Euch wahrscheinlich zuerst zu einem Priester schicken sollen, damit er die Dinger läutert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12584] = { id = 12584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das pure Böse", description = "Wir wissen, dass Kolramas, die abgestürzte Nekropole gen Südosten, eine große Menge Erz namens Saronit an Bord gehabt hat, als die Trolle sie vom Himmel holten.\n\nMeine Späher berichten mir, dass allerlei Saronit im Inneren des Dings herumliegt.\n\nEtrigg und seine Freunde drüben in der Argentumwache brauchen eine Ladung von dem Zeugs für ihre Forschungen.\n\nIch möchte also, dass Ihr dort hineingeht und nachseht, ob Ihr genug für sie sammeln könnt.", sourceObjective = "Hauptmann Rupert möchte, dass Ihr 10 Brocken Saronit einsammelt und sie anschließend zu Etrigg in der Argentumwache bringt.", progress = "Ja, {class}?\n\nSagt mir bitte, dass Ihr das Saronit, das wir bei Hauptmann Rupert beantragt haben, dabei habt.", completion = "Könnt Ihr das pure Böse dieses Zeugs spüren?\n\nWir müssen den Sachverstand und die Magien, die uns zur Verfügung stehen, gemeinsam mit der Macht des Heiligen Lichts dazu einsetzen, um den Schleier der Bosheit, der dieses verdorbene Erz umgibt, zu durchdringen. Wir müssen seinen Ursprung erkunden.\n\nSchnell, gebt mir das Saronit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12585] = { id = 12585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Annehmlichkeiten", description = "Tja, es ist nicht gerade glamourös, muss aber gemacht werden.\n\nMeine Truppen haben sich die Seele aus dem Leib gekämpft, während sie tagelang knietief in abgestandenem Wasser standen. Das kann einfach nicht gut für einen sein.\n\nWas sie brauchen ist ein warmes Feuer, um sie trocken zu bekommen und ihre Stimmung zu bessern.\n\nIn diesem Teil der Stadt gibt es nichts, das trocken bleibt, doch die toten Wurzeln dieser Dornholzbäume sind irgendwie gegen die Feuchtigkeit resistent.\n\nBesorgt uns etwas Brennholz und wir werden Euch mächtig dankbar sein.", sourceObjective = "Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt.", progress = "Habt Ihr das Holz für das Feuer, {race}?", completion = "Sehr nett von Euch, {name}. In der Tat: sehr nett.\n\nNun, Ihr werdet Hauptmann Arnath westlich von hier finden, die Anhöhe hoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12586] = { id = 12586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game" }
quests[12587] = { id = 12587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille", description = "Zieht Eure Waffe, {race}. Es ist Zeit, auf Patrouille zu gehen!\n\nIch habe vier Posten unter meinem Kommando und es ist äußerst wichtig für unser Gelingen, dass sie das auch bleiben. Ich befehle Euch, bei jedem dieser Posten vorbeizuschauen und Eure Hilfe anzubieten.\n\nIhr könnt mit Hauptmann Brandon südöstlich von hier beginnen. Er wird Euch den nächsten Posten weisen, wenn er keine Verwendung mehr für Euch hat.\n\nMeldet Euch wieder bei mir zurück, sobald Ihr jedem meiner Männer zur Hand gegangen seid. Und vergesst nicht: Je eher Ihr wieder zu mir zurückkommt, umso reicher werdet Ihr belohnt werden - legt Euch also ins Zeug!\n\nWegtreten!", sourceObjective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok.", completion = "Nun ja, {name}, zumindest habt Ihr es in einem Stück wieder zurückgeschafft. Ich vermute mal, dass das schon etwas wert ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12588] = { id = 12588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Könnt Ihrs aushalten?", description = "Einer unserer Trupps ist während der letzten Offensive über eine alte Schatzkarte gestolpert. Falls das, was auf der Karte eingezeichnet ist, stimmt, dann gibt es hier in der Nähe unbezahlbare Trollartefakte.\n\nMeine Soldaten haben die Drakkari und gleichzeitig auch die Geißel am Hals - haben also alle Hände voll zu tun. Ich möchte, dass Ihr diese Sache genauer untersucht.\n\nNehmt diese Schaufel; Ihr werdet sie für die lockeren Erdhaufen im Südwesten benötigen. Kehrt wieder zu mir zurück, nachdem Ihr die Gegend gründlich durchsucht habt.", sourceObjective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr mit dem Stahlspaten in den uralten Erdhaufen in der Nähe herumgrabt, um das uralte Relikt der Drakkari zu finden.", completion = "Danke, dass Ihr Euch die Sache für mich angesehen habt, {name}. Eure Unterstützung wird in meinem Bericht Erwähnung finden.\n\nAls Nächstes solltet Ihr wahrscheinlich Hauptmann Rupert aufsuchen - er ist östlich von hier an der Mauer stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12589] = { id = 12589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, was für'n Kick?", description = "Also Ihr denkt, Ihr könnt schießen?\n\nNun, dann wollen wir mal sehen. Hier, wir geben Euch für den Anfang etwas Nettes und Harmloses. Keine Sorge, sie hat überhaupt keinen Rückstoß. Vergesst nicht, das Gewehr auf nichts zu richten, auf das Ihr nicht schießen wollt.\n\nWenn Ihr bereit seid, zielt einfach mal auf den Apfel auf'm Kopf von Wilhelm dem Glückspilz und dann lasst se fliegen!", sourceObjective = "Schießt mit dem RJR-Gewehr den Apfel vom Kopf von Wilhelm dem Glückspilz und sprecht dann mit Drostan.", progress = "Zufrieden mit dem Ergebnis?", completion = "Kein schlechter Schuss, aber mit ein bisschen Übung werdet Ihr noch besser werden. Was haltet Ihr von einer kleinen Wette?", sourceObjectiveStatus = "unverified-source-field" }
quests[12591] = { id = 12591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Werfen", description = "Clever...\n\nGerade, als es so aussah, als würden wir die Sache unter Kontrolle bekommen, haben sie einen Tunnel unter uns durchgegraben und den Schrein eingenommen!\n\nJetzt sind wir zwischen zwei Armeen der Neruber gefangen und unsere Lage wird von Sekunde zu Sekunde schlimmer.\n\nAls Erstes müssen wir sie daran hindern, Verstärkung zu erhalten. Die Tunnel müssen verschlossen werden.\n\nNehmt diese Granaten und werft sie in die Krater im Nordwesten.", sourceObjective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr hocheffektive Granaten in der Nähe von 5 nerubischen Kratern einsetzt.", completion = "Wir sind noch lange nicht über den Berg, doch Euer Einsatz hat geholfen, den Gegner zu verlangsamen.\n\nHauptmann Grondel in Drak'Agal hat wahrscheinlich Arbeit für Euch.\n\nLebt wohl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12592] = { id = 12592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des großen Jägers Wettstreit", description = "Also habt Ihr so was wie 'nen Jägerinstinkt. Ihr schießt nicht übel und Hemet hat Euch auch nicht davongejagt, also muss er Euch in die Jagd einplanen.\n\nWas haltet Ihr von 'nem kleinen Wettkampf, nur Ihr und ich?\n\nHemet und die anderen werden Euch bitten, ihnen bei der Jagd zu helfen. Unterwegs werden wir beide zählen, wie viele ihrer Ziele wir erledigt haben. Naja, das ist nichts, das Ihr mit 'nem Augenzwinkern bewältigen könnt, und Ihr werdet viele verschiedene Kreaturen töten müssen. Waidmannsheil!", sourceObjective = "Tötet 60 Beutetiere, während Ihr Hemet und seinen Kameraden bei der Jagd helft. Kehrt zu Drostan in Nesingwarys Basislager zurück, wenn Ihr Eure 60 getötet habt, um Ergebnisse zu vergleichen.", completion = "So, Ihr gesteht also schon Eure Niederlage ein?\n\n<Drostans Unterkiefer klappt nach unten, als Ihr ihm erzählt, dass Ihr bereits die erforderliche Zahl getötet habt.>\n\nUnmöglich! Wie in ganz Azeroth habt Ihr das geschafft? Ich bin gerade mal bei 58! So knapp!\n\nAber abgemacht ist abgemacht. Ich hab' Euch unterschätzt, {name}, aber Ihr habt Euch den Sieg wirklich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12593] = { id = 12593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Lichkönigs", description = "Alles, was ich bin: Zorn, Grausamkeit, Rache, verleihe ich Euch, mein erwählter Ritter. Ich schenke Euch Unsterblichkeit, auf dass Ihr ein neues dunkles Zeitalter der Geißel einleitet.\n\nSeht die Länder unter uns. Der Scharlachrote Kreuzzug will alles zunichtemachen und die Kapelle des Hoffnungsvollen Lichts stellt sich uns trotzend entgegen - eine Schande für die Pestländer. Sie werden für ihre Frechheit zahlen.\n\nIhr werdet zu meiner Vergeltung. Auf Euren Schritt folgt die Verderbnis. Geht nun und folgt Eurer Bestimmung, Todesritter.", sourceObjective = "Meldet Euch bei Instrukteur Razuvious, sobald Ihr dort seid.", completion = "Ihr habt den Ruf des Lichkönigs vernommen, {class}. Die Zeit, Eurem Meister zu antworten, ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12594] = { id = 12594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollpatrouille: Juckt mich kein bisschen", description = "Von all den Posten, die es gibt, haben sie ausgerechnet den hier für mich ausgesucht.\n\nDer Ort ist von modrigem, fahlem Wasser nur so überflutet, was nun zu einem Paradies für Abwasserelementare geworden ist!\n\nIch weiß nicht wirklich, was sie sind oder wieso sie hier sind, und um ehrlich zu sein, juckt es mich kein bisschen. Was ich weiß, ist, dass sie aus meinem Sektor einen Saustall machen! Wie soll ich nur irgendeine militärische Operation mit Würde durchführen können, wenn diese Dinger hier umherstreifen?\n\nGeht hinaus, {class}, und kommt nicht eher wieder zurück, bis Ihr Euren Anteil dieser Schmutzfinken von meinem Schlachtfeld entfernt habt!", sourceObjective = "Hauptmann Grondel möchte, dass Ihr 7 moosbedeckte Amokläufer in Drak'Agal tötet.", completion = "Seid Ihr Euch da sicher, {race}?\n\nFür mich scheint es, als gäbe es jetzt noch mehr von den Dingern als zuvor!", sourceObjectiveStatus = "unverified-source-field" }
quests[12595] = { id = 12595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach größerem Wild", description = "Nun, {name}, Ihr habt auf jeden Fall bewiesen, dass Ihr alles an Tieren jagen könnt, was es so gibt: Rhinozerosse, Katzen und Krokilisken. Für einige Mitglieder dieser Expedition sind diese Kreaturen genug, um an ihnen ihre Jagdkünste zu erproben, doch anderen - wie mir selbst zum Beispiel - verlangt es nach größeren Herausforderungen.\n\nDorian Drachenlauer ist nach Norden gegangen. Er befindet sich jetzt auf der anderen Seite des Bittertidensees und hat dort ein Lager aufgeschlagen. Er hat Gerüchte über gigantische, urzeitliche Drachen gehört. Stellt Euch nur mal vor, was das für eine Beute wäre! Geht und seht mal nach Dorian und findet heraus, ob er Glück gehabt hat.", sourceObjective = "Sprecht mit Dorian Drachenlauer in Dorians Außenposten im Sholazarbecken.", completion = "Der alte Hemet hat mich letztendlich also doch nicht vergessen. Ich nehme an, dass er bei der Jagd mitmachen möchte, nachdem wir die ganze harte Arbeit erledigt haben. Macht Euch keine Sorgen, es sind genug Drachen für alle da. Hemets Wunsch wird erfüllt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12596] = { id = 12596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'trollieren", description = "Willkommen in der Argentumwache, Grünling. Ich bin Kommandant Kunz, doch Ihr, Ihr könnt mich... Kommandant nennen.\n\nDenkt bloß nicht, dass Ihr ohne jemandem Bericht zu erstatten durch meine Gegend ziehen und Eure eigenen Missionen auswählen könnt.\n\nHier, Ihr habt mir Bericht zu erstatten und meine Befehle haargenau zu befolgen. Verstanden?!\n\nZuerst müsst Ihr Euch mit meinen Männern und der Region, die wir säubern sollen, vertraut machen.\n\nMeldet Euch bei jedem von ihnen und tut das, was sie von Euch verlangen. Kehrt anschließend wieder zu mir zurück und Eure Patrouille ist beendet.", sourceObjective = "Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.\n\nHauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra südöstlich von hier stationiert.\n\nHauptmann Grondel ist in Drak'Agal gleich im Osten stationiert.\n\nAlchemist Finkelstein ist in Heb'Valok im Norden stationiert.", completion = "Wurde auch Zeit, dass Ihr Euren Kadaver hierher zurückschleift! Dachte schon, wir hätten Euch an die Geißel verloren - nicht, dass das ein großer Verlust gewesen wäre...\n\nFalls Ihr noch weiterhin dem Kreuzzug dient, dann solltet Ihr Beeindruckenderes liefern.\n\nMerkt Euch das, {race}! Eure zukünftigen Patrouillen werden anhand Eurer Pünktlichkeit belohnt werden.\n\nWegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12597] = { id = 12597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas gegen die Schmerzen", description = "So tapfer meine Männer auch sein mögen, sie sind noch immer sterblich.\n\nWunden und Schmerzen erschweren die Durchführung ihrer Missionen - das ist eine einfache Tatsache des Lebens und keine Ausbildung der Welt wird daran etwas ändern.\n\nGlücklicherweise hat einer unserer Alchemisten ein Rezept für eine Salbe entwickelt, die auf unsere Bandagen geschmiert werden kann und die Schmerzen unserer Soldaten erheblich lindert.\n\nFür die Salbe benötigt man eine besondere Mohnblume, die von den Trollen gleich westlich von hier angebaut wird. Geht zu den Feldern von Drak'Sotra und sammelt ein paar von den Blumen, bevor unsere Vorräte zu Ende gehen.", sourceObjective = "Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt.", progress = "Habt Ihr den Wassermohn gesammelt, {name}?", completion = "Ausgezeichnete Exemplare, {name}.\n\nIm Namen meiner Soldaten möchte ich mich dafür bedanken, was Ihr heute getan habt.\n\nHauptmann Rupert wird wahrscheinlich der nächste Halt auf Eurer Patrouille sein. Er ist an der Wand gleich östlich von hier stationiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12598] = { id = 12598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinunterwerfen", description = "Sehr schlau...\n\nGerade als es so schien, als würden wir die Dinge unter Kontrolle bringen, haben sie sich direkt unter uns hindurchgegraben und den Schrein eingenommen!\n\nNun sind wir zwischen zwei nerubischen Armeen eingeschlossen und unsere Lage verschlimmert sich von Minute zu Minute.\n\nUnsere erste Handlung muss sein, dass wir verhindern, dass sie Nachschub bekommen. Ihre Tunnel müssen versiegelt werden.\n\nNehmt diese Granaten und werft sie in die Tunnel gen Nordwesten.", sourceObjective = "Hauptmann Rupert in Drak'Sotra möchte, dass Ihr die hocheffektiven Granaten in der Nähe von 5 nerubischen Kratern verwendet.", progress = "Habt Ihr die nerubischen Krater schon versiegelt, {name}?", completion = "Wir sind keinesfalls schon aus dem Schneider, doch wir haben erreicht, dass der Gegner langsamer vorankommt.\n\nHauptmann Grondel oben in Drak'Agal wird Euch wahrscheinlich brauchen.\n\nLebt wohl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12599] = { id = 12599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annehmlichkeiten", description = "Tja, es ist nicht gerade glamourös, muss aber getan werden.\n\nMeine Truppen haben sich die Seele aus dem Leib gekämpft, während sie tagelang knietief in abgestandenem Wasser standen. Das kann einfach nicht gut für einen sein.\n\nWas sie brauchen ist ein nettes, gutes Feuer, um sie trocken zu bekommen und ihre Stimmung zu bessern.\n\nIn diesem Teil der Stadt ist alles durchnässt, doch die toten Wurzeln dieser Dornholzbäume sind irgendwie gegen die Feuchtigkeit resistent.\n\nBesorgt uns etwas Brennholz und wir werden Euch mächtig dankbar sein.", sourceObjective = "Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt.", progress = "Habt Ihr das Holz für das Feuer, {race}?", completion = "Sehr nett von Euch, {name}. In der Tat: Sehr nett.\n\nNun, Ihr werdet den alten Finkelstein westlich von hier finden, die Anhöhe hoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12601] = { id = 12601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Alchemisten", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hier hergeschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, {race}. Und merkt Euch: Timing ist alles!", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12602] = { id = 12602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Alchemisten", description = "Ahh, Ihr müsst die angekündigte Patrouille sein. Ihr hättet zu keinem besseren Zeitpunkt eintreffen können. Ich brauche dringend ein extra Paar Hände.\n\nWir halten hier einen Drakkari fest, der zwecks Vernehmung hierher geschickt wurde. Doch bevor diese stattfindet, benötige ich Eure Hilfe, um ein Wahrheitsserum herzustellen.\n\nEin Wahrheitsserum herzustellen ist eine knifflige Angelegenheit, bei der jeder Schritt scharfe Instinkte, ein perfektes Timing und Improvisationstalent verlangt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, {race}. Und merkt Euch: Timing ist alles!", sourceObjective = "Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.\n\nSprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12603] = { id = 12603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen schärfen", description = "Die urzeitlichen Drachen besetzen den Großteil des Gebiets im Norden und Osten und ich fühle selbst auf diese Entfernung hin die Hitze ihres Atems. Bevor wir uns den mächtigsten unter den Drachen stellen können, müssen wir unsere Fähigkeiten an den geringeren erproben.\n\nDoch seid nach wie vor auf der Hut: Jedes dieser Wesen kann einen ganzen Mann verschlingen. Kehrt zu mir zurück, sobald Ihr Euch mit den Kampftaktiken dieser Drachen vertraut gemacht habt, und ich werde Euch unseren nächsten Schritt erklären.", sourceObjective = "Tötet 6 urzeitliche Drachen und sprecht anschließend mit Dorian Drachenlauer in Dorians Außenposten.", completion = "Ich höre die Zuversicht in Euren Worten. Gut, die Erfahrung wird Euch hilfreich sein, wenn wir uns der Königin der Drachen stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12604] = { id = 12604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlichen Glückwunsch!", sourceObjective = "Ihr lagt auf dieser Patrouille hervorragend in der Zeit. Es scheint, als wäret Ihr doch für etwas zu gebrauchen.\n\nHier, wie versprochen, ein kleiner Bonus für Eure Mühen.\n\nMacht weiter so, {name}.\n\nWegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12605] = { id = 12605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Köder sichern", description = "Es ist ziemlich unwahrscheinlich, dass wir Brutmutter Slivinas Aufmerksamkeit erregen werden, wenn wir wie Trottel mit unseren Armen herumfuchteln; doch wenn wir schlau sind, dann können wir sie dazu bringen, uns anzugreifen. Darüber hinaus würden wir auch mehr, ähm, Futter für mein kleines Projekt liefern.\n\n<Dorian wirft einen Blick auf Spleenix.>\n\nMacht Euch jedoch darüber im Moment keine Sorgen. Sucht einfach nach den urzeitlichen Dracheneiern in der Gegend östlich und nordöstlich des Lagers. Zerschlagt sie und fangt die Jungtiere ein, wenn sie aus den Eiern springen. Sobald die Brutmutter dann erst einmal mitbekommt, was wir getan haben, wird sie keine andere Wahl haben, als sich uns zu stellen.", sourceObjective = "Bringt 6 urzeitliche Jungtiere zu Dorian Drachenlauer in Dorians Außenposten.", progress = "Habt Ihr den Köder schon beschafft, den Ihr dazu benötigt, um die Aufmerksamkeit der Brutmutter auf Euch zu ziehen?", completion = "Ah, gut gemacht. Spleenix hat jetzt genug Jungtiere!", sourceObjectiveStatus = "unverified-source-field" }
quests[12606] = { id = 12606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Kokons eingesponnen!", description = "Nun, da die Tunnel versiegelt wurden, werden wir uns als nächstes darum kümmern, diejenigen wieder hierher zu bringen, die in feindliche Hände gefallen sind.\n\nMit etwas Glück sind noch einige unserer Soldaten, die sich in den nerubischen Kokons befinden, am Leben und relativ unversehrt.\n\nBefreit sie, {class}, solange Ihr noch Gelegenheit dazu habt!", sourceObjective = "Hauptmann Rupert möchte, dass Ihr die nerubischen Kokons in Drak'Sotra öffnet und wieder zu ihm zurückkehrt, sobald Ihr 3 gefangene Fußsoldaten befreit habt.", completion = "Die Neruber haben einen hohen Tribut gefordert, {class}.\n\nNichtsdestotrotz bin ich dankbar für das, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12607] = { id = 12607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mammutunternehmen", description = "Dorian dachte, bevor Ihr losgeht und Brutmutter Slivina heraufordert, wäre es vielleicht eine gute Idee, wenn Hemet und Ihr zusammenarbeitet und auf dem Rücken eines Mammuts in die Schlacht zieht.\n\nDie Gegend um das Lager herum ist voll von ihnen. Nehmt einfach dieses Zaumzeug und legt es einem Spaltzahnmammut an. Nehmt Euch jedoch vor den Bullen in Acht. Sie werden das Geschirr auf keinen Fall tragen. Bringt das Mammut hierher zurück, wenn Ihr ein passendes gefunden habt.", sourceObjective = "Bringt ein Spaltzahnmammut zu Spleenix in Dorians Außenposten.", completion = "Perfekt! Das Einzige, was wir nun brauchen, ist, für Hemet eine Trittleiter zu besorgen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12608] = { id = 12608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Kultisten", description = "<Es scheint, als hätte der Avatar von Freya recht. Die Untoten waren nicht in der Lage, das Sholazarbecken zu betreten, bevor die Lebensblutsäule umstürzte. Stattdessen hatten sie ihre lebenden Agenten vom Kult der Verdammten entsandt.>\n\n<Ihr warnt sie besser vor den lebenden Agenten des Lichkönigs im Sholazarbecken.>", sourceObjective = "Sprecht mit dem Avatar von Freya im Katarakt der Regenrufer.", completion = "Die Lebenden... freiwillige Diener des Lichkönigs?\n\nAll diese Zeit habe ich den falschen Feind gesucht, {race}. Lasst uns eilen und die Kultisten in diesen Landen ausmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12609] = { id = 12609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Regale einräumen", description = "Hört zu, {class}. Ich weiß, dass ich damit viel von Euch verlange...\n\nFrisches Spinnensekret ist etwas schwer zu bekommen, sogar in diesen stark verseuchten Regionen. Doch Finkelstein hat gesagt, dass er nicht eher zufrieden ist, bis er nicht weniger als ein ganzes Fass hat, und dass er es schon bald braucht.\n\nIch werde meine Männer weiterhin draußen auf dem Feld Reagenzien sammeln lassen, doch falls die Bestellung des Alchemisten rechtzeitig ausgefüllt werden soll, dann werden sie etwas Unterstützung brauchen.\n\nHaltet nach Falltürkrabblern Ausschau, wenn Ihr auf den Feldern von Zul'Drak seid, und bringt mir alles Sekret, das Ihr finden könnt.", sourceObjective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 Einheiten frischen Spinnensekrets von den Falltürkrabblern in Zul'Drak sammelt.", progress = "Habt Ihr meine benötigten Reagenzien dabei, {class}?", completion = "Diese hier sehen wie ausgezeichnete Proben aus, {name}.\n\nDanke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12610] = { id = 12610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Flügel stutzen", description = "Seitdem Finkelstein hier ist, bin ich dazu verdammt, verschiedene Zutaten für seine Experimente und Rezepte zu sammeln.\n\nIch werde meinem Eid zwar treu bleiben und meine Befehle ausführen, doch ich bin ein erfahrener Veteran! Ich habe an dutzenden Konflikten teilgenommen. Ich wäre viel lieber an der Front, um direkt Einfluss auf den Ausgang des Kreuzzuges zu nehmen.\n\nHelft mir, {race}. Sammelt ein paar Fledermausschwingen, damit ich vielleicht schon eher dort mitmischen kann, wo der eigentliche Kampf stattfindet.", sourceObjective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 makellose Fledermausflügel von den Fledermäusen von Zul'Drak sammelt.", progress = "Habt Ihr die Fledermausschwingen für Finkelstein schon eingesammelt?", completion = "Ausgezeichnete Arbeit, {name}.\n\nIch danke Euch für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12611] = { id = 12611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siebenfach zurückgezahlt", description = "Die Agenten des Lichkönigs haben törichterweise diese Lande betreten, in denen die Macht des Lebens regiert. Jedes Leid, das sie anrichten, soll ihnen siebenfach heimgezahlt werden.\n\nDas unmittelbar für die Verderbnis des Landes verantwortliche Monster nennt sich Thalgran Seuchenbringer; Ihr findet ihn genau nördlich von hier. Nehmt diesen Zauberschutz, um die Macht des Todes auf ihn zurückzuwerfen. Zeigt der Geißel, dass die Macht des Lebens über alles siegt.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr Thalgran Seuchenbringer besiegt, indem Ihr mit Freyas Wall seine Todesblitze siebenfach auf ihn zurückwerft.", progress = "Ist es vollbracht, {name}?", completion = "Ihr erweist Euch weiterhin als würdig, {name}. Womöglich war ich vorschnell, Euch zu verurteilen.\n\nIch nahm an, Ihr wärt gemeinsam mit den Wilderern gekommen, die kürzlich in meinen Landen strandeten, aber vielleicht seid Ihr bereit, dies hinter Euch zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12612] = { id = 12612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestürzte Säule", description = "Die Titanen schufen ganze Lebensformen hier und behüteten ihr uneingeschränktes Wachstum.\n\nDie fünf Kristallsäulen, die das Becken umgeben, strömen reine Lebenskraft aus. Die Geißel hätte niemals in das Becken einfallen dürfen, aber eine der Säulen wurde zerstört.\n\nGeht zur Lebensblutsäule und versucht herauszufinden, was geschah. Kein Untoter hätte sich der Säule nähern können, also haltet die Augen nach lebenden Eindringlingen offen. Ihr findet das, was von der Säule übrig ist, unmittelbar südlich von hier.", sourceObjective = "Reist zur Lebensblutsäule und sucht nach Hinweisen, die auf die Ursache ihrer Zerstörung hinweisen.", completion = "<Die Leiche ist schwer verbrannt. In der Umgebung liegen offensichtlich die Überreste einiger Pulverfässer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12613] = { id = 12613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladen des Tors - Die Warte der Schöpfer", description = "Wir können nun nicht mehr zurück, {race}. Ihr habt den ersten Schalter umgelegt, doch einer verbleibt.\n\nDie Titanen konstruierten einen zweiten günstigen Aussichtspunkt, von wo aus sie ihre Kreationen überwachten. Ihr findet ihn im Osten, hoch oben in den Bergen.\n\nBetätigt den Aktivierungsschalter Theta innerhalb der Warte, um das Tor zu öffnen.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr Euch zur Warte der Schöpfer im Osten des Sholazarbeckens begebt und den Aktivierungsschalter Theta betätigt.", progress = "Ist es vollbracht, {name}?", completion = "Das Tor wurde aktiviert, {name}. Es ist an der Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12614] = { id = 12614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postnatale Aggression", description = "Brutmutter Slivina ist vermutlich ein wütendes Knäuel aus Zähnen, Stacheln und Klauen. Ihr habt ihre Kinder gestohlen und keine Mutter kann so etwas verzeihen.\n\nDie kleinen Biester sind zwar aus Eiern geschlüpft, aber sie liebt sie dennoch so wie Euch Eure Mutter liebt.\n\nSie wird zugleich verzweifelt und wild sein - alles, was Hemet an einem Gegner liebt. Ihr und er, zusammen mit diesem Mammut, solltet Ihr ihr gewachsen sein.\n\nSie hält sich am nördlichen Rand des Wilden Dickichts auf und hungert nach Rache.", sourceObjective = "Tötet Brutmutter Slivina und kehrt zu Dorian Drachenlauer bei Dorians Außenposten zurück.", completion = "Nun, ich hatte eine komplette Rede vorbereitet, aber der alte Mann höchstpersönlich möchte einige Worte an Euch richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12615] = { id = 12615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Torga", description = "Verhexer Ubungo hat Euch wahrscheinlich von den Opfergaben an die Götter von Zul'Drak erzählt. Zim'Abwa ist nicht der einzige Gott, der von den Drakkari vergessen wurde.\n\nWir haben unter dem Mantel Zim'Torgas, der Mutter des Wohlstands, Schutz genommen. Es gilt dasselbe wie für Zim'Abwa: Reicht ihr Opfergaben der Drakkari dar und sie wird Euch sicherlich ihren Segen verleihen.", sourceObjective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Torga 10 Drakkariopfergaben darbringt.", progress = "<Ihr könnt spüren, wie die Augen der Mutter des Wohlstands auf Euch ruhen. Sie fragt sich, was ein {race} wie Ihr hier bei Ihr zu suchen hat.>", completion = "<Zim'Torgas Gedanken erfüllen die Euren. Sie spürt die Opfergaben und auch, dass Ihr sie ihr geben wollt. Sie ist erfreut.>\n\n<Sie lässt Euch wissen, dass Ihr dafür angemessen belohnt werdet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12616] = { id = 12616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kammer der Geheimnisse", description = "Ausgezeichnet, ein erfahrener Abenteurer. Genau das, was wir brauchen.\n\nEs gab Gerede unter den Kirin Tor, die Medivhs Turm bewachen, dass etwas in Karazhan nicht stimme. Es ging darum, dass dort drinnen eine neue Macht schlummere, eine Macht, die weder der Magie des Wächters noch der Legion unterstellt sei. Ihren Erkundungen zufolge scheint es, als handle es sich um einen Elfenprinzen namens Tenris Mirkblut; außerdem gäbe es Grund zur Annahme, dass er der Geißel diene.\n\nGeht, mein Freund, untersucht Mirkbluts Kammer und bringt sämtliche Informationen mit, die Ihr finden könnt.", sourceObjective = "Der Abgesandte der Argentumdämmerung möchte, dass Ihr Tenris Mirkbluts Kammer in den Bedienstetenunterkünften in Karazhan durchsucht.", completion = "Wenn die Befehle, die Ihr gesehen habt, echt sind, dann verheißt das, was Ihr gesehen habt, wirklich nichts Gutes. Wir können nur darauf hoffen, dass man ihn aufgehalten hat, ehe der Feind zu viel über unsere Stärken herausgefunden hat.\n\nHabt Dank, {name}. Möget Ihr sicher sein in diesen dunklen Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12617] = { id = 12617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eindringlinge vernichten", description = "Ich bin die Verkörperung von nur einem Aspekt Freyas, Tochter der Titanen. Ich bin die Lebenswächterin - ich wurde hier zurückgelassen, um dieses Land gegen die Bedrohung der Geißel zu schützen.\n\nNie hatte ich geahnt, dass der Lichkönig willige, lebendige Diener aussenden würde, um seine Befehle auszuführen.\n\nIch könnte diese Kultisten mit Leichtigkeit selbst zerschmettern, doch nur ich alleine stehe zwischen den untoten Armeen und dem übrigen Becken. Geht, {name}, überbringt diesen anmaßenden Eindringlingen meinen Zorn.", sourceObjective = "Der Avatar von Freya am Katarakt der Regenrufer möchte, dass Ihr Euch zum Lager der Todeshand im Nordwesten begebt und 8 infiltrierende Kultisten tötet.", completion = "Ihr sprecht die Wahrheit. Die Eindringlinge im Lager wurden beseitigt... aber ich fürchte, es könnte zu spät gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12618] = { id = 12618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Torga", progress = "<Zim'Torga schaut weiterhin teilnahmslos. Sie fragt sich, ob Ihr durch das Überreichen weiterer Drakkariopfergaben ihr zu Ehren einen weiteren Segen wünscht.>", completion = "<Die Mutter des Wohlstands blickt voller Wohlwollen auf Euch herab.>" }
quests[12619] = { id = 12619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verzierte Runenklinge", description = "Das einzig wirklich wichtige Stück Ausrüstung eines Todesritters ist seine Runenklinge. Mit dieser Klinge beherrscht er die Mächte des Frosts, des Blutes und der Dunkelheit. Außerdem dient sie als Gefäß, in dem der Todesritter Runenmacht speichern kann.\n\nDie Zeit ist gekommen, um Eure erste Runenklinge zu erschaffen. Geht zu den Waffenregalen auf der ersten Ebene und sucht nach einem kampferprobten Schwert. Bringt dieses Schwert anschließend zu einer Runenschmiede in der Nähe und verwandelt es in eine Runenklinge.", sourceObjective = "Geht zu den Waffenregalen in der Schwarzen Festung und sucht nach einem kampferprobten Schwert. Verwandelt es anschließend in einer Runenschmiede zu einem Runenklingenschwert.\n\nBringt das Runenklingenschwert danach zu Instrukteur Razuvious in der Schwarzen Festung.", progress = "Die Runenklinge ist ein Teil von Euch. Ein {class} kann ohne eine Runenklinge nicht kämpfen.", completion = "Gut gemacht, {name}. Ihr habt es geschafft, Eure erste Runenklinge herzustellen. Mit dieser werdet Ihr Chaos und Zerstörung hervorrufen! Ihr werdet eine Spur des Blutes hinterlassen, ein Schlachtfeld mit den Leichen all derer übersät, die es wagen sollten, sich der Geißel zu widersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12620] = { id = 12620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Lebenswächterin", description = "Wir waren nicht schnell genug, {name}. Diese verdammten Kultisten sind an der Schimmersäule und wollen sie zerstören - ich kann sie spüren.\n\nWir haben nicht viel Zeit. Besteigt die Schimmersäule, und wenn Ihr ganz oben angelangt seid, dann stoßt in das Horn, um meine Energie durch die Säule zu leiten.\n\nWir werden diesem Abschaum schon zeigen, dass mit den Schöpfungen der Titanen nicht zu spaßen ist.", sourceObjective = "Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr auf dem Gipfel der Schimmersäule Freyas Horn blast.", completion = "Beeindruckend. Ich hätte nicht gedacht, dass jemand wie Ihr, der Ihr nur ein Sterblicher seid, sich als so wertvoller Verbündeter erweisen würde.\n\nIch fürchte jedoch, dass wir nicht genug unternommen haben. Denn es scheint nicht so, als wäre es gelungen, der Geißel Einhalt zu gebieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12621] = { id = 12621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freyas Pakt", description = "Die Kultisten wurden erledigt, doch die Invasion der Geißel nicht aufgehalten. Die Situation wird langsam verzweifelt, {name}.\n\nEs gibt einen letzten Ausweg. Bevor ich Euch jedoch mehr verrate, muss ich sicher sein, dass Ihr mir vollkommen vertraut.", sourceObjective = "Hört zu, was der Avatar von Freya zu sagen hat.", progress = "Uns bleibt wenig Zeit. Die Geißel rüstet sich zum letzten Schlag.", completion = "Es gibt kein Zurück mehr. Wenn Ihr mir helfen wollt, müsst Ihr dies ohne zu zögern tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12622] = { id = 12622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anführer in Jin'Alai", description = "Denkst du auch das, was Ahunae denkt, Mann?\n\nEinige der Drakkaritrolle haben sich bei den Teichen von Jin'Alai im Südwesten versammelt. Wir werden ihre Anführer herauslocken müssen und Ahunae weiß auch ganz genau, wie du das machen wirst!\n\nGeh und töte diese Trolle. Sobald du genug von ihnen getötet hast, werden ihre Anführer aufkreuzen.\n\nWenn sie neben ihren Totems aufkreuzen, dann krall dir auf jeden Fall die Schätze von Kutube'sa, Gawanil und Chulo dem Verrückten, Mann.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr den Schatz von Kutube'sa, den Schatz von Gawanil und den Schatz von Chulo dem Verrückten beschafft.", progress = "Der {class} muss wieder bei Ahunae sein, weil der {class} alle Schätze gesammelt hat.", completion = "Der Skalpierer denkt, dass du genau sein {race} bist!\n\nWas machen denn diese Schokoladenriegel hier drin? Was sollen wir damit machen, Mann?\n\nAhunae sagt, dass du sie wieder zurückhaben kannst!", sourceObjectiveStatus = "unverified-source-field" }
quests[12623] = { id = 12623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Hexendoktor", description = "Wir Zandalari könnten Eure Hilfe gebrauchen, {name}. Wir müssen dem, was die Drakkari ihren Göttern antun, ein Ende setzen!\n\nGen Nordosten die großen Stufen hoch in Richtung der nächsten Ebene von Zul'Drak liegt Zim'Torga. Es ist die Heimat einer weiteren Götterstatue und eine Zuflucht, die mein Volk verzweifelt zu verteidigen versucht.\n\nIch hätte gerne, dass Ihr Euch dorthin begebt und mit Hexendoktor Khufu sprecht. Seid jedoch gewarnt, der Ort wird ständig von den Drakkari angegriffen.", sourceObjective = "Sprecht mit Hexendoktor Khufu in Zim'Torga.", completion = "Seid gegrüßt, {class}. Es freut mich, dass Umbungo jemanden gefunden hat, dem er vertrauen konnte.\n\nWillkommen in Zim'Torga.", sourceObjectiveStatus = "unverified-source-field" }
quests[12624] = { id = 12624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er könnte überall sein!", description = "Als ich herausfand, dass Fräulein Boulian Nesingwary bei seiner Expedition half, habe ich mich sofort als Deckmatrose gemeldet. Ihr müsst wissen, dass ich sie schon seit Monaten heiraten wollte!\n\nIch hatte alles geplant. In derselben Nacht, als wir Schiffbruch erlitten, wollte ich um ihre Hand anhalten... doch nun ist der Ring verschwunden. Ich habe überall nach ihm gesucht!\n\nEs mag sich vielleicht verrückt anhören, doch ich weiß, dass sich der Verlobungsring im Sholazarbecken befindet. Wenn niemand von der Venture Company ihn gestohlen hat, vielleicht hat ihn dann irgendeine wilde Kreatur gefressen. Doch er ist dort, irgendwo... Ich weiß es einfach!", sourceObjective = "Sucht nach einem goldenen Verlobungsring, den Ihr in den Mägen der verschiedenen Kreaturen im Sholazarbecken finden könnt.", progress = "Der Ring, {name}! Bitte... sagt mir, dass Ihr ihn gefunden habt!", completion = "Ihr habt es geschafft! Ihr habt ihn tatsächlich gefunden!\n\nIch weiß nicht... ich weiß nicht, wie ich Euch danken soll!", sourceObjectiveStatus = "unverified-source-field" }
quests[12625] = { id = 12625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrschaft über Acherus", description = "Erblicket Acherus, die große Zitadelle des Todes! Nicht einmal die mächtige Naxxramas könnte einem direkten Angriff der Schwarzen Festung Stand halten.\n\nObwohl Eure Gedanken vielleicht noch vernebelt sind, haben wir keine Zeit zu verlieren. Ihr müsst die Herrschaft über Acherus und Eure Gedanken erlangen! Die Hörner des Krieges erklingen!\n\nNehmt die Treppen auf dieser Etage - im Norden, Süden, Osten und Westen - um zur Garnisonsetage über uns zu gelangen. Sprecht mit Meisterbelagerungsschmied Corvus und besorgt seinen Statusbericht. Dieser muss an Thalanor geliefert werden.", sourceObjective = "Meldet Euch bei Meisterbelagerungsschmied Corvus auf der Etage der Garnison in der Schwarzen Festung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12626] = { id = 12626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompanie der Verdammten", description = "<Corvus salutiert vor Euch.>\n\nUnsere Vorräte an Waffen, Rüstungen und Munition haben schon fast ihre volle Kapazität erreicht. Wir sind nun kriegsbereit!\n\n<Corvus rollt ein fleischiges Stück Pergament aus.>\n\nAuf der anderen Seite der Garnison südwestlich von hier werdet Ihr die Offiziersquartiere vorfinden. Bringt diesen Statusbericht dorthin und übergebt ihn Geißelkommandant Thalanor, dem Bataillonskommandanten der Kompanie der Verdammten.", sourceObjective = "Liefert Corvus' Bericht bei Geißelkommandant Thalanor auf der Garnisonsebene der Schwarzen Festung ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[12627] = { id = 12627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Jin'Alai durchkommen", description = "Ich habe versucht, mit den Göttern Zwiesprache zu halten. Jedoch führen die Medizinmänner bei den Teichen von Jin'Alai Rituale durch, die meine Versuche unterbinden.\n\nEs ist äußerst wichtig, dass wir dieses Hindernis beseitigen. Falls Ihr nach Südwesten in das Gebiet mit den Teichen gehen solltet, dann bin ich mir sicher, dass Ihr die Kessel findet, die sie für ihre Magie verwenden.\n\nSabotiert jeden einzelnen von ihnen und setzt ihrem Ritual ein Ende, denn es hindert mich an meiner Arbeit.", sourceObjective = "Hexendoktor Khufu in Zim'Torga möchte, dass Ihr den blauen, grünen, purpurnen und roten Kessel sabotiert.", completion = "Ja, ich kann den Unterschied spüren. Habt Dank.\n\nDann lasst uns einmal sehen, ob wir jetzt mit den Göttern Kontakt aufnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12628] = { id = 12628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Har'koa sprechen", description = "Die Götter haben gesprochen, {name}. Wir wissen jetzt, was Ihr tun müsst.\n\nIhr müsst jetzt zum Altar von Har'koa im Südosten gehen und mit der Leopardengöttin sprechen.", sourceObjective = "Sprecht mit Har'koa am Altar von Har'koa.", completion = "Hört gut zu, kleiner {race}. Die Zeit drängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12629] = { id = 12629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt kein Entkommen", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Monstrositäten, sammelt den Ghulsabber, den Ihr dort finden werdet, und bringt mir ihre Überreste.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", progress = "Habt Ihr die Komponenten, um die ich Euch gebeten habe, mitgebracht, {name}?", completion = "<Stefan inspiziert die faulen Komponenten.>\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, {class}. Jetzt wird's erst richtig spannend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12630] = { id = 12630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narsch treten und Haare krümmen", description = "Bevor Ihr Narsch trefft, solltet Ihr etwas wissen.\n\nIhm wurde mal vor längerer Zeit eine toxische Dosis Seuche verabreicht und nun ist er taub, blind und kann kaum was spüren.\n\nDas hat aber auch sein Gutes. Er ist nun praktisch immun gegen das Zeugs und deshalb für gewisse Aufgaben wie die, die ich Euch gleich geben werde, perfekt geeignet.\n\nIn der Nähe gibt es viele Trolle, die erst kürzlich verseucht wurden, und wir müssen untersuchen, welche Auswirkungen die Seuche auf sie hat. Hier, nehmt Narsch mitsamt diesem Schuh. Gebt ihm einen kräftigen Tritt, nachdem Ihr einen Troll erschlagen habt, und er wird wissen, dass er eine Haarprobe zu nehmen hat.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe von Narsch 10 Haarproben von den siechenden Trollen sammelt.\n\nKehrt zu Stefan zurück, falls Ihr Narsch verlieren solltet, damit er ihn für Euch zurückbekommt.", progress = "Wie sieht's mit dem Schuh aus, {race}?", completion = "Wisst Ihr, Ihr erinnert mich unheimlich stark an meinen Narsch.\n\nVielleicht sind es auch nur die Ohren...", sourceObjectiveStatus = "unverified-source-field" }
quests[12631] = { id = 12631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Art Einladung...", description = "Dieser bluttriefende Halsreif ist aus Knochen gefertigt. Es ist von komplexer Art und wurde für einen bestimmten Zweck hergestellt.\n\nIhr starrt ihn an und werdet von etwas Unheilvollem ergriffen, das Euch dazu zwingen möchte, den Halsreif zu tragen. Ihr kämpft gegen den Drang an und beschließt endlich, ihn zur Schwarzen Wacht zurückzubringen.\n\nWenn irgendjemand eine Erklärung dafür hat, dann ist das ein Todesritter...", sourceObjective = "Bringt den untoten Halsreif zu Stefan in der Schwarzen Wacht.\n\nBereitgestellter Gegenstand:", completion = "Ich bin in der Tat mit Gegenständen wie diesem vertraut.\n\n<Stefan blickt Euch in die Augen.>\n\nEs scheint, {name}, als wärt Ihr... auserwählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12632] = { id = 12632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aber zunächst meine Jungen", description = "Ich bin der letzte der Götter, der unterworfen wurde, deshalb müssen wir zunächst versuchen, die anderen zu befreien. Da ich durch die Magie meiner Unterdrücker gebunden bin, ist es mir nicht möglich, zu erkennen, was mit ihnen geschehen ist.\n\nAber zuvor möchte ich Euch um einen Gefallen bitten. Schon jetzt nutzen die Drakkari meine Magie gegen mich. Sie haben meine Jungen in Monster verwandelt.\n\nNehmt eins meiner Barthaare. Erschlagt meine gequälten Kinder und nutzt seine Magie, um sie aus diesem Alptraum zu erwecken und ins Leben zurückzubringen.", sourceObjective = "Har'koa hat Euch gebeten, ihre Barthaare mit den Leichnamen ihrer Kinder zu benutzen und sie wiederzubeleben. Kehrt zu ihr am Altar von Har'koa zurück, sobald Ihr fertig seid.", progress = "Ich habe noch mehr Kinder, um deren Erlösung von ihren Qualen ich Euch bitte.", completion = "Ich danke Euch, {name}. Ich werde niemals vergessen, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12633] = { id = 12633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finsternis ruft", description = "Aus Knochen geschnitzt und bluttriefend, weist dieser Halsreif ein kompliziertes und wohlüberlegtes Design auf.\n\nBeim Betrachten überwältigt Euch eine beunruhigende Aura - eine, die Euch nötigt, es anzulegen. Ihr ringt den Drang nieder und entschließt Euch, es zur Schwarzen Wacht zurückzubringen.\n\nWenn jemand hierfür eine Erklärung hat, dann ein Todesritter...", sourceObjective = "Bringt Stefan in der Schwarzen Wacht den zuckenden Halsreif.\n\nBereitgestellter Gegenstand:", completion = "In der Tat kenne ich mich mit Gegenständen dieser Art aus.\n\n<Stefan sieht Euch in die Augen.>\n\nEs sieht so aus, {name}, als seid Ihr… auserwählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12634] = { id = 12634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die einen machen Limonade draus, die anderen Schnaps", description = "Das Leben hat mir dieses Mal eine Wagenladung Zitronen beschert! Als das Schiff auf Grund lief, zerbrachen die Krüge mit meinem besten Gebräu! Alles, was wir jetzt noch haben, sind ein paar Flaschen Rum und das stärkt keine durstige Expedition!\n\nWir müssen etwas Alkohol brennen und das schnell!\n\nDie Bäume im Wildwuchsmangal im Osten scheinen überladen mit Früchten zu sein, aber für mich sind sie zu hoch. Sucht nach guten, starken Ranken, mit denen Ihr ein paar dieser Früchte von den Bäumen schütteln könnt. Bringt mir alles, was Ihr finden könnt.", sourceObjective = "Bringt 1 Orange, 2 Bananenbündel und 1 Papaya zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", progress = "Hattet Ihr Glück und habt ein paar Früchte von diesen verflucht hohen, knausrigen Bäumen bekommen?", completion = "Gut, das ist eine bessere Auswahl, als ich von diesem Ort erwartet hätte. Nun zur entscheidenden Frage: Können wir daraus etwas Trinkbares destillieren? Wir fangen besser gleich damit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[12635] = { id = 12635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Schneeleopardengöttin", description = "Ich habe mitbekommen, dass Ihr Euch um das Wohlergehen von Har'koa kümmern werdet. Viel Glück.\n\nIch wollte nur einmal fragen, ob Ihr, während Ihr in der Nähe des Altars seid, nicht ihre Relikte für mich einsammeln wollt? Ich brauche nicht viele und es ist nur ein kurzer Abstecher nach Südosten.\n\nWas sagt Ihr dazu?", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 10 Har'koarelikte beschafft.", progress = "Die Drakkari sind so sehr damit beschäftigt, sich selbst zu zerstören, es wäre schade, wenn auch gleichzeitig die historische Bedeutung ihres Reiches verlorenginge.", completion = "Ahh, erstklassige Exemplare!\n\nIhr könnt hier die Abweichung von den Grundsymbolen erkennen. Ziemlich außergewöhnlich.\n\nWie schade, dass die Eistrolle fest dazu entschlossen scheinen, ihren eigenen Untergang herbeizuführen.\n\nHabt Ihr zum Beispiel gewusst, dass die Drakkari aufgrund ihrer äußerst brutalen Art vom Rest der Trollnationen verbannt wurden?\n\nEs ist wahr! Wie sonst hätten Trolle in solch einem rauen Klima wie hier landen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[12636] = { id = 12636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Acherus", description = "Seht, Acherus, die große Zitadelle des Todes! Seinesgleichen gibt es nur ein Mal auf dieser Welt! Nicht einmal Naxxramas, die mächtige Nekropole, könnte einem direkten Angriff der Schwarzen Festung widerstehen. Über dessen Fassade zeichnet sich drohend das allsehende Auge von Acherus ab. Von dort aus kann sein Meister über große Entfernungen sehen und die Gebiete seiner Feinde ausspionieren. Was das Auge sieht, sieht auch der Lichkönig, und nun ist die Zeit gekommen, dass Ihr durch das Auge blickt! der Lichkönig hat Euch gerufen, {name}.\n\nGeht nun! Geleidet Euch wohl, <Bruder/Schwester>...", sourceObjective = "Meldet Euch beim Lichkönig in der Schwarzen Festung.", completion = "Der Zeitpunkt, das Blut unserer Feinde zu vergießen, rückt näher. Zuerst müsst Ihr erfahren, was Ihr zerstören wollt, bevor Ihr Euch Hals über Kopf in die Schlacht stürzt.\n\nIch werde Euch Sicht jenseits des Sichtbaren gewähren, mein Champion. Mit dem Auge von Acherus werdet Ihr nun die Geheimnisse unseres Feindes stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12637] = { id = 12637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um ein Haar", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, {race}.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den untoten Halsreif zu Datura Blutrose bringt.", progress = "Ja, {race}?", completion = "Nun habt Ihr gesehen, was Euch beinahe zugestoßen wäre.\n\nWie ich schon zuvor erwähnt habe, war dies kein Zufall. Ein solches Gerät herzustellen, erfordert viel Aufmerksamkeit, und die benötigten Ressourcen würden nicht auf ein zufälliges Ziel verschwendet werden.\n\nIm Grunde genommen ist es so: Die Geißel hat es auf Euch abgesehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12638] = { id = 12638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine knappe Sache", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, {race}.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den zuckenden Halsreif zu Datura Blutrose bringt.", completion = "Nun habt Ihr also gesehen, welches Schicksal Euch gedroht hätte.\n\nWie ich schon erwähnte, war dies kein Zufall. Die Erschaffung eines solchen Apparates ist sehr umständlich. Ihr habt es geschafft, irgendwie die Aufmerksamkeit der Führung der Geißel auf Euch zu ziehen.\n\nDie Frage ist nicht wie, warum oder gar wer,... sondern was wir deswegen tun können?", sourceObjectiveStatus = "unverified-source-field" }
quests[12639] = { id = 12639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefrorene Erde", description = "Diese Elementare haben wir in der Nähe gefunden und dann eingefangen - nun stehen mir zahlreiche Verteidiger zur Verfügung. Man muss jedoch über erhebliche Kräfte verfügen, um sie stark genug zu machen, damit sie auch gegen unsere Feinde standhalten können.\n\nDie gefrorene Erde bei Drak'Mabwa gen Nordwesten hat genau das, was ich brauche, um unsere Verteidigungen aufrechtzuerhalten. Ich werde noch mehr von ihrer Essenz benötigen, um meine Arbeit weiterhin machen zu können.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 7 Essenzen der gefrorenen Erde beschafft.", progress = "Ich hoffe, dass Ihr genug zurückgebracht habt. Die Angriffe aus den Teichen von Jin'Alai sind verzweifelter geworden, nach dem, was Ihr dort angerichtet habt", completion = "Habt Dank, {class}. Mit diesen Essenzen sollte ich recht lange Zauber wirken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12640] = { id = 12640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Risse versiegeln", description = "Dagoda wird dich nach Nordwesten in Richtung Drak'Mabwa schicken, Mann, damit du dort mehr Zeug für ihre Verteidiger beschaffen kanns', falls sie das nich' schon gemacht hat.\n\nWenn du schon mal da oben bis', dann sollst du für Ahunae die Risse zerstören, aus denen die Elementare strömen. Das Letzte, was wir brauchen können, is', dass sie uns angreifen!\n\nPass bloß auf: Wenn du nämlich versuchst, die Risse zu schließen, dann wird noch mehr dieser gefror'nen Erde auftauchen.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr 7 Elementarrisse verschließt.", completion = "Ahunae hofft, dass Dagoda alle Verteidiger, die sie haben wollte, bekommen hat. Nun, da die Risse verschlossen sind, wird sie wahrscheinlich keine mehr bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12641] = { id = 12641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod kommt von ganz oben", description = "Hoch über dieser Plattform ist das Auge von Acherus. Dort werdet Ihr eine Sonde herbeirufen, mit der Ihr dann die Befestigungsanlagen des Scharlachroten Kreuzzugs bei Neu-Avalon analysieren könnt. Das Auge hat jede Menge Kräfte, welche die Beschaffung dieser Informationen einfach gestalten sollten.\n\nAnalysiert mithilfe der magischen Kräfte des Auges die Schmiede, Wacht, Kapelle und das Rathaus. Die Kontrollmechanismen für das Auge befinden sich auf jeder Seite dieser Plattform. Verliert nun keine Zeit mehr, {name}.\n\nDie Geißel wird diesen Ort einnehmen. Der Lichkönig befiehlt es!", sourceObjective = "Der Lichkönig befiehlt Euch, mithilfe des Auges von Acherus die Scharlachrote Festung, die Schmiede von Neu-Avalon, das Rathaus von Neu-Avalon und die Kapelle der Scharlachroten Flamme zu analysieren.\n\nDas Auge von Acherus lässt sich mithilfe der Steuerung für das Auge von Acherus kontrollieren.", progress = "Unser Angriff auf den Scharlachroten Kreuzzug wird zur Legende werden.", completion = "Sie bereiten sich wie erwartet auf den Kampf vor, doch da ist noch etwas Anderes. Ich spüre die Anwesenheit eines alten Feindes. Ein Feind, den ich vor langer Zeit vernichtet habe...\n\nEs macht nichts. Wir werden sie mit der geballten Macht der Geißel konfrontieren, bevor sie überhaupt die Chance haben, ihre Häuser zu evakuieren und ihre Verteidigungen bereitzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12642] = { id = 12642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist von Rhunok", description = "Mein Gefühl sagt mir, dass Rhunok nicht viel Zeit bleibt.\n\nIch kann sehen, dass der Geist des arktischen Bärengottes sich bereits von seinem geschwächten Körper gelöst hat. Und es ist sein Geist, mit dem Ihr in Kontakt treten müsst.\n\nSein Altar liegt im Nordwesten, jenseits von Drak'Mabwa.", sourceObjective = "Sprecht mit dem Geist von Rhunok am Altar von Rhunok.", completion = "Ich bin kurz davor, loszulassen. Ihr müsst Euch beeilen oder es wird alles verloren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12643] = { id = 12643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtblick", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Ghule und Monstrositäten, die Ihr dort finden werdet, und bringt mir ihre Überreste.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", progress = "Habt Ihr die Komponenten gebracht, um die ich Euch gebeten habe, {name}?", completion = "<Stefan inspiziert die faulen Komponenten.>\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, {class}. Jetzt wird's erst richtig spannend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12644] = { id = 12644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch dabei", description = "Nun, da wir über die Rohmaterialien verfügen, bereitet mein Assistent den Destillierapparat vor. Er wird den Prozess überwachen, aber ich möchte, dass Ihr dabei helft, alles unter Kontrolle zu behalten. Womöglich denkt Ihr, dass wir einfach alles in den Apparat werfen und gut, aber das stimmt nicht.\n\nZutaten und Hitze müssen immer zu bestimmten Zeiten zugeführt werden, der Druck wiederum zu anderen. Euch bleiben nicht mehr als 10 Sekunden, um rechtzeitig zu reagieren. Sprecht mit \"Schluckspecht\" McManus, sobald ihr bereit seid zu destillieren.", sourceObjective = "Schließt den Destillationsprozess erfolgreich ab und bringt Donnerbräus Dschungelpunsch, wenn er fertig ist, zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", progress = "Und, wie ist es geworden?", completion = "<Schnapsbart schüttelt den Behälter.>\n\nEs ist etwas drin, aber die Millionen-Gold-Frage ist, ob man es auch trinken kann. Ihr geht nirgendwo hin! Ihr seid auch dafür verantwortlich, das Probieren des Produkts zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12645] = { id = 12645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmackstest", description = "Und nun der Moment der Wahrheit!\n\n<Schnapsbart kichert.>\n\nIch wollte das schon immer mal sagen. Normalerweise würde ich ein neues Getränk bei einem Bankett vorstellen, aber wir können mitten im Dschungel nun mal keins abhalten.\n\nBringt stattdessen Proben zu ein paar guten Freunden und berichtet mir von ihrer Reaktion. Lasst mal sehen, wir wollen auf jeden Fall Hemets Meinung und ebenso Hadrius Harlowes. Sie sind hier im Lager. Ihr solltet auch Tamara Wackelspross beim Landeplatz am See in der Nähe des Beckenzentrums eine Geschmacksprobe anbieten.", sourceObjective = "Bietet Hemet Nesingwary, Hadrius Harlowe und Tamara Wackelspross eine Probe von Donnerbräus Dschungelpunsch an. Kehrt anschließend zu Schnapsbart Donnerbräu in Nesingwarys Basislager zurück.", progress = "Lasst mich nicht warten, {name}. Was ist herausgekommen?", completion = "Zwei von drei Kostern sind also zufrieden, hm? Nicht schlecht für einen ersten Versuch. Ganz und gar nicht. Ich denke, ich muss für Tamara als Entschuldigung etwas anderes zusammenrühren.\n\nHm... wie sollten wir diese Kreation nennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12646] = { id = 12646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind mein Prophet", description = "Mein Prophet hat zu viel von meiner Kraft zu schnell absorbiert und sich dadurch selbst getötet. Ihr könnt das Ergebnis in den mit Wasser gefüllten Kratern gen Süden in Drak'Mabwa sehen.\n\nMeine früheren Priester haben ihn schon wiedererweckt, damit er zu Ende bringen kann, was er angefangen hat. Sie speisen ihn mit meiner Kraft und es wird nicht mehr lange dauern, bis er wieder erwacht.\n\nIhr müsst ihm ein Ende bereiten und mein Mojo zurückbringen, bevor es zu spät ist.", sourceObjective = "Der Geist von Rhunok am Altar von Rhunok möchte, dass Ihr sein Mojo des arktischen Bärengottes wiederbeschafft.", progress = "Schnell, {race}, sagt mir, habt Ihr mein Mojo?", completion = "Ihr habt es geschafft.\n\nEs gibt jedoch noch eine andere Angelegenheit, die Ihr für mich erledigen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12647] = { id = 12647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leid ein Ende bereiten", description = "Mein Körper ist jetzt zu weit entfernt, {name}. Es ist nur eine Frage der Zeit, bis ein neuer Prophet erkoren wird und das zu Ende bringt, was die anderen begonnen haben.\n\nIch werde Euch meine letzten Kräfte verleihen. Der Foltermeister im Inneren des Altargebäudes hat ein Rauchwerk bei sich, das meinen Körper erwecken und wieder verwundbar machen wird.\n\nMacht von dem Rauchwerk Gebrauch und seid so nett und bereitet meinem Leid ein Ende.\n\nIch entschuldige mich schon einmal im Voraus, falls ich mich wehren sollte. Der Wille zu überleben ist selbst bei mir stark ausgeprägt.", sourceObjective = "Der Geist von Rhunok möchte, dass Ihr das Rauchwerk des Foltermeisters dazu einsetzt, um seinen Körper zu erwecken. Danach sollt Ihr Rhunok mithilfe der Macht, die sein Geist Euch verliehen hat, töten.\n\nFalls aus irgendeinem Grund die Aura für das Mojo von Rhunok von Euch weichen sollte, dann könnt Ihr zum Geist von Rhunok zurückkehren und Euch wieder segnen lassen.", progress = "Wenn Ihr nicht schon bald meinem Leiden ein Ende bereitet, {name}, dann könnte alles zu spät und verloren sein.", completion = "Ihr habt getan, was getan werden musste, und mir damit gleichzeitig Ehre erwiesen.\n\nTiefsten Dank, {name}. Ich hoffe nur, dass Ihr und Har'koa in der Lage sein werdet, den anderen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12648] = { id = 12648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leger kleiden", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält, ist es Euch möglich, Euch ungestört unter ihnen zu bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen - nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif, besucht den Händler der Geißel gleich östlich von hier und bringt mir von dort eine Flasche bitteres Plasma mit.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Nun, {name}?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12649] = { id = 12649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anziehen!", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält könnt Ihr Euch ungestört unter ihnen bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen. Nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif und besucht den Händler der Geißel gleich östlich von hier. Bringt mir von dort eine Flasche bitteres Plasma mit.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Nun, {name}?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12650] = { id = 12650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigene Artefakte plündern", description = "Es gibt noch einen Altar in der Nähe, wo es Artefakte zu retten gibt.\n\nMan sagt, dass die Drakkari im Altar von Rhunok im Nordwesten jenseits der zerstörten Tundra von Drak'Mabwa schon so weit sind, dass sie ihre eigene heilige Stätte plündern.\n\n{class}, ich wäre Euch sehr dankbar, wenn Ihr diese Artefakte retten und sie ihren unwürdigen Händen entreißen könntet.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 7 Rhunokianartefakte beschafft.", progress = "Man kann die Drakkari einfach nicht verstehen. Sie sind nichts weiter als brutale Barbaren, die noch tiefer gesunken sind.", completion = "Lasst mich einen Blick auf sie werfen.\n\n<Der Chronist untersucht die Artefakte, die Ihr gebracht habt.>\n\nHmpf, ich würde einmal sagen, dass wir uns glücklich schätzen können, dass Ihr diese hier aus ihrem Besitz befreit habt, {class}.\n\nWie überaus interessant. Dieses Artefakt hier zeigt die Ereignisse während der Teilung. Es war einmal eine Zeit, als Nordend den nördlichsten Teil von Kalimdor darstellte.\n\nDoch nach der Teilung brach das Land vom Rest ab und wurde schließlich zu dem Kontinent, den wir heute Nordend nennen.\n\nDas ist natürlich der Grund dafür, wieso die Drakkari hier und auf den südlichen Kontinenten vorzufinden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12651] = { id = 12651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landeplatz am See", description = "Als der Ärger mit der Venture Company begann, bat ich Marvin Wackelspross und seine Frau Tamara, ihre Flugmaschinen nach Osten an den Flussnabel zu verlegen. Außerdem sollten sie dort ein kleines Lager aufbauen, damit wir es als Stützpunkt zum Einfliegen von Vorräten und zur Beobachtung des Gebiets nutzen können.\n\nSie sollten inzwischen angekommen und mit dem Aufbau beschäftigt sein. Der Flussnabel ist in der Nähe der Beckenmitte, wo die Flüsse ineinanderfließen. Sucht nach dem Landeplatz am See am nordöstlichen Ufer. Marvin erwähnte, dass dies der beste Platz sei.", sourceObjective = "Sprecht mit Tamara Wackelspross am Landeplatz am See.", completion = "Hemet schickt Euch also? Wir wollten ihn gerade benachrichtigen, dass wir hier alles aufgebaut und zum Laufen gebracht haben. Bitte verzeiht Marvin, falls er Euch ignoriert, aber er ist immer sehr versunken in seine Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12652] = { id = 12652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt dem Ghul Zucker", description = "Komm ma' her, Ghuul! Jep, mit dir red ich.\n\nIs' jetzt Fudderzeit. Muss all das Zeuch all den Ghuul'n bring'n!\n\nIs' diesma' schpessial Fudder, jawoll, ja! 'Ne Schüssel voll sämigem Hirn mit Kuddeln… Mjam, mjam, mjam.\n\nEinfach Schüssel neben Ghuul fall'n lass'n. Gut, um Freunde zu find'n.\n\nHabt Ihr Ghuulfreunde? Ha, ha, ha?", sourceObjective = "Knorpelsack an der Reliquie der Pein möchte, dass Ihr die Schüssel voll sämigem Hirn mit Kutteln in der Nähe von 10 zerfallenden Ghulen benutzt.", progress = "Fertich mit Ghuuls füddern?", completion = "Mjam, mjam!", sourceObjectiveStatus = "unverified-source-field" }
quests[12653] = { id = 12653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Har'koa", description = "Und nun ist es für Euch an der Zeit, zur Leopardengöttin zurückzukehren. Irgendwie spüre ich, dass sie andere Pläne für Euch hat.\n\nSagt Ihr, was auch immer kommt, wir sind ewig.", sourceObjective = "Sprecht mit Har'koa am Altar von Har'koa.", completion = "<Die Katzengöttin heult auf vor Schmerzen.>\n\nMeine Seele ist erfüllt von Kummer über den Verlust eines weiteren Freundes. Aber fürchtet Euch nicht, er wird zurückkehren und sein Geist wird für immer leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12654] = { id = 12654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teilzeitjäger", description = "Als Hemet mich bat, Marvin hierher zu begleiten, hoffte ich, dass ich Gelegenheit fände, zwischen dem Reparieren der Flugmaschinen und dem Aufbauen des Lagers meine Jagdfähigkeiten zu verbessern.\n\nIch wollte einen wilden Löwen namens Pech erlegen. Angeblich lebt er südlich von hier, nahe der Stelle, wo der Wildwuchsmangal auf die nördliche Seite der Himmelszeltsäule trifft. Wenn Ihr die Kreatur findet, könntet Ihr mir ihre Überreste bringen? Wenn die Gerüchte wahr sind, ergeben sie eine Trophäe, vor der selbst Hemet Respekt hätte!", sourceObjective = "Bringt Pechs Überreste zu Tamara Wackelspross am Landeplatz am See.", progress = "Habt Ihr Pech gefunden?", completion = "Ihr habt sie! Nun muss ich daraus nur noch eine Trophäe herstellen. Das wird der harte Teil - einen Weg zu finden, das Ganze so zu präparieren, dass Hemet sich nicht auf meine Kosten lustig macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12655] = { id = 12655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Rhuk", description = "Es gibt noch einen vernachlässigten Gott in Zul'Drak.\n\nZim'Rhuks Statue befindet sich direkt im Norden. Er ist als \"der Weise\" bekannt und auch dafür, dass er sehr beschützerisch ist, wenn es um sein Reich geht. Er unterhält Wächter, die jeden die Rute spüren lassen, der nicht schlau genug ist, um ungesehen an ihnen vorbeizuschleichen.\n\nGeht den Wächtern aus dem Weg und gebt Zim'Rhuk die Drakkariopfergaben, damit Ihr Euch seinen Segen zunutze machen könnt.", sourceObjective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Rhuk 10 Drakkariopfergaben darbringt.", progress = "<Ihr spürt, dass Zim'Rhuk Euch kein Vertrauen entgegenbringt. Er ist kurz davor, einen seiner Wächter herbeizurufen.>", completion = "<Zim'Rhuk akzeptiert die Opfergaben, die Ihr ihm zu Füßen legen möchtet, obwohl er weiß, dass Ihr sie den Leichen anderer abgenommen habt.>\n\n<Ihr reicht ihm die Opfergaben dar, worauf er kurz zögert, zustimmt und Euch dann schließlich seinen Segen erteilt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12656] = { id = 12656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Rhuk", progress = "<Zim'Rhuk ist beeindruckt und frustriert, dass Ihr anscheinend wieder einmal seinen Wächtern durch die Finger gegangen seid - zumindest für den Moment.>\n\n<Platziert die Gaben zu seinen Füßen und er wird Euch abermals seinen Segen gewähren.>", completion = "<Zim'Rhuk zwingt Euch eine Vision auf, in der einer seiner Wächter Euch unter seinen Füßen zerquetscht. Vielleicht solltet Ihr versuchen, Zim'Rhuk zu besänftigen und ihm noch mehr Opfergaben darzubringen.>" }
quests[12657] = { id = 12657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Geißel", description = "Hört gut zu, Todesritter, denn was ich Euch mitzuteilen habe, wird einen Krieg auslösen. Mein endgültiges Urteil ist gesprochen: Tod - Allen. Niemand, der die Unverschämtheit besitzt, sich gegen die Macht der Geißel zu stemmen, darf ungeschoren davonkommen!\n\nIhr habt mir bei Eurer ersten Aufgabe gut gedient, also sollt Ihr mir auch bei Eurer nächsten Aufgabe gut dienen. Bringt mein Urteil, meinen Befehl zu Hochlord Mograine. Er befindet sich auf der ersten Etage des Kommandopostens von Acherus. Sagt ihm, dass er den Angriff einleiten soll.\n\nUnd wenn der Scharlachrote Kreuzzug erst einmal beseitigt ist, werden wir uns um die Argentumdämmerung kümmern.", sourceObjective = "Der Lichkönig gebietet Euch, seine Befehle zu Hochlord Darion Mograine in der Schwarzen Festung zu bringen.\n\nBenutzt den leuchtenden Transporter, der sich hinter dem Lichkönig befindet, um zu Hochlord Darion Mograine in die Hallen des Befehls zu gelangen.", completion = "Die Hörner des Krieges werden schon bald über dieses Land erschallen, sie werden die Toten erwecken und die Kriegsmaschine der Geißel ins Rollen bringen. Leid komme über diejenigen, die sich uns in den Weg stellen!\n\nIhr und Eure Brüder werdet den Angriff leiten, {name}. Und wenn ich das nächste Mal einen Blick auf die Lande des Scharlachroten Kreuzzuges werfen werde, so werden mir die Legionen von Acherus die Sicht nehmen. Der Marsch auf Neu-Avalon beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12658] = { id = 12658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Kuschelroc", description = "Dorian ließ mich die von ihm gefangenen Drachenjungen ausbilden und füttern und das hat mich ins Grübeln gebracht. Ich möchte einen eigenen Begleiter!\n\nNein, keinen jungen Drachen. Ich möchte keinen Begleiter, der mir die Hand abbeißen kann!\n\nAllerdings gibt es in den Knochenfeldern nordöstlich des Lagers jenseits des von Drachen dominierten Gebiets eine große Menge Blutklauenrocs. Die ausgewachsenen lassen sich wohl nicht mehr zähmen, aber wenn Ihr mir die Eier aus ihren Nestern bringt, kann ich sie vom Moment des Schlüpfens an großziehen.", sourceObjective = "Bringt Spleenix bei Dorians Außenposten 7 Eier eines Rocs.", progress = "Habt Ihr diese Eier?", completion = "Oh, die sind wirklich schön! Ich bin die Gesellschaft mechanischer Eichhörnchen und Hühner so leid. Es wird wundervoll sein, einen Begleiter zu haben, dessen Gelenke nicht geölt werden müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12659] = { id = 12659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skalpe!", description = "Ich glaub', es is' an der Zeit, ein wenig zu skalpieren, Mann!\n\nDie Trolle von Heb'Drakkar eignen sich gut für so was. Mit ihren schicken Knüppeln und ihren Angriffen wollnse's ja gar nich' anders!\n\nUnd Ahunae gibt dir sogar sein Messer, damit du den Job richtig gut machen kannst.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr Ahunaes Messer benutzt, um 10 Heb'Drakkar Trolle zu skalpieren.\n\nDer Skalpierer erinnert Euch daran, sie zuerst auszuplündern.", completion = "Oh, das is' zu komisch.\n\n{name} is' ein {race} ganz nach mei'm Geschmack!\n\nHast du noch mein Messer?", sourceObjectiveStatus = "unverified-source-field" }
quests[12660] = { id = 12660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtungswaffen", description = "Die Lakaien des Lichkönigs haben es gewagt, Vernichtungswaffen in meine Lande zu bringen. Dies werde ich nicht tolerieren.\n\nGeht zu ihrem Außenposten im Norden und zerstört die Waffen, die sie gegen das Land einsetzen wollen. Wir dürfen nicht zulassen, dass die Geißel auch nur einen Zoll dieser heiligen Länder besudelt.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr zum Lager der Todeshand in den Nordwesten geht und 4 Stück des instabilen Sprengstoffs zerstört.", completion = "Ich danke Euch, {race}. Es ist gut, in Euch einen Verbündeten zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12661] = { id = 12661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als Spion nach Voltarus", description = "Ihr habt die Einzelheiten meines Plans sicher bereits erraten.\n\nWir setzen das Interesse, das die Geißel an Euch hat, gegen sie ein. Ihr schleicht Euch verdeckt hinein. Ich weiß, dass dies vermutlich den Tod bedeutet, aber wenn wir nichts tun, so ist Euer Tod ganz gewiss.\n\nReist nach Nordosten zum Reliquiar des Schmerzes und stellt Euch auf die Plattform, nachdem Ihr Euch verkleidet habt. Einmal in Voltarus, müsst Ihr das Vertrauen des Geißelkommandanten erlangen.\n\nBlast dieses Horn, wenn Ihr Eure Mission abgeschlossen habt, und ich werde zu Euch fliegen, um den Bericht entgegenzunehmen.", sourceObjective = "Stefan möchte, dass Ihr Euren bezauberten Halsreif benutzt, um Euch in Voltarus einzuschleichen und dort alles zu tun, was der Anführer der Geißel von Euch verlangt.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und besorgt Euch einen neuen.", completion = "Nun gut… Ich muss zugeben, ich bin schon etwas überrascht, Euch zu sehen, {name}.\n\nSagt, was habt Ihr in Erfahrung bringen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[12662] = { id = 12662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heb'Jin erledigen", description = "<Dagoda sieht Ahunae an und seufzt.>\n\nIhr wollt Euch wirklich um Heb'Drakkar kümmern? Einfach nur Skalps zu sammeln, wird nicht genug sein. Ihr müsst ihren Anführer Heb'Jin ausschalten.\n\nDas Problem ist nur, dass er oben auf dem Fledermaushorst steht und von dort seine Truppen antreibt.\n\nSchlagt seine Trommel und ich versichere Euch, dass er herunterkommen wird. Das ist der Moment, in dem Ihr ihn töten könnt.\n\nNehmt doch auch dieses Netz hier - wir haben es von seinen Kopfgeldjägern. Fangt damit seine Fledermaus ein, nachdem sie gelandet ist. Auf diese Weise müsst Ihr nicht beide bekämpfen.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr Heb'Jin tötet.", completion = "Ihr habt es geschafft!\n\n<Dagoda gibt Euch einen fetten Schmatzer auf die Wange.>\n\nIhr könnt Euch gar nicht vorstellen, wie mich das erleichtert! Die Trolle greifen uns von allen Seiten an und uns dagegen zu verteidigen, setzt uns wirklich unter Druck - von seinem ununterbrochenen Geschrei ganz zu schweigen.\n\nBitte, {name}, sucht Euch von dem hier etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[12663] = { id = 12663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereint", description = "{name}!\n\nDu musst mein Geschenk bekommen haben! Dreh dich um, Mann, und lasst mich dich mal ansehen... Ahhh, du machst mich stolz.\n\nWir haben viel hinter uns, du und ich, und nun werden wir beide dem Lichkönig dienen.\n\nHalt dich an mich und du wirst davon profitieren, Mann. Profitieren... doch zuerst müssen wir dich auf den neuesten Stand bringen. Viel ist passiert, seitdem wir uns das letzte Mal gesehen haben.\n\nGeh und sprich mit Grindbruch, damit er dich auf einen Rundflug über Zul'Drak mitnimmt. Hör mir zu und du wirst alles erfahren, was du wissen musst.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht.", completion = "So, nun weißt du, was uns gegenübersteht, Mann.\n\nGeh hinunter, lass dir etwas Zeit, lern das Land kennen und denk dir irgendeine Strategie aus.\n\nIch werde schon bald ein paar Aufgaben für dich haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12664] = { id = 12664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkler Horizont", description = "Ahh, noch ein Bittsteller, der des Lichkönigs Ruf gefolgt ist.\n\n<Drakuru schnüffelt an Euch.>\n\nFrisch verseucht, hm? Du riechst noch immer wie die Lebenden!\n\nDie Reihe derer, die den Segen des Lichkönigs suchen, ist lang. Du musst dich von den Massen abheben und beweisen, dass du wahrer Macht würdig bist.\n\nAls ich über Zul'Drak hinweg sah, konnte ich spüren, dass etwas in dir steckt. Ich war es, der dich zu uns \"einladen\" ließ.\n\nDer Rest liegt an dir...\n\nGeh und sprich mit Grindbruch und er wird dich auf einen Rundflug über Zul'Drak mitnehmen. Es wird viel zu tun geben, wenn du überhaupt irgendeinen Wert für mich besitzen willst.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht.", progress = "Hast du dir das Schlachtfeld schon angesehen, Mann?", completion = "So, nun weißt du, was uns gegenübersteht, Mann.\n\nIch möchte, dass du hinunter gehst, das Land kennenlernst und dich unter deine Brüder mischst. Sei bereit...\n\nSchon bald wird es viel für dich zu tun geben. Enttäusch mich bloß nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12665] = { id = 12665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich spüre eine Erschütterung", description = "Etwas ist nicht in Ordnung mit Quetz'lun, der Windnattergöttin. Was genau es ist, vermag ich nicht zu sagen, aber ich weiß, dass ihr Altar von mächtigen Kreaturen überrannt wurde.\n\nIch werde Euch dorthin auf dem Rücken eines meiner von Euch geretteten Kinder entsenden. Zusammen werdet Ihr Euch schnell und verstohlen bewegen können, um das Rätsel um Quetz'luns Schicksal zu lösen.\n\nMein Kind wird Euch sicher zu mir zurückbegleiten. Haltet nur Eure Augen offen.\n\nSobald Ihr bereit seid, sagt Bescheid und ich werde eins meiner Kätzchen rufen.", sourceObjective = "Har'koa hat Euch gebeten, herauszufinden, was mit Quetz'lun geschehen ist. Sprecht mit ihr, um heimlich auf einem ihrer Kinder zum Altar von Quetz'lun zu reiten.\n\nKehrt zu ihr am Altar von Har'koa zurück, sobald Ihr die Aufgabe erfüllt habt.", progress = "Warum die Verzögerung, {name}?", completion = "Ich danke Euch, dass Ihr mein Kätzchen sicher zurückgebracht habt.\n\nTief in meinem Inneren wusste ich es bereits. Ich habe versucht, es zu leugnen, aber Eure Augen haben die Wahrheit ans Licht gebracht.\n\nTrotzdem spüre ich noch etwas Anderes. Es ist nicht alles so, wie es scheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[12666] = { id = 12666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen für die Unterwelt", description = "Quetz'lun mag vielleicht tot sein, doch ich kann ihren Geist noch immer spüren: Sie ist in der Unterwelt bei ihrem Altar. Wir müssen herausfinden, wie wir Euch dorthin bringen können.\n\nWie es das Glück so will, steht mir eine Anzahl einstiger Bittsteller zur Verfügung, die nicht länger ihre heilige Zier benötigen. Meine Unterdrücker und Klauen werden sie höchstwahrscheinlich noch immer tragen.\n\nBringt mir diesen Schmuck und ich werde Euch mithilfe seiner Energie ein Tor zu Quetz'luns höllischer Unterwelt öffnen.", sourceObjective = "Har'koa am Altar von Har'koa möchte, dass Ihr 8 Stück heiliger Zier sammelt und sie anschließend bei ihr abliefert.", progress = "Ich hätte niemals geglaubt, dass es dazu kommen würde - die Drakkari sind wahrhaftig verloren.", completion = "<Die Leopardengöttin blickt traurig auf die vor ihr liegende Sammlung heiliger Symbole.>\n\nEs gab eine Zeit, als diese hier noch etwas zu bedeuten hatten... Sehen wir einmal, ob wir sie zu einem besseren Zweck einsetzen können", sourceObjectiveStatus = "unverified-source-field" }
quests[12667] = { id = 12667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Windschlangengöttin auf", description = "Ihr seid nun zwar bereit, doch ich bin mir nicht sicher, ob Ihr auch für das gewappnet seid, was denn kommen wird.\n\nWenn Ihr Euch zurück in den Bereich von Quetz'luns Altar begebt, dann werdet Ihr damit auch das Reich des Todes betreten. Ich hab's so im Gefühl, dass es kein angenehmer Aufenthalt sein wird.\n\nVersucht, Euch von den Dingen dort drinnen nicht ablenken zu lassen. Geht einfach nur in Richtung Altargebäude und sucht Quetz'luns Geist auf.", sourceObjective = "Geht zum Altar von Quetz'lun und sucht Quetz'luns Geist auf.", completion = "Du Wurm. Sag mir, wieso ich dich nicht an Ort und Stelle vernichten soll?", sourceObjectiveStatus = "unverified-source-field" }
quests[12668] = { id = 12668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg zur Rache ebnen", description = "Ich habe etwas Besonderes für meine Lieblingshohepriester geplant. Doch zuerst werdet Ihr den Grundstein für meine Rache legen und Euch somit beweisen.\n\nIhr wollt doch am Leben bleiben, oder?\n\nWie Ihr gesehen habt, genießen meine Verehrer ihren hiesigen Aufenthalt. Doch nun ist die Zeit gekommen, dass sie ihre letzte Schuld begleichen müssen.\n\nTut mir doch einen klitzekleinen Gefallen, {name}: Lockt sie in die Nähe meiner Seelenbrunnen und macht ihrem Dasein ein Ende.\n\nSie schmecken gar köstlich - und ihr Opfer wird nicht umsonst gewesen sein, das kann ich Euch versichern.", sourceObjective = "Quetz'luns Geist am Altar von Quetz'lun hat Euch damit beauftragt, in der Nähe ihrer Seelenbrunnen 12 Trolle zu töten. Diese können entweder Anbeter von Quetz'lun oder schlangengebissene Berserker sein.\n\nKehrt erst dann wieder zu ihr zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Wieso kehrt Ihr schon zurück, obwohl Eure Aufgabe noch nicht erfüllt ist? Erkennt Ihr denn nicht, dass nur ein einziger Gedanke von mir genügt, um Euch zu zerstören?\n\nGeht nun, kleiner {race}. Führt meinen Befehl zu Ende!", completion = "Exquisit. Vielleicht seid Ihr doch zu etwas zu gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12669] = { id = 12669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So weit, so schlecht", description = "Alles, was Ihr mir berichtet habt, stimmt mit unseren Informationen überein. Etwas über Drakuru zu erfahren und sein Vertrauen zu gewinnen, stellt die Basis für Eure zukünftigen Missionen dar.\n\nKehrt zu ihm zurück und macht, was er sagt. Tut alles, was nötig ist, um glaubwürdig zu erscheinen, {name}. Vieles hängt davon ab, wie Ihr Euch macht.\n\nDoch dieses Mal werdet Ihr eine zusätzliche Aufgabe bekommen: Gießt diese Lösung in ihre Seuchenkessel dort draußen. Dadurch sollte ihr Seuchenwirkstoff neutralisiert und ihre Ladung unbrauchbar gemacht werden.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zu Drakuru zurückkehrt und alles tut, was er von Euch verlangt.\n\nWährend Ihr beim Reliquiar des Schmerzes seid, sollt Ihr die Verdünnungslösung in 5 Seuchenkessel schütten.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "{name}, bitte sagt mir, dass Eure Tarnung nicht aufgeflogen ist...", completion = "Gute Arbeit, {name}!\n\nDas Zeug in den Kesseln zu verdünnen, wird nicht nur Leben retten, sondern auch dafür sorgen, dass sich die Geißel in dieser Region nicht so schnell verbreitet.\n\nNun kommt schon, erzählt mir, was Ihr über Drakurus Strategie in Zul'Drak erfahren habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12670] = { id = 12670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Scharlachrote Ernte", description = "Unterhalb von Acherus befindet sich die Todesbresche, die Bühne, auf der unser Angriff auf den Scharlachroten Kreuzzug stattfinden wird. Schwingt Euch auf einen meiner Geißelgreifen, die auf beiden Seiten dieser Plattform zu finden sind, und meldet Euch bei Prinz Valanar. Tut, was er sagt, und Ihr möget den Tag erleben, an dem diese Länder unter unsere Herrschaft fallen werden.", sourceObjective = "Meldet Euch bei Prinz Valanar bei der Todesbresche.", completion = "Riecht Ihr das?\n\n<Valanar macht einen kurzen Atemzug.>\n\nFrisches Fleisch… Der Geruch des Scharlachroten Kreuzzugs liegt in der Luft.\n\nEntschuldigt, {class}, ich bin sicher, dass Ihr nicht interessiert seid an meiner Art der feinen Küche. Ihr seid hier, um zu arbeiten! Um den Angriff anzuführen! Ja... ich weiß. Der Lichkönig hat mir alles erzählt, was ich über Euch wissen muss, {name}.\n\nDie Zeit ist gekommen, um Blut zu vergießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12671] = { id = 12671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärungsflug", description = "Es wird Zeit, dass wir hier Flugzeuge zum Laufen bringen. Die Professorin hat mich gebeten, das seltsame Wetterphänomen im Nordosten zu untersuchen.\n\nDie Sache ist, dafür brauche ich einen Copiloten, wenn wir in unbekanntes Territorium fliegen. Keine zehn Pferde bekommen mich da alleine hin.\n\nWas meint Ihr, Heißsporn? Vielleicht lernt Ihr noch ein oder zwei Dinge dazu. Und wenn Ihr erstmal lernt, mit den Winden des Nordens umzugehen,... dann könnt Ihr so ziemlich überall fliegen.", sourceObjective = "Helft Pilot Vic den Aufklärungsflug abzuschließen.", completion = "Ihr habt mir da oben das Leben gerettet, Kumpel. Nette Flugkünste!", sourceObjectiveStatus = "unverified-source-field" }
quests[12672] = { id = 12672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegbereiter", description = "Ich werde Euch die Chance geben, Eure Existenz noch ein wenig zu genießen.\n\nFragmente der Kraft, die meinem Fluch Nahrung gaben, sind über den Altarboden verteilt. Es ist mein Wunsch, dass Ihr einige davon für mich aufsammelt. Nicht so viele, dass mein Fluch aufgehoben wird, aber genug, dass es mir schließlich gelingen wird, Rache an meinem Propheten zu üben.\n\nGeht, Insekt. Lauft und erfüllt meine Befehle, bevor ich meine Meinung darüber ändere, Euch am Leben zu lassen.", sourceObjective = "Quetz'luns Geist verlangt, dass Ihr 10 Fragmente unterweltlicher Macht sammelt. Kehrt zu ihr zum Altar von Quetz'lun zurück, wenn Euch dies geglückt ist.", progress = "Eine Schande, dass Har'koa Euch nicht früher vorbeigeschickt hat. Auf der anderen Seite haben wir uns nie besonders gut verstanden.\n\nSie hat Eure Hilfe vermutlich einfach nur lange genug zurückgehalten, damit das hier geschieht.", completion = "Mit diesen wird es funktionieren. Wahrscheinlich brauche ich sie allerdings sowieso nicht.\n\nAber es hat Spaß gemacht, Euch nach meiner Pfeife tanzen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12673] = { id = 12673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach oben buckeln, nach unten treten", description = "Wenn du es jemals wert sein willst, die Geschenke des Lichkönigs zu erhalten, dann musst du lernen, ein großer Anführer zu sein - einer, der Respekt abverlangt!\n\nIch habe eine Aufgabe für dich, die deine Fähigkeit zu Führen verfeinern wird, Mann...\n\nEinige meiner Diener sind dazu ausgebildet, Seuchenkristalle in dem Gebiet unter uns zu sammeln, doch sie sind faul und arbeiten nur langsam. Du wirst die Leitung über sie haben, Mann.\n\nNimm dieses Szepter und zeig ihnen, wie man die Arbeit richtig macht. Lass sie die Kristalle sammeln, sobald sie unter deiner Kontrolle sind!", sourceObjective = "Oberanführer Drakuru in Voltarus möchte, dass Ihr das Szepter der Suggestion auf die Seuchenspuke anwendet und sie dann 7 Seuchenkristalle sammeln lasst.", progress = "Wurden meine Untergebenen von dir zurechtgepeitscht, {name}?", completion = "Wir werden mehr Kristalle haben als je zuvor!\n\nMach weiter so, {name}. Ich werde schon bald noch mehr Aufgaben für dich haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12674] = { id = 12674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornentbrannte Hölle", description = "Es ist nun Zeit, dass Ihr meine drei Hohepriester Mu'funu, Tua-Tua und Hawinni bestraft. Sie befinden sich alle irgendwo im Altargebiet verstreut.\n\nNehmt diesen Verhexungsstecken - er ist von meinem Zorn und Unwillen erfüllt. Ich bin mir sicher, dass er ein effektives Werkzeug sein wird.\n\nIhr müsst ihn einfach einsetzen und sie anschließend vernichten. Der Hex wird sich dann um den Rest kümmern.\n\n<Quetz'lun grinst über beide Ohren.>\n\nHabt Erfolg und ich werde Euch womöglich gehen lassen - versagt und Ihr werdet sterben.", sourceObjective = "Quetz'luns Geist am Altar von Quetz'lun möchte, dass Ihr Quetz'luns Verhexungsstecken auf Hohepriester Mu'funu, Hohepriester Tua-Tua und Hohepriester Hawinni anwendet. Anschließend sollt Ihr sie vernichten.", progress = "DENKT IHR ETWA, DASS ICH EIN IDIOT BIN?\n\nSIE SIND NICHT TOT!", completion = "<Der schreckliche Geist vor Euch gibt ein Gekicher von sich, das Euer Blut gefrieren lässt.>\n\nSie hätten damit rechnen können. Und ich werde ihnen dasselbe wieder und immer wieder zu spüren geben...", sourceObjectiveStatus = "unverified-source-field" }
quests[12675] = { id = 12675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine letzte Sache", description = "Da gäbe es noch eine letzte Sache zu erledigen und meine Rache am Propheten wäre perfekt. Die Fragmente der Macht, die Ihr gesammelt habt, müssen mit einem Teil des Geistes eines lebendigen Gottes erfüllt werden. Ihr werdet also Har'koa anflehen müssen, ob sie nicht etwas von ihrem Geist abgeben möchte.\n\nSobald dies dann getan ist und Ihr zurückkehrt, wird es nicht in der Unterwelt sein, nein, Ihr werdet zur materiellen Welt meines Altars zurückkehren. Meine Kinder und Wächter werden Euch nicht länger angreifen - Ihr könnt also zu meinem Propheten gelangen, ohne Euch großartig Sorgen wegen ihnen machen zu müssen.", sourceObjective = "Liefert die Fragmente unterweltlicher Macht bei Har'koa ab und bittet sie um einen Teil ihres Geistes. Sie befindet sich noch immer am Altar von Har'koa.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Ein Teil meines Geistes?\n\n<Die Schneeleopardengöttin hält einen Moment inne, um darüber nachzudenken.>\n\nDas ist ein ziemlich teures Geschenk, wenn man sich überlegt, dass es zu Rachezwecken eingesetzt wird und ich durch die Machenschaften meiner Unterdrücker schon ziemlich geschwächt wurde.\n\nIch weiß vielleicht trotzdem einen Weg, wie wir die Sache lösen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12676] = { id = 12676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage", description = "Wir werden versuchen herauszufinden, welchen Zweck diese Kristalle erfüllen, und Ihr geht zurück nach Voltarus und tut, was Drakuru von Euch verlangt.\n\nMit jeder Aufgabe, die Ihr für ihn erledigt, wird er Euch mehr Vertrauen schenken und uns damit Einblick in sein Denken gewähren.\n\nIch habe auch eine andere Aufgabe für Euch, während Ihr schon mal dort seid: Drakurus Geißelwagen stellen eine beträchtliche Gefahr dar - sie müssen zerstört werden.\n\nMacht Euch auf den Weg zu den Wagen und bringt diese Sprengladungen an. Geht in Deckung, sobald Ihr sie scharf gemacht habt! Die Explosion wird Euch verraten, wenn Ihr zu nah dran steht.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr eine weitere Aufgabe für Drakuru erledigt.\n\nZusätzlich dazu müsst Ihr an 5 Geißelwagen im Reliquiar des Schmerzes Sprengladungen anbringen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", completion = "Ausgezeichnet!\n\nEuer verdeckter Einsatz hat sich wirklich ausgezahlt, {name}.\n\nNun lasst uns einmal einen Blick auf dieses Szepter werfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12677] = { id = 12677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Materialien", description = "Seuchenkristalle?! Was könnte dieser Mistkerl Drakuru nur vorhaben? Offensichtlich arbeitet er an etwas Bedeutendem.\n\nTanzt weiterhin nach seiner Pfeife und vielleicht, sobald er sich etwas mehr an Euch gewöhnt hat, wird er Euch seine Pläne verraten. Versucht in Voltarus ein paar Proben der geernteten Kristalle in die Finger zu bekommen, wenn gerade niemand hinsieht.\n\nDoch aufgepasst! Der Umgang mit diesen Kristallen könnte Euch enttarnen.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr nach Voltarus geht und all das erledigt, was Drakuru Euch aufgibt. Während Ihr dort seid, sollt Ihr 5 geerntete Seuchenkristalle stehlen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Willkommen zurück, {name}.\n\nKonntet Ihr irgendwelche Proben von Drakurus Kristallen mitgehen lassen?", completion = "Faszinierend!\n\nWir werden uns diese Kristalle gleich einmal näher ansehen, um deren Beschaffenheit herauszufinden.\n\nNun sagt mir, {name}, gibt es irgendwelche Neuigkeiten über diesen Drakuru?", sourceObjectiveStatus = "unverified-source-field" }
quests[12678] = { id = 12678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leid wird vom Chaos getrieben", description = "Sie haben Stellung außerhalb der Todesbresche bezogen und versuchen vergeblich, uns zurückzudrängen. Sie hoffen, dass sie dadurch ihre Pferde, Minen, ihr Holz und ihre Bürger retten können.\n\nDies wird Eure erste Lektion in Sachen Geißelkriegsführung sein: SCHRECKEN!\n\nGeht an die südliche Front und tötet die Scharlachroten Kreuzfahrer. Lasst ihre Leichen in Ruhe, damit wir sie für unseren Todesfeldzug einsetzen können.\n\nDoch was am aller wichtigsten ist: tötet die flüchtenden Dorfbewohner. Tote Soldaten nehmen sie in Kauf, doch einfache Bürger? Das erfüllt die Herzen der Menschen mit Furcht.", sourceObjective = "Prinz Valanar in der Todesbresche befiehlt Euch, 10 Scharlachrote Kreuzfahrer oder Scharlachrote Arbeiter, und 10 Bürger von Havenau zu töten.", completion = "Könnt Ihr es spüren, {name}? Dieses Gefühl ist pure Macht, wie sie durch Euren Körper fließt. So etwas kennen Sterbliche nicht.\n\nWir haben an den Fronten den Sieg errungen. Die Spuke werden die Reste beseitigen und alles für Razuvious' Ankunft vorbereiten. Wir werden unsere Aufmerksamkeit nun auf taktischere Ziele richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12679] = { id = 12679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heute Abend speisen wir in Havenau", description = "Die Himmelsverdunkler sind hirnlose Konstrukte, die nur ein Ziel kennen: TÖTEN! Sie haben es ganz besonders darauf abgesehen, jeden zu töten, der aus Havenau flieht, um sich in Neu-Avalon in Sicherheit zu bringen. Gewiss können wir diese Feiglinge nicht entwischen lassen, nur damit sie später die Waffen gegen uns erheben werden!\n\nEs gibt jedoch ein kleines Problem. Sie verwenden Saronitpfeile, um ihre Reichweite zu maximieren und den größtmöglichen Schaden anzurichten. Saronit ist allerdings ein Metall, das nur in Nordend vorkommt, also sind die Vorräte begrenzt! Beschafft mir diese Pfeile und ich werde Euch reich belohnen.", sourceObjective = "Orithos der Himmelsverdunkler in der Todesbresche möchte, dass ihr 15 Saronitpfeile beschafft.", progress = "Anhand der Flugbahn ihrer Pfeile würde ich sagen, dass sich die meisten südlich von uns auf den Höfen von Havenau und in deren näheren Umgebung finden lassen.", completion = "Gut gemacht, {class}! Eure Taten treiben die Kriegsmaschinerie der Geißel voran!\n\nAch ja, Eure Belohnung - wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12680] = { id = 12680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Palomino", description = "Welch Zufall, dass der Scharlachrote Kreuzzug keinen Steinwurf von hier entfernt einen Stall voller Pferde hat. Sie bewachen ihn zwar hartnäckig, doch ein aufstrebender junger Todesritter könnte durch ihre Verteidigungen brechen und nehmen, was rechtmäßig ihm gehört!\n\nSobald Ihr dann ein Pferd aus den Ställen von Havenau besorgt habt, sollt Ihr es zu mir bringen und ich werde sehen, ob es sich in ein ordentliches Todesstreitross umwandeln lassen wird oder nicht.\n\nMerkt Euch, {name}: Gestohlen ist es erst dann, wenn man sich erwischen lässt. Und nehmt Euch vor dem verrückten Stallmeister Kitrik in Acht!", sourceObjective = "Salanar der Reiter in der Todesbresche möchte, dass Ihr ein Pferd aus den Ställen von Havenau stehlt und es zu ihm bringt.", progress = "Ihr wollt doch nicht für immer zu Fuß gehen, oder?", completion = "Nun zum eigentlichen Test: Habt Ihr das Zeug dazu, ein ungezähmtes Todesstreitross zu beherrschen und den Willen dessen zu brechen, nach dem es Euch am meisten verlangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[12681] = { id = 12681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzagent", description = "Der Erzmagier Pentarus in Dalaran wird erwarten, dass wir mit allerlei Arten von Reagenzien und Glücksbringern zurückkehren. Es sieht so aus, als hätten die Einheimischen Tierteile recht gern. Verdrehte Klauen von Blutklauenrocs scheinen ihnen die Liebsten zu sein.\n\nEs ist nicht an mir, zu sagen, ob die Gerüchte stimmen oder nicht, aber ich habe so das Gefühl, dass da durchaus etwas dran sein könnte.\n\nDie Rocs leben in den Knochenfeldern im Nordosten, wo sie sich von den Überresten alter Mammuts ernähren. Wollt Ihr mir helfen, für die Forschungsarbeit des Erzmagiers Klauen zu sammeln?", sourceObjective = "Bringt Colvin Norrington an Dorians Außenposten 5 verdrehte Rocklauen.", progress = "Habt Ihr es geschafft, verdrehte Klauen zu finden?", completion = "<Colvin schaut bewundernd auf die Klauen, die Ihr mitgebracht habt.>\n\nDiese werden mehr als ausreichen. Die Gorlocs haben ein Sprichwort, welches besagt: je verdrehter die Klaue, umso mehr Macht besitzt sie. Ich bin mir sicher, der Erzmagier wird bei dieser Expedition etwas für sein Geld bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12683] = { id = 12683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenn darauf zu helfen", description = "Es gibt kein Material im ganzen Becken, das ätzender und beißender ist als Bittertiden-Hydrasputum. Ich besitze besondere Behälter, um es für Erzmagier Pentarus' Studien zu sammeln. Nun brauche ich nur noch jemanden, der mutig genug ist, es, ähm... einzusammeln.\n\nIhr wirkt wie <ein abgehärteter, abenteuerlustiger/eine harte> abenteuerlustige:c; {class}. Was haltet Ihr davon, Euch ein bisschen Geld zu verdienen und gleichzeitig Dalarans Sache zu helfen?\n\nAlles, was Ihr zu tun habt, ist, diesen Behälter zum Bittertidensee im Südwesten mitzunehmen. Greift eine Hydra an und benutzt den Behälter, um das Sputum einzufangen, das sie auf Euch niederregnen lässt.", sourceObjective = "Colvin Norrington bei Dorians Außenposten möchte, dass Ihr 5 Proben Hydrasputum sammelt und 5 Bittertidenhydras tötet.", progress = "Habt Ihr diese Proben besorgt?", completion = "Wunderbar! Hier ist Eure Bezahlung, wie abgemacht. Und, äh, ein kleiner Rat: Ihr solltet in den nächsten Tagen lange, heiße Bäder nehmen, wenn dieses \"brennende Gefühl\" weiter anhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[12684] = { id = 12684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut eines toten Gottes", description = "Mam'toth, der Gott der Mammuts, hat sich selbst vernichtet und dabei lieber den Großteil seines Tempels mit sich gerissen, als es seinen Trollen zu erlauben, seine Macht zu erlangen.\n\nWenn ich einen Teil meines Geistes opfern soll, so brauche ich etwas, um mich zu stärken.\n\nMam'toth hat einen enormen Krater im Nordosten hinterlassen, gerade nördlich des Altars von Quetz'lun. In diesem Krater lebt sein Blut noch immer.\n\nBringt es mir.", sourceObjective = "Har'koa hat Euch gebeten, 7 Blutproben von Mam'toth zu sammeln. Bringt sie zu ihr am Altar von Har'koa.", progress = "Ich wünschte, es gäbe etwas, womit wir Mam'toth von den Toten zurückholen könnten, aber es gibt nichts.\n\nWir können ihm und seinem Opfer Ehre erweisen, indem wir den Kampf gegen die Drakkari fortführen.", completion = "Nun gut. Lasst uns sehen, ob das hier funktioniert...", sourceObjectiveStatus = "unverified-source-field" }
quests[12685] = { id = 12685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man erntet, was man sät", description = "Darauf ist es hinausgelaufen... Rache.\n\n<Har'koa seufzt.>\n\nNehmt diesen Beutel mit Ritualgegenständen und vollzieht in der Nähe von Quetz'luns Leiche auf ihrem Altar ein Ritual. Wenn alles reibungslos abläuft, dann sollte Ihr Geist in die materielle Welt gezogen werden, von wo aus sie ihre Macht vom Propheten wiedererlangen kann.\n\nDer Rest wird an Euch liegen, {name}. Ihr müsst den Propheten in seinem ausgelaugten Zustand erschlagen.", sourceObjective = "Erschlagt den ausgelaugten Propheten von Quetz'lun und informiert anschließend Hexendoktor Khufu in Zim'Torga.", completion = "<Der Hexendoktor schüttelt ungläubig den Kopf.>\n\nEs hört sich an, als wärt Ihr Quetz'luns Unterwelt gerade noch lebend entkommen.\n\nIch bin froh, dass es Euch gibt. Ich weiß nicht, ob ich den Mut gehabt hätte, um mit dieser Situation fertig zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12686] = { id = 12686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null Toleranz", description = "Ignoranz! Unerträglich ist das, Mann! Meine ganze Ladung Seuche ist zu nichts zu gebrauchen!\n\nDieser Bastard Darmuk! Er war dafür verantwortlich, ein Auge auf die Seuche zu werfen, doch enttäuscht hat er mich, Mann, enttäuscht!\n\nDas wird dir eine gute Lektion sein, {name}. Versagen ist wie ein gefährlicher Virus: Du musst schnell sein, ihn einfangen und töten, bevor er dich tötet!\n\nNimm dieses Szepter, es wird meine verseuchten Trolle stärker machen, damit du sie dann auf Darmuk hetzen und ihn töten kannst. Er liegt dort unten im Süden auf der Lauer.\n\nLass dies ein Beispiel für alle sein, Mann: Enttäusch Drakuru nich'!", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr zum Reliquiar des Schmerzes geht und das Ermächtigungsszepter auf einen Diener von Drakuru anwendet, um anschließend mit seiner Hilfe Darmuk zu töten.", progress = "Hat Darmuk für sein Versagen schon bezahlen müssen, {name}?", completion = "Gut gemacht, {name}. Du lernst schneller, als ich gedacht habe.\n\nGeh jetzt und ruh dich etwas aus. Bald werde ich dich einer noch größeren Prüfung unterziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12687] = { id = 12687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Reich des Schattens", description = "Das Pferd, das Ihr gestohlen habt, wurde ins Reich der Schatten verschleppt. Dort wird mein dunkler Reiter das Biest niederstrecken und es wieder als Todesstreitross auferstehen lassen. Denkt Ihr, dass Ihr den Mut besitzt, dem Ross hinterher ins Reich des Schattens zu folgen?\n\nSolltet Ihr einwilligen, werde ich Euch dorthin befördern. Geht nach Süden, sobald Ihr dort angekommen seid, und sucht auf den Feldern nach einem der dunklen Reiter. Um den Sieg davonzutragen, müsst Ihr ihn niederstrecken, sein Todesstreitross übernehmen und es wieder zur Todesanhöhe bringen. Lasst den Ruf des Reiters ertönen, falls Ihr erfolgreich sein solltet.", sourceObjective = "Salanar der Reiter auf der Todesanhöhe hat Euch dazu herausgefordert, einen dunklen Reiter von Acherus zu erschlagen und sein Todesstreitross von Acherus in Eure Gewalt zu bringen.\n\nBringt das Todesstreitross von Acherus auf die Todesanhöhe und lasst den Ruf des Reiters ertönen, um Salanar herbeizurufen.", completion = "Ihr hattet dort Erfolg, wo andere Initianden fehlschlugen, {name}. Dafür werdet Ihr großzügig belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12688] = { id = 12688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Desaster konstruieren", description = "Diese idiotischen Goblins und ihre Anhänger haben beschlossen, dass diese Säule und ihre Kristalle nun ihnen gehören. Ich kam hierher, um die Kristalle zu untersuchen und Proben zu sammeln, aber sie haben mich überwältigt und wollten mich nicht zum Lager zurückkehren lassen.\n\nWenn Ihr mir helft, hier auszubrechen, können wir diesen Schlägern eine Lektion erteilen, die sie nie vergessen werden!", sourceObjective = "Helft Ingenieurin Helice, aus Schwindelgrins' Grabungsstätte zu entkommen, und sprecht dann mit Hemet Nesingwary in Nesingwarys Basislager.", completion = "Danke, dass Ihr Helice befreit und ihr zu einer sicheren Rückkehr verholfen habt. Wir waren alle bereits voller Sorge, als sie nicht von ihrer Suche nach Kristallen zurückkehrte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12689] = { id = 12689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand der Orakel", sourceObjective = "Hallo! Freut mich sehr, dich wiederzusehen!\n\nIch wusste, wir Freunde. Ich wusste es! Du guter Freund. Nicht nur von uns, sondern von allen Orakeln. Danke, dass du uns gerettet hast! Danke, danke!\n\nIch gesehen, wie du Wauwau gut verprügelt hast! Untotes Ding gesagt, dass ihr einmal gute Freunde - stimmt das? Ich davon nichts wissen. Doch du Wauwau fertig gemacht haben, oder? Du jetzt nur noch Freund von Orakel?\n\nHalt! Nicht zustimmen ohne Nachdenken. Du sicher nicht mehr Freund sein willst von Wauwauleuten?", sourceObjectiveStatus = "unverified-source-field" }
quests[12690] = { id = 12690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennstoff", description = "Es wird Zeit, dass wir auf Gundrak marschieren, Mann. Es wird Zeit, dass ich dich auf diese Trolle loslasse!\n\nSie sind durch unsere Mauern gestoßen und haben gleich nördlich von hier eine ganze Armee in Stellung gebracht.\n\nHahaha!\n\nSie werden nichts weiter als Brennstoff sein, Mann! Wir werden die Häuptlinge gefangen nehmen und den Rest töten! - alles Teil meines eigentlichen Plans...\n\nHier, nimm dieses Szepter und befiehl meine Monstrositäten. Schick sie zur Drakkariarmee und lass sie alle töten! Sobald die Häuptlinge auftauchen, wird mein Begleiter Schieferschwinge herbeieilen, sie ergreifen und hierher zu mir bringen.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr das Szepter des Befehls auf die aufgeblähten Monstrositäten anwendet und dann ihre Fähigkeiten dazu einsetzt, um 60 Schädelberster der Drakkari zu töten und 3 Häuptlinge der Drakkari hervorzulocken.\n\nDie Häuptlinge tauchen erst dann auf, wenn genug Schädelberster getötet wurden.", progress = "Hast du die Trolle platt gemacht, {name}?", completion = "Wir haben es geschafft, Mann!\n\nIch habe die Häuptlinge eingesperrt und du hast mithilfe meiner Monstrositäten den Sieg über ihre Armeen davongetragen.\n\nZeit zu feiern, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12691] = { id = 12691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verwitterte Kiste", description = "Die steinerne Kiste scheint verschlossen zu sein. Offensichtlich passt ein Schlüssel in das große Schlüsselloch aus Stein.\n\nVielleicht besitzt einer der Wächter in der Nähe diesen Schlüssel.", sourceObjective = "Erbeutet einen gewaltigen, steinernen Schlüssel von einem der Sholazarwächter in der Nähe und bringt ihn zur verwitterten Kiste bei der Warte der Schöpfer.", progress = "Die Steinkiste rührt sich nicht.", completion = "Der gewaltige, steinerne Schlüssel dreht sich mit einem tiefen Knarzen und die Kiste öffnet sich, um den verborgenen Schatz im Inneren zu enthüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12692] = { id = 12692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Lichjägers", description = "Gut, ich kehre zum Hügel der Wildherzen zurück, damit auch alle Wildherzen wissen, was du für Wolvar und Zepik getan. Du großer Jäger und sie so dumm, das nicht zu glauben.\n\nGeh zu Hügel zurück und sprich mit Ältesten Harkek... Ich sorge dafür, dass er erster Wildherz seien, der weiß, dass du kein Verräter.\n\nDanke, Lichjäger.", sourceObjective = "Kehrt zum Hügel der Wildherzen zurück und sprecht mit dem Ältesten Harkek.", completion = "Es gut, dich wiederzusehen. Ich wusste, du kein Verräter, ich froh, dass Zepik bewiesen hat.\n\nIch höre, du nun Lichjäger - das ziemlich gut! Du machst Harkek stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[12695] = { id = 12695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der netten Trockenhaut", description = "Juhu! Soo-say wohl sorgen um uns! Vielleicht du gehst zurück zu Stadt und sagst ihm, dass alles in Ordnung? Ja, geh und erzähl Soo-say.\n\nIch werde glänzendes Kugelding von totem Lichkerl schnappen - ich dich dort treffen! Geh, geh! Ich dich dort treffen!", sourceObjective = "Kehrt zum Baldachin der Regenrufer zurück und sprecht mit dem Hochorakel Soo-say.", completion = "Gut, dich wiederzusehen! Wir besorgt, als du nicht sofort zurückkamst.\n\nJaloot dich zurückgetrieben - viel Energie in Jaloot, er sehr schnell. Er mir erzählte, wie du ihn vor Lichding gerettet. Moodle mir erzählt, wie du auch Mooswandler gerettet. Du wirklich nett.\n\nIch hoffe, du bei uns eine Weile bleibst. Immer etwas zu tun hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[12696] = { id = 12696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberwachung", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordosten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.", sourceObjective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.", completion = "Die Professorin hat Euch zu mir geschickt? In Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12697] = { id = 12697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gothik der Ernter", description = "CHAOS, {name}! Der Kreuzzug ist wild geworden. Sie haben alle Streitkräfte außerhalb von Neu-Avalon dazu abbestellt, eine Blockade am Lichtgipfel östlich von hier zu errichten. Sie versuchen wie verzweifelt die Mine von Havenau leerzuschürfen und das Erz auf die Fregatten zu verladen, die an der Küste vor Anker liegen.\n\nNa dann lasst uns mal ein wenig Unruhe stiften. Gothik der Ernter, Großnekromant des Lichkönigs, hat uns mit seiner Anwesenheit gesegnet. Er hält ein Geschenk parat, das er gerne dem Scharlachroten Kreuzzug machen würde... Sucht ihn auf.", sourceObjective = "Sprecht mit Gothik dem Ernter in der Todesbresche.", completion = "Ihr habt hart gekämpft, um in das Reich des Ernters einzudringen... Wartet.\n\n<Gothik betrachtet seine Notizen.>\n\nIch möchte mich entschuldigen, {race}. Alte Gewohnheiten wird man nicht so schnell los.\n\nValanar hat Euch also geschickt? Ich kann mich dann darauf verlassen, dass Ihr eine gewisse Kompetenz besitzt.\n\nIch habe ein Geschenk für diese Hunde vom Scharlachroten Kreuzzug. Eines, das ihre Arbeit in den Minen sicherlich vorantreiben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12698] = { id = 12698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk, das nicht aufhört zu schenken", description = "Ich bin aus dem gefrorenen Innersten von Naxxramas gekommen, um mich an Seelen gütlich zu tun und unseren Todfeinden eine ordentliche Tracht Prügel zu verpassen - nur leider gibt es keine Seelen mehr.\n\nDieses Gerät, das ich Euch gleich geben werde, ist ein tragbarer Seuchenverbreiter. Nehmt ihn, geht nach Osten zu den Minen von Havenau und entfesselt ihn auf die Scharlachroten Minenarbeiter, die dort drinnen arbeiten. Verwandelt die Minenarbeiter mit seiner Hilfe in Ghule und kehrt zu mir zurück, wenn Ihr eine kleine Armee um Euch gesammelt habt. Für sie habe ich einen besonderen Platz im Seelenstaubsauger freigehalten!", sourceObjective = "Gothik der Ernter in der Todesbresche hat Euch die Gabe des Ernters gegeben, um sie gegen die Scharlachroten Minenarbeiter einzusetzen. Erschafft mithilfe des Geräts 5 Scharlachrote Ghule und kehrt anschließend zu Gothik zurück.", progress = "Eine kleine Anmerkung: Minenarbeiter werden nicht immer zu Ghulen. Manchmal verwandeln sie sich in wütende Geister, die fest dazu entschlossen sind, Euch zu töten.", completion = "Sie wissen, dass die Minenarbeiter nicht länger sicher sind. Sie werden sich nun umso schneller zurückziehen, mit dem Rücken zu uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[12699] = { id = 12699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der peinliche Vorfall", description = "Es gibt da ein kleines Problem zu lösen, bevor wir losziehen können. Wisst Ihr, ich kann den Schlüssel für meine Flugmaschine einfach nicht finden.\n\nIch hab' so ziemlich überall nach ihm gesucht... Vielleicht könnt Ihr mir helfen. Es gibt nur noch einen Ort, an dem ich noch nicht gesucht habe: im See.\n\nIch werde Euch sogar meinen eigenen Lufttank zur Verfügung stellen. Er ist zwar fast leer, hat jedoch noch genug Luft für ein paar Atemzüge.", sourceObjective = "Sucht nach Vics Schlüssel im See am Flussnabel.", progress = "Habt Ihr schon was gefunden, {name}?", completion = "Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[12700] = { id = 12700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheitsangriff", description = "Nur die Streitkräfte des Scharlachroten Kreuzzugs bei Neu-Avalon und dem Lichtgipfel stellen noch eine Herausforderung dar! Die Zeit, die Scharlachrote Flotte beim Lichtgipfel anzugreifen, ist gekommen.\n\nDas Ablenkungsmanöver an der Mine hat sie ins Chaos gestürzt. Sie versuchen verzweifelt, die Gegend freizuräumen und zu ihren Schiffen zurückzukehren.\n\nDie Zeit ist reif! Prinz Valanar nutzt die Gelegenheit, um ihrer Flotte den letzten Stoß zu versetzen. Meldet Euch bei ihm - umgehend!", sourceObjective = "Sprecht mit Prinz Valanar in der Todesbresche.", completion = "Ihr habt uns gut gedient, {class}. Nur wenige Eurer Brüder haben den ersten Angriff auf die Eindringlinge des Scharlachroten Kreuzzugs überlebt. Ihr seid als einer der Stärksten hervorgegangen.\n\n\n\nÖstlich von uns jenseits der Mine von Havenau liegt die Küste - vom Scharlachroten Kreuzzug \"Lichtgipfel\" genannt. Zwischen uns und ihren Schiffen stehen Eintausend ihrer Soldaten. Unüberwindlich? Davon kann kaum die Rede sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[12701] = { id = 12701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massaker am Lichtgipfel", description = "In ihrer Eile werden die Diener des Scharlachroten Kreuzzugs einen schwerwiegenden Fehler begehen: zu vergessen, ihre Loren zu überprüfen.\n\nIhr sollt nach Osten zur Mine von Havenau reisen und die Lore finden, die meine Diener am Nebengebäude abgestellt haben. Klettert dann hinein und ein Scharlachroter Minenarbeiter wird sich unwissentlich darum kümmern, dass Ihr sicher hinter die feindlichen Linien gebracht werdet.\n\nSobald Ihr dann an Bord eines ihrer Schiffe seid, sollt Ihr ihre Kanonen gegen sie verwenden! SCHLACHTET SIE ALLE AB!\n\nRuft den Geißelgreif herbei, wenn Ihr bei der Kanone steht, und er wird Euch sicher wieder zurückbringen.", sourceObjective = "Prinz Valanar in der Todesbresche hat Euch befohlen, 100 Scharlachrote Verteidiger zu vernichten.", progress = "{class} kennen keine Angst!", completion = "Ihr habt die gesamte Flotte des Scharlachroten Kreuzzugs in wenigen Minuten ausradiert! Ich werde vom Lichkönig dafür eine Auszeichnung erhalten! Alles, was vom Scharlachroten Kreuzzug noch übrig bleibt, sind die Bewohner von Neu-Avalon.\n\nIch werde die Brandstifter und Nekromanten umgehend auf Havenau ansetzen. Ihr werdet meinen Report zum Hochlord bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12702] = { id = 12702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnerparty!", description = "Ich wette, Ihr nicht ratet, was schon wieder passiert.\n\nNe, nicht Goregek oder Hühner.\n\nJa, gut, ich lüge. Goregek schon wieder Hühner frei gelassen. Dummer Goregek mit hungrigem Bauch.\n\nLass mich wissen, wenn du brauchst Hilfe von einem der Jäger... sie hier irgendwo in der Nähe.", sourceObjective = "Fangt 12 entflohene Hühner für Ältesten Harkek auf dem Hügel der Wildherzen.", progress = "Hühner normalerweise nicht weit kommen... Wenn Wespen sie nicht essen, vielleicht wir sie einfach das nächste Mal draußen auf Feld lassen.", completion = "Du gut darin.\n\nVielleicht wir eines Tages Goregek einfach in Fluss fallen lassen, damit du das nie wieder machen musst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12703] = { id = 12703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kartaks Wut", description = "Du der große Lichjäger, he? Gut, so starken Wildherzverbündeten in Kampf zu haben. Vielleicht du stark genug, sogar Kartak zu rufen.\n\nGroßer Kampf bei Kartaks Stellung im Südwesten. Geh und töte Funken-Großzungen, bis du kriegst gute Menge von Orakelblut. Bring Blut zu Altar in Kartaks Stellung, um Kartak für schmackhafte Gelage von Großzungen zu rufen.\n\nKartak nimmt deinen Körper, wenn du würdig... Mit Kartaks Kraft du tötest mehr Großzungen als in besten Träumen.\n\nGeh und töte viele, Jäger!", sourceObjective = "Bringt eine reine Probe vom Blut der Orakel zum Altar von Kartak, um Kartak zu beschwören. Mit der Hilfe von Kartaks geteilten Kräften sollt Ihr für Schamanen Jakjek in Kartaks Stellung 50 in der Nähe befindliche, funkenbesprühte Gorlocs töten.", completion = "Ritual ging so leicht für dich!\n\nDu eines Tages kommst zurück für mehr Töten, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12704] = { id = 12704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besänftigung des großen Regensteins", description = "Seit Mooswandler angegriffen wurden, ich in Sorge, wir vielleicht nicht gut zu Großem Regenstein... wir vielleicht zu gierig. Wir müssen mehr Schätze opfern!\n\nDu letztes Mal gut darin, Glitzers zu finden... vielleicht du suchst um Dorf herum nach mehr Glitzers? Du womöglich brauchst einen von guten Regenrufern zu Hilfe. Sag uns nur, wen.", sourceObjective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr einen Gefährten auswählt und 6 glänzende Kostbarkeiten sammelt.\n\nSprecht noch einmal mit dem Hochorakel Soo-say, um Euch die Hilfe eines Eurer früheren Gefährten zusichern zu lassen.", progress = "Nie genug Glitzers... Großer Regenstein gut zu uns, wir müssen gut sein zu Großer Regenstein.", completion = "So viele gute Glitzers! Du gut darin.\n\nKomm zurück später für mehr, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12705] = { id = 12705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wille der Titanen", description = "Wauwaumenschen angreifen Funkenbesprühten... wir müssen kämpfen oder sie nur angreifen auch andere Orakel.\n\nDu gut Freund von uns, also wir erlauben dir vielleicht besondere Ehre. Die Großen haben vor langer Zeit hinterlassen Beschützer für Schreine... Er immer noch hier, aber er nicht wissen, etwas falsch, bis Schreine verwüstet.\n\nWauwaumenschen da unten haben böse Kristalle zum Ärgermachen... Bring einen bösen Kristall zu Blitzschrein, damit Soo-holu weiß, dass er helfen.\n\nErschreck nicht, wenn Soo-holu deinen Körper nimmt... er sehr mächtig, also er dich beschützt.", sourceObjective = "Erlangt einen getrübten Kristall von den Wolvar in der Nähe der Zuflucht der Funkenbesprühten und bringt ihn zum großen Blitzstein, um Soo-holu zu beschwören. Tötet mithilfe Soo-holus geteilter Macht 50 in der Nähe befindliche Wolvar der Wildherzen und kehrt anschließend zu Blitzrufer Soo-met in der Nähe des großen Donnersteins zurück.", completion = "Soo-holu stark, hm? Ich sehr froh, dass er zugestimmt, seinen Körper mit dir für Kampf zu teilen.\n\nEr mehr Vertrauen in Leute, die er schon vorher getroffen, also vielleicht komm zurück ein anderes Mal, um mehr zu helfen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12706] = { id = 12706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg an der Todesbresche!", description = "<Prinz Valanar händigt Euch eine versiegelte Schriftrolle aus.>\n\nDies ist der komplette Bericht über Euren Sieg bei der Todesbresche. Bringt ihn zu Hochlord Mograine in Acherus. Ich habe dafür gesorgt, dass in dem Report von Euren Heldentaten die Rede ist. Mograine wird Euch zweifellos für diesen Sieg belohnen, {name}.\n\nNun geht!", sourceObjective = "Liefert Prinz Valanars Bericht bei Hochlord Darion Mograine in Acherus: der Schwarzen Festung ab.", progress = "Ich war mir sicher, dass Ihr es nicht mehr in einem Stück zurückschaffen würdet, {class}. Vielleicht steckt doch mehr in Euch, als ich zuerst vermutet habe.", completion = "<Hochlord Mograine liest sich den Report durch.>\n\nDie gesamte Flotte des Scharlachroten Kreuzzugs?\n\n<Hochlord Mograine nickt.>\n\nSolch Macht, {name}... Solch eine Darbietung von Dominanz habe ich schon seit Jahren nicht mehr gesehen... seit mein Vater...\n\n\n\nEs ist nicht wichtig...\n\nJa: Eure Auszeichnung - bevor ich sie vergesse.", sourceObjectiveStatus = "unverified-source-field" }
quests[12707] = { id = 12707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollige Gerechtigkeit", description = "Ahunae hat über deine Reise zum Krater Mam'toth gehört, Mann. Die Kinder von Mam'toth sind erzürnt und schreien nach Gerechtigkeit!\n\nFolg der Allee in Richtung Nordosten die Stufen hoch zur nächsten Ebene von Zul'Drak. Zu deiner Rechten wirst du die Überreste des Altars von Mam'toth finden.\n\nHalt' das Medaillon von Mam'toth einem tobenden Mammut vor die Nase, wenn du dort bist. Es wird sich dann für eine Weile beruhigen, was dir die Chance gibt, auf seinen Rücken zu springen.\n\nReite anschließend mit ihm alle Jünger von Mam'toth nieder, die dir über den Weg laufen!", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr mithilfe des Medaillons von Mam'toth ein tobendes Mammut beruhigt, um dann auf ihm zu reiten. Anschließend sollt Ihr 12 Jünger von Mam'toth zu Tode trampeln.", completion = "Erster Punkt für die Opfer, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12708] = { id = 12708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Tikikrieger", description = "Ich weiß, dass Ihr Euch auf dem Weg zur Festung von Zol'Maz gen Nordosten befindet, {class}. Ich möchte, dass Ihr Euch um die Spezialwächter des Kriegsfürsten kümmert, wenn Ihr schon einmal dort seid.\n\nDie verzauberten Tikikrieger, wie sie genannt werden, stellen eine äußerst reelle Gefahr dar. Sollten die Drakkari sie in Massen produzieren, würden wir recht schnell überrannt werden.\n\nNa dann wollen wir ihnen mal zeigen, dass es sich nicht lohnt, die Dinger zu erschaffen.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 12 verzauberte Tikikrieger zerstört.", completion = "Jetzt werden sie es sich wahrscheinlich zweimal überlegen, bevor sie mehr von diesen Dingern herstellen. Mich schaudert der Gedanke daran, wie es sein würde, wenn wir gegen eine ganze Armee dieser Dinger kämpfen müssten.\n\n<Der Elementzähmer scheint, einen Moment lang in Gedanken versunken zu sein.>\n\nIch nehme einmal an, dass es genauso wäre, als würde man gegen die endlosen Wellen der Geißel ankämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12709] = { id = 12709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexte Behälter", description = "Entschuldigt, {name}, mir scheint, Ihr seid unterwegs nach Nordosten zur Festung Zol'Maz? So eine Reise wäre für uns eine großartige Gelegenheit, unsere Sammlung der Schätze der Drakkari zu vollenden.\n\nIch habe erfahren, dass der Kriegsfürst der Drakkari extrem paranoid ist. Alle seine Behältnisse in der Feste hat er mit schrecklicher Magie verhexen lassen. Es wird gemunkelt, dass die Tikikrieger das Heilmittel haben - aber wer weiß das schon genau?\n\nWenn Ihr Euch die Zeit nehmen würdet, mir ein paar der Behälter zu holen, wäre ich Euch ziemlich dankbar.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 12 Behälter der Festung Zol'Maz sammelt.", progress = "Kann es sein, dass sich die Behältnisse in Eurem Rucksack befinden?", completion = "Seht Euch das alles nur mal an!\n\nSeht Euch dies an, {name}. Dieses von Euch mitgebrachte Exemplar zeigt es deutlich: Die Drakkari erkannten, dass das Land durch die Anwesenheit der Geißel schwächer wurde.\n\nDer Kriegsfürst fühlte sich dazu gezwungen, die sich dadurch bietende Gelegenheit wahrzunehmen. Er drängte die Propheten dazu, Ihre Götter zu töten, um deren Macht zu beherrschen und die Streitkräfte des Lichkönigs zurückzudrängen.\n\nSie waren so oder so dem Untergang geweiht. Sie waren somit unbewusst für ihre eigene Zerstörung verantwortlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[12710] = { id = 12710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllung", description = "Gute Arbeit, {name}.\n\nDu bist der Beweis, dass ich'n Auge für Talent besitze! Nun siehst du, weshalb mir der Lichkönig seinen Segen gegeb'n hat...\n\nDie Zeit is' gekommen, dir meinen eigentlichen Plan zu enthüllen, Mann.\n\nNun wirst du seh'n, wie wir über die Schwärme der Drakkaritrolle hinwegfegen werd'n, um unseren angestammt'n Platz im großen Palast von Gundrak einzunehmen.\n\nNimm dieses Szepter, Mann. Es is'n Zeichen meines Vertrauens in dir. Es wird dir Zugang zu meinen oberen Gemächern gewähren, damit du selbst Zeuge unserer Geheimwaffen sein kannst.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr den Teleporter benutzt, der in sein oberes Gemach führt.", progress = "Hast du meine Schöpfungen mit eigenen Augen sehen können, {name}?", completion = "So, da hast du es also, Mann.\n\nWir werden die ultimative Geißelarmee erschaffen und sie wird dem Lichkönig dienen. Er wird äußerst zufrieden sein!\n\nDu kannst das Szepter behalten, {name}. Du wirst es brauchen, um meine Armee in die Schlacht zu führen...\n\nSchon bald!", sourceObjectiveStatus = "unverified-source-field" }
quests[12711] = { id = 12711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrenlose Post", sourceObjective = "Auf dem Briefkasten liegen einige unleserliche Briefe und Schriftrollen. Nutzlos…\n\nVielleicht solltet Ihr mal hinein schauen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12712] = { id = 12712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel des Kriegslords Zol'Maz", description = "{name}, wir benötigen einen Schlüssel, um die Ketten des Nashorngottes Akali zu lösen. Selbst jetzt, während wir hier noch reden, ist er auf dem Weg zur Schlachtbank.\n\nDer Drakkarikriegslord Zol'Maz trägt den Schlüssel bei sich. Als er von Euren Heldentaten erfuhr, hat er sich mitsamt seiner Familie in sein Bollwerk zurückgezogen; die Stufen hoch gen Nordosten.\n\nDer Kriegslord ist stark und Ihr werdet Hilfe benötigen. Solch Hilfe ließe sich herbeirufen, indem Ihr während des Kampfes vor seinen Toren das Tiki, das Schwert und die Zauberformeln seiner Familienmitglieder miteinander kombiniert.", sourceObjective = "Har'koa in Zim'Torga möchte, dass Ihr den Schlüssel des Kriegslords Zol'Maz beschafft.", progress = "Ich kann nicht genug betonen, wie wichtig es ist, dass wir den Schlüssel des Kriegslords um jeden Preis in die Hände zu bekommen.", completion = "Es wäre vielleicht besser gewesen, wenn ich Euch darum gebeten hätte, ihn direkt nach Gundrak zu bringen anstatt hierher.\n\nIch denke jedoch, dass es am besten ist, wenn Ihr zuerst hört, was ich noch zu sagen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12713] = { id = 12713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat", description = "Die Zeit ist gekommen, um dieser Scharade ein Ende zu setzen, {name}.\n\nSo wertvoll Eure Informationen auch sein mögen, wir müssen Drakuru erledigen und sein Projekt stoppen, bevor seine verrückten Spießgesellen auf die Welt losgelassen werden.\n\nWir haben Euer Szepter für die Aufgabe modifiziert. Wenn die Zeit reif ist, werdet Ihr es gegen Drakurus Seuchenbluttrolle einsetzen und sie damit gegen ihren eigenen Meister aufhetzen. Es ist Eure einzige Chance, ihn zu vernichten.\n\nKämpft gut.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr Drakuru besiegt.\n\nFalls Ihr Euren bezauberten Halsreif verlieren solltet, dann kehrt zu Stefan in der Schwarzen Wacht zurück und besorgt Euch einen neuen.", progress = "Habt Ihr Euch Drakuru schon gestellt, {name}?", completion = "So, es ist vollbracht.\n\nEs gibt noch immer viel zu tun, doch Dank Euch wird unsere Arbeit hier viel einfacher sein.\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12714] = { id = 12714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Lichkönigs", description = "Es ist der Wille des Lichkönigs, der uns vorantreibt, {name}. Niemand ist sich dessen mehr bewusst, als die Todesritter. Unsere schiere Existenz ist mit seinem Bewusstsein verbunden. Sicherlich habt Ihr ihn zu Euch sprechen hören, habt gespürt, wie er in Eure Gedanken eindringt...\n\nKönnt Ihr ihn jetzt hören? Vielleicht ist es zu früh für Euch.\n\n<Mograine schließt seine Augen und es scheint, als nickte er jemandem zu.>\n\nJawohl, mein Fürst. Es wird vollbracht werden.\n\n{name}, Ihr sollt zur Todesbresche zurückkehren und Euch bei Prinz Valanar melden. Der Lichkönig befiehlt es!", sourceObjective = "Kehrt zur Todesbresche zurück und meldet Euch bei Prinz Valanar.", completion = "Havenau ist unser! Tausend Leichen liegen auf dem Boden verstreut und warten nur auf ihre Wiedergeburt. Jetzt werden wir die Kraft der Geißel auf unseren Feind entfesseln!\n\nDie Ghule haben schon mit ihrem Angriff auf Neu-Avalon begonnen. Unsere Streitkräfte sind ihnen gefolgt und haben die Krypta der Erinnerung eingenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12715] = { id = 12715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krypta der Erinnerung", description = "Die Angriffe auf die Tore der letzten Bastion des Scharlachroten Kreuzzugs haben begonnen. Unsere Ghule sind dabei, ihre Streitkräfte an den Frontlinien zu zermürben, während wir hart daran arbeiten, die Verteidigung unserer Basis an vorderster Front zu verstärken - damit meine ich die Krypta der Erinnerung.\n\nGeht nach Süden zur Krypta - sie liegt gleich bei Neu-Avalon - und meldet Euch bei meinem verehrten Bruder Prinz Keleseth.\n\nEr wird Euch erwarten.\n\nMacht Euch bereit, {name}, denn Ihr werdet Zeuge der nächsten Stufe unserer Kriegsführung sein: DOMINANZ!\n\nReitet aus, Todesritter!", sourceObjective = "Meldet Euch bei Prinz Keleseth in der Krypta der Erinnerung.", completion = "Seid gegrüßt, {class}. Ich bin Blutfürst Keleseth, Herrscher über die südöstlichen Gebiete Nordends. Der Lichkönig möchte mich und meine Fähigkeiten dazu einsetzen, diesen Sterblichen, dieser Beleidigung in den Augen der Geißel, ein Ende zu setzen. Wie mit allen Dingen, die der Lichkönig von mir verlangt, so werde ich auch jetzt mit Freude gehorchen. Meinen Durst mit einem Meer an endlos vielen Seelen zu stillen, versüßt natürlich die Sache, meint Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12716] = { id = 12716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Seuchenfürstens Gesuch", description = "Seht Euch dieses Kürbisbeet an! Merkt Ihr, dass irgendetwas fehlt? Natürlich merkt Ihr das nicht - und wisst Ihr warum? Weil Ihr ein Idiot seid! Euer Gehirn war womöglich das Erste, was gestorben ist.\n\n<Noth seufzt.>\n\nIch wurde dazu beauftragt, einen Seuchenkessel zusammenzustellen, und Ihr werdet mir dabei helfen.\n\nDirekt hinter dem Tor von Neu-Avalon befindet sich das Gasthaus. Dort sollt Ihr mir einen leeren Kessel stehlen. Geht dann anschließend zur Schmiede, die sich auch gleich in der Nähe des Tores befindet, und besorgt mir eine Eisenkette. Bringt das Zeug gemeinsam mit zehn Kreuzfahrerschädeln zu mir. Soll ich Euch auch noch sagen, woher Ihr die Schädel bekommt?", sourceObjective = "Noth der Seuchenfürst möchte, dass Ihr ihm 1 leeren Kessel, 1 Eisenkette und 10 Kreuzfahrerschädel bringt.", progress = "Habt Ihr die Materialien gesammelt, um die ich Euch gebeten habe?", completion = "Perfekt! Nun gebt mir einen Moment lang Zeit, damit ich die Vorbereitungen treffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12717] = { id = 12717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noths Spezialgebräu", description = "Der Kessel kann nun seine faule Verderbnis ausspeien und über das Land verbreiten!\n\nNun, Todesritter: Eine kurze Lektion in Sachen Seuchenkessel. Das Gas des Kessels ist für alles Lebendige tödlich, erfüllt die Diener der Geißel jedoch mit Macht. Wie alle Schöpfungen der Geißel ernährt sie sich vom Tod und wird stärker, je länger sie sich nähren kann.\n\nNehmt diese Kreuzfahrerschädel und werft sie in den Kessel. Ihr werdet mit dem Resultat sehr zufrieden sein.", sourceObjective = "Werft den Haufen Kreuzfahrerschädel in den Seuchenkessel.", progress = "Der Kessel rührt sich nicht.", completion = "Der Seuchenkessel fängt an zu rasseln, als Ihr die Schädel hineinwerft.\n\nNach ein paar Sekunden tauchen ein paar Phiolen mit dunkler Flüssigkeit auf der Oberfläche auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12718] = { id = 12718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Totenschädel fürs Gebräu", progress = "Im Seuchenkessel blubbert und kocht das giftige Gebräu - überall dickes Gas verbreitend.\n\nHabt Ihr noch mehr Kreuzfahrerschädel, die Ihr hineinwerfen könnt?", completion = "Der Seuchenkessel fängt an zu rasseln, als Ihr die Schädel hineinwerft.\n\nNach ein paar Sekunden spürt Ihr die herrliche Wirkung der dunklen und schaumigen Flüssigkeit, auch Noths Spezialgebräu genannt." }
quests[12719] = { id = 12719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt kein Entrinnen", description = "Es wird schon ausreichen, wenn wir sie komplett vernichten, {name}. Und um das zu erreichen, wird es nicht genügen, dass nur ein paar Hundert hirnlose Ghule die Tore von Neu-Avalon angreifen. Wir müssen ins Allerheiligste des Dorfes vordringen und ihre Würdenträger beseitigen. Ihnen muss gezeigt werden, dass niemand der Geißel entkommen kann!\n\nMacht Euch auf den Weg in Richtung Südwesten zum Rathaus von Neu-Avalon und beseitigt den Bürgermeister. Sucht dort auch nach der Registratur von Neu-Avalon und bringt sie mir.", sourceObjective = "Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, Bürgermeister Quimby zu töten und die Registratur von Neu-Avalon zu beschaffen.", progress = "Es gibt kein Entrinnen!", completion = "Die Registratur wird uns Vieles über die Insekten des Scharlachroten Kreuzzugs verraten.\n\n<Keleseth blättert durch die Seiten der Registratur.>\n\nTodes- und Geburtsraten, doch was am allerwichtigsten ist: Logistik.\n\nSeht her, {name}, sie haben schon vier Schiffe ausgesandt. Lasst mich sehen... Worauf steuern sie zu?\n\n\n\nWAS? Das ist nicht möglich. Sie segeln nach Nordend!\n\nNeben den Koordinaten steht geschrieben: \"Scharlachroter Morgen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[12720] = { id = 12720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man Freunde gewinnt und Feinde beeinflusst", description = "Auf meinen Weltreisen habe ich mehrere interessante Entdeckungen gemacht. Habt Ihr zum Beispiel gewusst, dass man einem Mann jede auch noch so verheimlichte Wahrheit entlocken kann, indem man ihn nur richtig dazu ermutigt? Wie es das Glück so will, habe ich ein wenig \"Ermutigung\" zur Hand.\n\n<Keleseth nimmt etwas aus einer juwelenbesetzten Schatulle.>\n\nDies ist mein \"Überzeuger\", wie ich ihn nenne. Legt ihn an und zieht aufs Feld hinaus, Todesritter. Richtet das spitze Ende auf die Soldaten von Neu-Avalon. Findet die Wahrheit über den \"Scharlachroten Morgen\" heraus.", sourceObjective = "Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, die Wahrheit über den \"Scharlachroten Morgen\" herauszufinden.\n\nNehmt Keleseths Überzeuger aus der juwelenbesetzten Schatulle und bringt damit einen Scharlachroten Kreuzzügler zum Reden.", progress = "Wendet den Überzeuger auf einen Scharlachroten Kreuzfahrer an. Einer von ihnen wird letztendlich... brechen - äh, ich meine: aufgeben.", completion = "Ein Erwachen? Was für einen Unsinn redet Ihr da! Was für ein Idiot würde sein Volk schon mitten in die gefrorenen Weiten führen? Womöglich wird dieser Kurier jedoch die Antwort haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12721] = { id = 12721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale", description = "{name}, wir haben keine Zeit mehr. Ihr müsst den Schlüssel nehmen und Akali befreien.\n\nEr wird im Hof vor Gundrak, der Hauptstadt von Zul'Drak, gefangen gehalten. Akalis Ketten sind an vier Verankerungen befestigt. Um den Rhinozerosgott zu befreien, müsst Ihr jede einzelne von ihnen aufschließen.\n\nIn Gundrak wimmelt es nur so von Eistrollen. Ich glaube jedoch, dass Ihr mit der nötigen Vorsicht ohne große Gefahr hineinschleichen könnt.\n\nInformiert bitte den Hexendoktor, sobald Ihr die Sache erledigt habt.", sourceObjective = "Har'koa in Zim'Torga möchte, dass Ihr Akali befreit und danach Hexendoktor Khufu in Zim'Torga benachrichtigt.", completion = "Nein!\n\nSchon wieder wurde ein Gott vernichtet und seine Kräfte gestohlen. Und nun hat uns der Prophet von Akali direkt bedroht.\n\nWenn er kommt, dann wegen Har'koa. Wir können nicht zulassen, dass er auch noch ihre Kraft an sich reißt.\n\nEinmal mehr müssen wir die Götter um Rat bitten, {name}. Sie werden uns sagen, was getan werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[12722] = { id = 12722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Lämmer zur Schlachtbank", description = "Die meisten Menschen wären geflohen, sobald eine Nekropole der Geißel über ihren Köpfen erschienen wäre. Doch nicht so der Scharlachrote Kreuzzug!\n\nIch muss zugeben, dass ich unseren Austausch mit dem Kreuzzug doch recht genieße. Im Laufe der Jahre haben Schlachten zwischen ihnen und der Geißel zu einigen der tragischsten Ereignisse in der Geschichte der Menschheit geführt. Und trotzdem stehen wir hier - SCHON WIEDER - und kämpfen gegen sie!\n\nWir sollen ihnen nicht die Freuden der ewigen Knechtschaft unter der Herrschaft des Lichkönigs verwehren! Geht nach Neu-Avalon und erfüllt ihren Todeswunsch. Lasst niemanden am Leben.", sourceObjective = "Baron Totenschwur in der Krypta der Erinnerung hat Euch befohlen, 10 Soldaten des Scharlachroten Kreuzzugs und 15 Bürger von Neu-Avalon zu erschlagen.", completion = "Ihr seid ziemlich effektiv mit der Klinge, {name}. Vielleicht - mit des Lichkönigs Erlaubnis, versteht sich - wärt Ihr dazu geneigt, einer meiner Diener zu werden? Stratholme sucht nach einem neuen Bürgermeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[12723] = { id = 12723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter den Linien der Scharlachroten", description = "Ich habe Orbaz, Thassarian und Koltira ausgesandt, um hinter feindlichen Linien nach dem Kurier zu suchen. Sie haben die Scharlachrote Taverne ganz im Süden von Neu-Avalon zu ihrer Operationsbasis gemacht. Sie liegt hinter den zwei Obstgärten versteckt, neben der Kapelle der Scharlachroten Flamme. Ihr sollt bis zur Taverne vordringen und Euch bei Orbaz Blutbann melden. Er wird Euch über ihre derzeitige Lage aufklären.", sourceObjective = "Meldet Euch bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon.", completion = "Sieht so aus, als würden wir heutzutage jedem Einlass in den Dunklen Orden gewähren. Als mir das Geschenk zuteil wurde, war es anders - sehr anders!\n\nWas diesen Kurier angeht...", sourceObjectiveStatus = "unverified-source-field" }
quests[12724] = { id = 12724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des gerechten Kreuzfahrers", description = "Wir haben nicht den geringsten Hinweis darüber, wann und wo dieser Kurier erscheinen soll. Diese Menschen wussten auch nichts.\n\n<Orbaz deutet auf die Leichen des Scharlachroten Kreuzzugs, die über den Boden verteilt liegen.>\n\nAus dem letzten konnte ich noch etwas Nützliches herausprügeln. Im Inneren der Scharlachroten Festung befindet sich ein Plan, auf dem all ihre Patrouillen eingezeichnet sind. Ich möchte, dass Ihr in die Festung einbrecht und ihn stehlt.\n\nDie Wacht ist das größte Gebäude in Neu-Avalon nordöstlich von hier.", sourceObjective = "Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, die Patrouillenaufstellung von Neu-Avalon aus der Scharlachroten Festung zu stehlen.", progress = "Durchsucht alle Fugen und Ecken dieser Wacht! Der Plan ist dort!", completion = "<Orbaz blättert durch die Seiten des Plans.>\n\nDiese nutzlosen Scheusale sind geschäftig gewesen! Patrouillen im Norden, Süden, Westen und Osten, doch kein Wort über ihre Kurierwege. Wartet. Was ist das? Es sieht so aus, als gäbe es eine Patrouille, die von den westlichen Pestländern ausgeht. Und sie wird heute genau hier vorbeikommen! Ich brauche etwas Zeit zum planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12725] = { id = 12725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Tode vereint", description = "Durch die Linien des Scharlachroten Kreuzzugs zu brechen, war keine einfache Aufgabe. Wir mussten während des Angriffs hohe Verluste hinnehmen und verloren einen unserer besten Todesritter: Koltira Todesweber. Ich weiß nicht, ob er tot oder am Leben ist, doch ich soll verdammt sein, wenn wir nicht nach ihm suchen würden.\n\nAls ich ihn das letzte Mal sah, war er in Ketten gelegt und wurde zur Scharlachroten Festung nordöstlich von hier verschleppt. Durchsucht jeden Winkel dieser Festung, Todesritter. Findet Koltira!", sourceObjective = "Sucht nach Koltira Todesweber in der Scharlachroten Festung.", completion = "Es war töricht, mir zu folgen. Ich habe versagt. Sie hätten mich sterben lassen sollen - nun werden womöglich zwei von uns getötet werden.\n\n<Koltira schüttelt den Kopf.>\n\nWir sind {class} der Geißel - das ist dem Bündnis der dunklen Bruderschaft ein Dorn im Auge.\n\nThassarian, du verdammter Trottel!", sourceObjectiveStatus = "unverified-source-field" }
quests[12726] = { id = 12726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied von Wind und Wasser", description = "Du Sturm zugehört, ja? Das Sturmherrenschelf hallt mit uralten Liedern... das Lied von Wind und Wasser.\n\nDer große Sturm verschlingt die Söhne des Taifuns und des Unwetters. Hier, nimm diese Trommel und spiel sein Lied... Haifuns Lied.\n\nHilf ihm, Wind und Wasser aufzusaugen, damit Sturm weitermachen kann.", sourceObjective = "Soo-nee möchte, dass Ihr die Trommeln des Sturms auf dem Sturmherrenschelf verwendet und Haifun dabei helft, 3 Sturmwiedergänger und 3 Aqueousgeister zu verschlingen.", completion = "Ich danke dir, {name}. Dank dir wird uns der große Sturm freundlich gesonnen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12727] = { id = 12727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiger Ausbruch", description = "Der Alarm wurde geläutet. Der Hochinquisitor und seine Akolyten werden bald hier sein. Ich bin zu schwer verwundet, um von irgendwelchem Nutzen sein zu können, werde jedoch so gut wie möglich helfen.\n\nErschlagt den Hochinquisitor und seine Spießgesellen. Reißt ihm den Kopf ab und bringt ihn Thassarian. Rache wird seine barbarische Seele besänftigen.\n\nUnd noch etwas, {name}: Falls Ihr überleben und zurück zu Thassarian gelangen solltet, dann sagt ihm, dass sie in der Kapelle Gefangene hinrichten. Womöglich wird er Euch dann dorthin schicken, damit Ihr einmal mehr den Helden spielen könnt.", sourceObjective = "Erschlagt Hochinquisitor Valroth und bringt Valroths Kopf zu Thassarian in der Scharlachroten Taverne in Neu-Avalon.", progress = "Was ist mit Koltira?", completion = "Ich werde den Kopf dieses Monsters an die Ghule verfüttern!\n\n<Thassarian wirft den Kopf ins Hinterzimmer.>\n\nHat es Koltira wieder herausgeschafft?\n\n<Thassarian hält inne.>\n\nIch bin mir sicher, dass er's geschafft hat. Diese Mauern können ihn nicht lange halten.\n\nZeit, Rache zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12728] = { id = 12728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klamm beobachten: Höhlen der Winterflossen", description = "Ich muss meine Notizen zusammentragen und eine Präsentation für meine Kollegen in Dalaran vorbereiten.\n\nWährend ich das mache, muss ich Euch darum bitten, den Höhlen der Winterflossen im Norden einen Besuch abzustatten. Dort müsst Ihr Euch in den Eingang der Höhle stellen und das Arkanometer benutzen.\n\nKehrt umgehend zu mir zurück, sobald Ihr die Daten gesammelt habt. Ohne sie würde mein Material unvollständig sein.", sourceObjective = "Bibliothekar Garren vom Bernsteinflöz möchte, dass Ihr zu den Höhlen der Winterflossen geht und dort das Arkanometer benutzt.", completion = "Ausgezeichnet, jetzt ist mein Bericht komplett.\n\nIch werde den Rat auf jeden Fall von Eurer Gefälligkeit wissen lassen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12729] = { id = 12729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Götter haben gesprochen", description = "Die Götter haben gesprochen und wir müssen uns ihrer Weisheit beugen.\n\nGeht in den Norden nach Zim'Rhuk und vernichtet dort Wächter, bis sie Euch das unbefleckte Herz abtreten. Reist in den Osten zum Altar von Quetz'lun und bringt Unfrieden unter die Altarbehüter, bis Ihr ihre stürmische Essenz bergen könnt.\n\nBringt beides zu Har'koa und sie wird sie zu etwas zusammenfügen, das den verblichenen Akalipropheten zwingen wird, zu erscheinen.", sourceObjective = "Bringt das unbefleckte Herz des Wächters und die stürmische Essenz des Behüters zu Har'koa in Zim'Torga.", progress = "Habt Ihr, was benötigt wird, {name}?", completion = "Euer Heldenmut scheint grenzenlos, {name}.\n\nBitte gebt mir das Herz und die Essenz und ich werde sie in etwas verwandeln, das den Propheten zwingen wird, vor Euch zu erscheinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12730] = { id = 12730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörung bei Zol'Heb", description = "Ihr müsst dieses Beschwörungsjuwel nach Zol'heb gleich südlich von Gundrak bringen.\n\nDort befindet sich ein Kreis der Macht. Benutzt dieses Juwel und zwingt damit den Propheten von Akali zu erscheinen.\n\nMein Herz ist mit Euch, {name}. Gemeinsam haben wir schon viel durchgestanden und Ihr habt alles getan, was in Eurer Macht steht, um nicht nur mein Leben zu retten, sondern auch das der anderen Götter, die von den Drakkari vernichtet wurden.\n\nDoch ich fürchte, dass wir uns in diesem Leben nicht mehr wiedersehen werden.", sourceObjective = "Har'koa in Zim'Torga möchte, dass Ihr den Propheten von Akali tötet.", progress = "Das Einzige, was ich Euch anbieten kann, sind die Wärme meiner Worte und den damit verbundenen Herzenstrost.\n\nLasst Euch so viel Zeit wie nötig, um all Euren Mut zusammenzunehmen und bereit zu sein; doch ich flehe Euch an: Lasst Euch nicht zu lange Zeit oder der Prophet wird über uns kommen.", completion = "Ihr habt es geschafft! {name}, Ihr seid der Held von Zul'Drak!\n\nWir stehen in Eurer Schuld und werden diese doch nie begleichen können. Die Zandalari haben mir jedoch eine Reihe von Objekten anvertraut und meinen, dass sie Euch womöglich interessieren könnten.\n\nBitte, ich möchte, dass Euch dies gehört - ein Zeichen unserer Dankbarkeit - doch beeilt Euch. Ich spüre, dass es noch eine weitere wichtige Angelegenheit gibt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12732] = { id = 12732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Herzbluts Stärke", description = "Eines Tages Rejek mächtiger Krieger. Blut und Himmelsfeuer Rejek stark machen werden. Du bald siehst.\n\nRejek gibt dir Phiole, bringe sie zur obersten Spitze der Sonnenstrahlsäule, weit im Westen. Fülle Wasser in Phiole.\n\nDann du gehst nach Norden zu Grenze von Becken, zu Felsvorsprung nördlich von Knochenfelder. Du findest und tötest Blutklauenmatriarchin. Nimm Herzblut.\n\nDu mischt Herzblut und Wasser und bringst zu Rejek. Rejek trinkt, macht stark.", sourceObjective = "Bringt eine Phiole voll Sonnenstrahlherzblut zu Rejek auf dem Hügel der Wildherzen.", progress = "Du bringst Rejek Geschenk?", completion = "Rejek dankt dir. Rejek trinkt, wird stark, nie vergisst mächtiges Geschenk von {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12733] = { id = 12733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Todes", description = "Sie wurde ins Leben gerufen, als der Lichkönig auf den gefrorenen Weiten den Sieg über Illidan Sturmgrimm errang: Die Herausforderung des Todes ist ein Übergangsritus, den alle Todesritter über sich ergehen lassen müssen.\n\nSucht andere Todesritter von Acherus auf und fordert sie zu einem Duell heraus. Sie sind dazu verpflichtet, die Herausforderung zu akzeptieren und so lange zu kämpfen, bis ein Sieger hervortritt!\n\nGeht nun, {name}! Sieg der Geißel! Ehre dem Lichkönig!", sourceObjective = "Olrun die Schlachtenruferin hat Euch befohlen, 5 Duelle mit anderen Todesrittern zu gewinnen.\n\nIhr könnt gegen Initianden der Todesritter oder gegen Spieler kämpfen.", progress = "Habt Ihr die Herausforderung des Todes abgeschlossen?", completion = "Dem Sieger gehört der Ruhm, {class}! Gut gemacht! Die Gunst des Lichkönigs ist Euch an diesem Tage sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[12734] = { id = 12734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejek: Erstes Blut", description = "Rejek gerade jüngster Krieger in ganzem Stamm der Wildherzen geworden. Vater gab Rejek ein mächtiges Schwert, um Feinde der Wildherzen zu besiegen, aber alter Brauch sagt, Schwert muss erst Blut schmecken. Alter Krieger normalerweise das macht. Du Rejek diese Ehre machen?\n\nNimm Klinge, steche in Leichen aller Wildherzenfeinde: Wespen und Hartknöchel im Südwesten und Großzungen. Vielleicht Klinge in Blut von Nebelflüsterern tauchen, weit im Nordwesten bei Bittertidensee.", sourceObjective = "Taucht Rejeks Klinge in das Blut der Leichen von einer saphirblauen Schwarmwespe, einem Hartknöchelstürmer und 3 Mitgliedern des Stamms der Nebelflüsterer - es können entweder Orakel der Nebelflüsterer oder Krieger der Nebelflüsterer sein. Kehrt zu Rejek auf dem Hügel der Wildherzen zurück, sobald die Aufgabe abgeschlossen ist.", progress = "Du Rejeks Klinge in Blut gebadet?", completion = "Rejek sieht Blutspuren seiner Feinde auf der Klinge. Nun hat Rejek mächtige Waffe für mächtigen Krieger, der er wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[12735] = { id = 12735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein reinigendes Lied", description = "Erde in Sholazar ist sauber. Die Säulen haben das Land Jahrhunderte lang beschützt.\n\nWasser, nicht so sauber, kommt von draußen... von Meeren, von Seen, von Flüssen. Wasser bringt manchmal böse Geister mit - muss gesäubert werden.\n\nNimm dieses Glockenspiel und spiele am Bittertidensee, am Tausendwinterfluss und am Flussnabel. Das macht böse Geister wütend... und dann musst du sie töten.", sourceObjective = "Soo-nee beim Baldachin der Regenrufer will, dass Ihr am Bittertidensee, am Tausendwinterfluss und am Flussnabel das läuternde Glockenspiel erklingen lasst und die bösen Geister tötet, die das Wasser dort verschmutzen.", completion = "Wasser... gesäubert. Ja. Alles gut.\n\nDu verstehst uns, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12736] = { id = 12736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied der Besinnung", description = "Natürlich du nicht so schlau wie ein Gorloc! Du nur {race}.\n\nDu aber nicht hoffnungslos! Du zeigst, du kannst lernen. Vielleicht Kristalle machen dich schlau, wie Kristalle uns machen schlau!\n\nIch dich lehren Lied spielen, um Geist zu reinigen. Du spielst Lied bei Kristallen, dann Kristalle machen deinen Geist besser... nicht so gut wie den von Gorlocs, aber besser als jetzt. Lebensblutsäule kaputt, aber andere Säulen immer noch gut!", sourceObjective = "Soo-nee im Baldachin der Regenrufer möchte, dass Ihr das Didgeridoo des Nachsinnens auf der Spitze der Schimmersäule, der Sonnenstrahlsäule, der Mooslichtsäule und der Himmelszeltsäule verwendet.", completion = "Du sehen? Ich kann dir sagen, schon schlauer geworden. Und wenn nicht schlauer... dann... glücklicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[12737] = { id = 12737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied der Fruchtbarkeit", description = "Ein Sturm ist ein zerstörerisches Kraft. Sturm verbrennt Bäume. Sturm überflutet Häuser.\n\nDoch Sturm kann auch Leben spenden, wenn man kennt richtiges Lied. Bei Sturmherrenschelf über Hort der Schöpfer gibt es klein Dreckhügel. Die sehr fruchtbar - darin starke Samen. Warten nur auf richtiges Lied.\n\nDu nehmen dies Horn und spielen Lied für Samen.", sourceObjective = "Soo-nee beim Baldachin der Regenrufer möchte, dass Ihr zum Sturmherrenschelf nordwestlich des Horts der Schöpfer geht und das Horn der Fruchtbarkeit neben 8 Hügeln durchtränkten Mutterbodens blast.", completion = "Du lernen schnell, {name}. Du Lied gut gelernt. Vielleicht ich zeigen anderes Lied nächstes Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[12738] = { id = 12738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrei nach Rache!", description = "Der Schrei nach Rache darf nicht zu überhören sein, {name}. Kommandant Seuchenfaust hat sich mit einer Kompanie von Todesrittern auf den Weg gemacht, um die Kapelle der Scharlachroten Flamme dem Erdboden gleich zu machen. Falls dort irgendwelche Todesritter gefangen sein sollten, dann wird Seuchenfaust sie da rausbringen.\n\nIhr könnt sie noch immer einholen, wenn Ihr Euch beeilt. Die Kapelle befindet sich westlich von hier.", sourceObjective = "Meldet Euch bei Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme.", completion = "Sie bestehen auch nur aus Fleisch und Knochen - der Geißel also nicht gewachsen.\n\nWir haben zwar keinen unserer Brüder gefunden, sind jedoch über etwas Besonderes gestolpert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12739] = { id = 12739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Tauren, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Malar Tapferhorn hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12740] = { id = 12740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallschirme für den Argentumkreuzzug", description = "Diese Himmelsschrecken töten meine Leute! In den Tod zu stürzen, ist eine schreckliche Art zu sterben.\n\n{class}, Ihr müsst diese Fallschirme hinaus zu ihnen aufs Feld bringen! Zumindest haben sie dann eine Überlebenschance.", sourceObjective = "Kommandant Falstaav in der Argentumwache möchte, dass Ihr 10 Argentumkreuzfahrer oder Argentumschildmänner draußen auf dem Hof mit Fallschirmen versorgt.", completion = "Ihr seid ein guter Mann, {name}. Wir können uns glücklich schätzen, dass Ihr zufällig vorbeigekommen seid.\n\nBleibt doch ein Weilchen. Ich bin mir sicher, dass es hier vieles zu tun gibt, bei dem ein fähiger {class} wie Ihr helfen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12741] = { id = 12741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke des Sturms", description = "Dumme Großzungen denken, Singen zu Wolken ihnen Macht gibt. Rejek zeigt Großzungen, wie man Macht kriegt - durch Nehmen!\n\nWeit im Nordwesten liegt großes, flaches Gebiet, das Großzungen \"Sturmherrenschelf\" nennen. Rejek ist sicher, man kann dort nur hinkommen, wenn fliegen wie ein Vogel.\n\nAuf diesem Schelf hat Rejek von mächtigen Kräften von Wind und Wasser gehört. Töte sie für ihre Bosheit und bringe dann zum \"Sturmschrein\" von Großzungen an der Westseite des Schelfs. Rejek wird warten, bis du mit ultimativer Macht zurückkommen.", sourceObjective = "Sammelt 3 Essenzen des Monsuns und 3 Essenzen des Sturms ein und bringt sie zum Sturmschrein. Kehrt mit der wahren Macht des Sturms zu Rejek auf dem Hügel der Wildherzen zurück.", progress = "Du bringst Rejekwahre Macht des Sturms?", completion = "Nun Rejek zeigt feigen Großzungen, wie man Elemente wirklich benutzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12742] = { id = 12742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Menschen, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Ellen Stanbrück hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12743] = { id = 12743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen eine recht angriffslustige Nachtelfe, an deren Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Yazmina Eichendorn hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12744] = { id = 12744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Zwergen, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Donovan Dulfrost hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12745] = { id = 12745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Gnom, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Goby Blastenheimer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12746] = { id = 12746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Vor allem gibt es dort drinnen einen recht angriffslustigen Draenei, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Valok den Gerechten hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", progress = "Wie fühlt es sich an?", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12747] = { id = 12747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen eine recht angriffslustige Blutelfe, an deren Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Lady Eonys hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12748] = { id = 12748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Orc, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Kug Eisenkiefer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", progress = "Wie fühlt es sich an?", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12749] = { id = 12749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustiger Troll, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Iggy Dunkelhauer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12750] = { id = 12750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Diener der Verlassenen, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Antoine Brack hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12751] = { id = 12751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So etwas wie Heimkehr", description = "Kehrt zu Thassarian in der Scharlachroten Taverne zurück und lasst ihn wissen, dass Koltiras Schrei nach Rache erhört wurde. Die Kapelle der Scharlachroten Flamme wird in weniger als ein paar Stunden nur noch ein Haufen Asche sein.\n\nIhr seid ein kaltblütiges Monster, {name}. Ich verneige mich vor Euch, <Bruder/Schwester>.", sourceObjective = "Überbringt Thassarian in der Scharlachroten Taverne in Neu-Avalon die Nachricht Eures Sieges.", completion = "Wieder ein Sieg für die Geißel! Für diese Hunde, diese Scharlachroten, gibt es kein Entrinnen mehr. Jetzt ist es nur noch eine Frage der Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[12752] = { id = 12752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Grüße, Bruder. Ihr möget zwar im Namen der Argentumdämmerung geschickt worden sein, doch das ist nicht der Grund, weshalb Ihr hier seid... Ihr seid hier, um Eurem Volk den Respekt zu verschaffen, den wir uns so redlich verdient haben. Alle Verlassenen würden zustimmen, wenn ich sage: der Zweck heiligt die Mittel. Und unsere Forschungen für das Heilmittel der Zombieseuche sind genau dieses Sprichwort in die Tat umgesetzt...", sourceObjectiveStatus = "unverified-source-field" }
quests[12753] = { id = 12753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Bruder {race}, ich bin stolz, in diesen Zeiten der Not an Eurer Seite stehen zu dürfen. Seid gesegnet und möge die Allianz zwischen Zwergen und Menschen eintausend Jahre lang währen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12754] = { id = 12754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfall am Rundblick", description = "Während Ihr damit beschäftigt wart, Kirchen niederzubrennen und Ungeziefer zu beseitigen, habe ich mich an die Ausarbeitung eines Plans gemacht.\n\nDer Scharlachrote Kurier wird den Scharlachroten Rundblick innerhalb der nächsten Stunde passieren. Die Straßen dort sind recht ungeschützt und wimmeln nur so von Kreuzfahrern. Werft diese provisorische Tarnung über, wenn Ihr dort angekommen seid, und wartet, bis der Kurier vorbeikommt. Schlagt mit all Eurer Wildheit zu, sobald er in Eurer Reichweite ist! Macht ihn nieder und nehmt sein Hab und Gut mitsamt seinen Kleidern!\n\nDer Rundblick ist 200 Meter östlich von hier.", sourceObjective = "Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, den Scharlachroten Kurier zu töten und seine Sachen und die Nachricht zu beschaffen.", progress = "Wenn Ihr diesen Kurier verpasst, werde ich gezwungen sein, Euch zu töten. Mit \"gezwungen\" meine ich, dass ich großen Gefallen daran finden werde, Euer Leben auszulöschen.\n\nBEEILT EUCH!", completion = "<Orbaz liest sich die Nachricht durch.>\n\nDie Armeen von Herdweiler und Tirisfal werden direkt in ein Massaker laufen.\n\n<Orbaz grinst.>\n\nNun zum zweiten Teil des Plans. Ihr werdet diese Nachricht höchstpersönlich an Hochgeneral Abbendis übergeben - dafür sind die Kleider gedacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[12755] = { id = 12755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung mit dem Schicksal", description = "Diese Nachricht muss Abbendis erreichen. Wir wollen nicht ihren Verdacht auf uns ziehen. Sie müssen weiterhin davon ausgehen, dass alles für sie nach Plan verläuft.\n\nIhr werdet die Kleider des Scharlachroten Kuriers anlegen und mit der Hilfe von ein wenig dunkler Magie seine Gestalt annehmen.\n\nAbbendis befindet sich im Königshafen südlich des Scharlachroten Rundblicks. Erzählt ihr die Neuigkeiten und bekommt so viel Informationen wie möglich aus ihr heraus. Sie wird uns sagen können, was es über den \"Scharlachroten Morgen\" zu wissen gibt.", sourceObjective = "Orbaz Blutbann hat Euch befohlen, die Nachricht des Scharlachroten Kuriers bei Hochgeneral Abbendis im Königshafen abzuliefern.", progress = "Wo seid Ihr gewesen? Ihr seid zwei Stunden zu spät. Wir waren gerade dabei, einen Kurier zum Hochkommandanten zu schicken.", completion = "<Hochgeneral Abbendis liest sich die Nachricht durch.>\n\nVerdammt! Die Armeen von Herdweiler und Tirisfal dürfen Neu-Avalon nicht erreichen! Die Geißel wird sie alle töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12756] = { id = 12756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Ansturm tritt hervor", description = "Hört gut zu, Kurier. Die Lande des Scharlachroten Kreuzzugs sind verloren. Neu-Avalon und Havenau wurden von der Geißel überrannt. Die Fratze des Todes ist über uns gekommen und droht damit, uns jeden Augenblick in seine Gewalt zu bringen.\n\nKehrt mit dieser Nachricht zu Galvar zurück:\n\n\"Lasst Eure Armeen umdrehen und bereitet Eure Schiffe darauf vor, in Richtung der gefrorenen Weiten zu segeln. Wenn wir uns das nächste Mal sehen, wird es in Nordend sein.\"\n\nGebt dies Galvar.\n\n<Abbendis händigt Euch ein Tagebuch aus.>\n\nEs wird alles erklären.\n\nDen Scharlachroten Kreuzzug gibt es nicht mehr. Lang lebe der Scharlachrote Ansturm!", sourceObjective = "Liefert das Buch \"Der Weg der Erlösung\" bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon ab.", progress = "<Orbaz lacht.>\n\nWas ist das? Ein Malbuch für Kinder?", completion = "<Orbaz blättert durch das Tagebuch.>\n\nWas für ein Müll! Dies ist der \"Scharlachrote Morgen\"?\n\nSie segeln in ihren Tod! Konzentrieren wir uns lieber auf die anrückenden Armeen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12757] = { id = 12757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Armeen des Scharlachroten Ansturms rücken näher...", description = "Wir müssen uns auf die anrückenden Armeen vorbereiten, {name}. Ihr werdet Hochlord Mograine schleunigst von Eurer Entdeckung berichten! Ich werde ein Portal direkt nach Acherus öffnen. Tretet hindurch und Ihr werdet dorthin befördert.\n\nGebt Hochlord Mograine auch Abbendis' Tagebuch. Vielleicht wird er es nützlich finden.", sourceObjective = "Liefert das Buch \"Der Weg der Erlösung\" bei Hochlord Darion Mograine in \"Acherus: der Schwarzen Festung\" ab.", progress = "Ihr habt was getan?", completion = "Ihr seid zu einem Werkzeug des Untergangs geworden, {class}! Wir werden diese anrückenden Armeen vernichten und ihre Toten zu unseren Dienern machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12758] = { id = 12758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Helden Helm", description = "Rejek hört Geschichten von riesigen Metallmännern beim weit entfernten Sturmherrenschelf. Du finden es weit im Nordwesten, außerhalb des Rands des Beckens.\n\nStell dir vor, wie Rejek den Kopf eines Riesenmetallmanns als Helm benutzen. Machen Rejek unaufhaltsam! Machen Rejek mächtig!\n\nDu es holen für Rejek, aber Metallkopf vielleicht nicht einfach abzumachen von Metallkörper. Vielleicht Bomben klauen von kleinen, grünen Männchen und ihren Freunden in Schwindelgrins' Grabungsstätte in der Nähe der Sonnenstrahlsäule? Benutzen Bomben um Kopf abzukriegen von Metallkörper und bringen zu Rejek.", sourceObjective = "Besorgt Sprengstoff der Venture Co. von der Venture Company in Schwindelgrins' Grabungsstätte und benutzt ihn, um den Kopf eines Sturmbetrachters zu erhalten. Bringt Rejek beim Hügel der Wildherzen den Kopf des Sturmbetrachters.", progress = "Du bringen Rejek neuen Helm?", completion = "Rejek sieht, du seien erfolgreich gewesen! Jetzt Rejek probieren neuen Kriegshelm auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12759] = { id = 12759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrument des Krieges", description = "Zepik mir erzählen, du vielleicht der beste Gorlocjäger, er getroffen... außer Zepik. Immer noch große Schlacht im Südwesten - du gehen helfen.\n\nZepik ein paar der größten, bösesten Fallen in seiner Truhe in Kartaks Stellung hat... Vekgar befohlen, sie für Kampf zu nutzen, also du sie auch benutzen. Geh jede Falle auswählen, die du willst, und töte viele von Großzungen.\n\nGanz, ganz viele!", sourceObjective = "Holt einige von Zepiks Fallen aus seiner Truhe in Kartaks Stellung. Verwendet die Fallen, um 50 der sich in der Nähe aufhaltenden, funkenbesprühten Gorlocs zu töten, dann kehrt zu Schamane Jakjek in Kartaks Stellung zurück.", progress = "Ziemlich durcheinander! Aber immer noch so lustig.", completion = "Du fast so gut mit diesen Fallen wie Zepik!", sourceObjectiveStatus = "unverified-source-field" }
quests[12760] = { id = 12760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Kraft der Wildherzen", description = "Schlacht tobt immer noch in Kartaks Stellung... Ich denke, es an der Zeit für dich, großes Geheimnis der Wildherzen zu lernen.\n\nWir haben Beeren aus anderen Ländern, aus denen wir gekommen... sie nicht so besonders an sich, aber mische sie mit Trinkgetränks und sie machen Wildherz ganz stark. Du nun ein Wildherz... es Zeit, du wirst auch stark.\n\nIch gebe dir jetzt Trinken und dann zerschmetterst du alle Funken-Großzungen.", sourceObjective = "Nutzt den geheimen Trank der Wildherzen und tötet mit der Kraft des Tranks 30 funkenbesprühte Gorlocs um Kartaks Stellung herum.", completion = "Du wilder Kämpfer... komm bald zurück für mehr Kampf. Nie genug gute Kämpfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[12761] = { id = 12761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Kristalle", description = "Funkenbesprühte immer noch angegriffen von Wauwaumenschen... Wir glauben, sie vielleicht nicht aufhören, wenn wir nicht sie aufhalten. Wir haben aber geheime Waffe, wir schicken sie zu Soo-met, damit er nutzen kann, um alle Orakel zu schützen.\n\nGeheime Waffe ist von den Großen persönlich... besonders glänzende Kristalle, die wir in heiligen Tempeln der Großen gefunden. Sei sehr vorsichtig, nicht zerbrechen.\n\nKristalle sind in Kiste nahe Schrein in Zuflucht der Funkenbesprühten, weit im Südwesten. Du gehst und benutzt Kristalle, um Soo-met helfen, Wauwaumenschen zu schlagen.", sourceObjective = "Erlangt die Verteidigung des Kristalls in der Zuflucht der Funkenbesprühten und verwendet sie, um 50 in der Nähe befindliche Wildherzwolvar zu töten. Kehrt zu Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten zurück, sobald diese Aufgaben abgeschlossen sind.", progress = "Sehr mächtig. Wauwaumenschen nicht wissen von Macht der Großen. Dumme Wauwaumenschen.", completion = "Danke, Trockenhaut.\n\nIch behalten diese Kristalle - sie uns beschützen. Vielleicht du kommst bald zurück und uns hilfst noch einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[12762] = { id = 12762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht der Großen", description = "Wir müssen etwas unternehmen, um Wauwaumenschen aufzuhalten, die Zuflucht der Funkenbesprühten angreifen. Jaloot mir einen ganz besonderen Kristall gebracht, den er im Flussnabel gefunden hat... Wir erst einen wie ihn zuvor gesehen.\n\nDer Kristall jetzt nicht hat genug Kraft, aber die geöffnete Lebensblutsäule sollte genug Energie haben, um ihn aufzuladen, wenn du ihn in die Nähe bringst. Sobald der Kristall aufgeladen ist, geh zu Zuflucht der Funkenbesprühten im fernen Südwesten und lass dich von der Energie des Kristalls groß und stark machen.\n\nDann es Zeit, Wauwaumenschen in Hintern zu treten.", sourceObjective = "Ladet den schlafenden polierten Kristall an der offenen Lebensblutsäule. Reist zur Zuflucht der Funkenbesprühten und verwendet die Kraft des Kristalls, um 30 der sich in der Nähe aufhaltenden Wolvar der Wildherzen zu töten. Sprecht anschließend mit Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten.", progress = "Gut, dass du uns hier hilfst. Langer Kampf.", completion = "So viel Energie in dir... voller Kraft der Großen.\n\nIch nicht lüge, ich ein bisschen neidisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12763] = { id = 12763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschiebung von Prioritäten", description = "So dringend unsere Bedürfnisse hier auch sein mögen - es gibt Neuigkeiten aus den Ländern im Norden, die wir nicht ignorieren dürfen.\n\nIch habe soeben eine Nachricht vom Argentumkreuzzug erhalten. Offensichtlich sammeln sich die Streitkräfte der Geißel dort und drohen, Zul'Drak zu überrennen.\n\nIch muss wohl kaum erwähnen, {name}, dass unser Kampf hier aussichtslos wäre, wenn das geschähe. Ihr müsst den Kreuzzüglern dort helfen, die Armeen des Lichkönigs zurückzuschlagen.\n\nSprecht mit Makki, sobald Ihr aufbruchbereit seid.", sourceObjective = "Späher Vor'takh möchte, dass Ihr nach Zul'Drak reist und Euch bei Unteroffizier Riannah an der Lichtbresche meldet.\n\nMakki Orkan im Lager Oneqwah wird für Euren Transport sorgen.", completion = "Möge das Licht obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12766] = { id = 12766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Eurem Abgesandten", description = "<Der Drache in Elfengestalt nimmt Euch das Vorstellungsschreiben ab, liest es sich kurz durch und steckt es in seinen Ärmel.>\n\nAlles scheint in Ordnung zu sein. Wenn es Euch jedoch nichts ausmacht, dann würde ich Euch darum bitten, mit dem Abgesandten hier im Tempel zu sprechen.\n\nSie hat noch eine Sache von großer Wichtigkeit, um die Ihr Euch kümmern solltet, bevor wir Euch hoch zur Königin schicken können.\n\n<Er klopft sich auf den Ärmel, in dem er den Brief gesteckt hat.>\n\nIch werde ihn sicher aufbewahren, bis Ihr zurück seid.", sourceObjective = "Sprecht mit Lauriel Wahrklinge im Wyrmruhtempel.", completion = "Ihr müsst {name} sein. Man hat mir gesagt, dass Ihr kommen würdet.\n\nIch denke, dass ich hier eine Aufgabe habe, für die Ihr ganz besonders gut geeignet seid. Nehmt Euch ihrer an und Ihr würdet in die hiesige Drachengemeinschaft aufgenommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12767] = { id = 12767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Eurem Abgesandten", description = "<Der Drache in Elfengestalt nimmt Euch das Vorstellungsschreiben ab, liest es sich kurz durch und steckt es in seinen Ärmel.>\n\nAlles scheint in Ordnung zu sein. Wenn es Euch jedoch nichts ausmacht, dann würde ich Euch darum bitten, mit dem Abgesandten hier im Tempel zu sprechen.\n\nEr hat noch eine Sache von großer Wichtigkeit, um die Ihr Euch kümmern solltet, bevor wir Euch hoch zur Königin schicken können.\n\n<Er klopft sich auf den Ärmel, in dem er den Brief gesteckt hat.>\n\nIch werde ihn sicher aufbewahren, bis Ihr zurück seid.", sourceObjective = "Sprecht mit Golluck Felsenfaust im Wyrmruhtempel.", completion = "Ihr müsst {name} sein. Mir wurde gesagt, dass Ihr kommen würdet.\n\n\n\nIch habe hier etwas, um das Ihr Euch kümmern müsst. Tut es und Ihr würdet Euch den hiesigen Drachen beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12768] = { id = 12768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Wyrmruhtempels", description = "Ihr habt mehr als nur Eure Vertrauenswürdigkeit bewiesen.\n\nIhr solltet zum Wyrmruhtempel zurückkehren und erneut mit dem Wächter Tariolstrasz sprechen, {name}.", sourceObjective = "Sprecht mit Tariolstrasz im Wyrmruhtempel.", completion = "Schon so bald zurück, {name}?\n\nCeristrasz hat uns schon berichtet, dass Ihr kommen würdet. Ich danke Euch für das, was Ihr am Rubindrachenschrein geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12769] = { id = 12769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Wyrmruhtempels", description = "Ihr habt mehr als nur Eure Vertrauenswürdigkeit bewiesen.\n\nIhr solltet zum Wyrmruhtempel zurückkehren und erneut mit dem Wächter Tariolstrasz sprechen, {name}.", sourceObjective = "Sprecht mit Tariolstrasz im Wyrmruhtempel.", completion = "Schon so bald zurück, {name}?\n\nVargastrasz hat uns schon berichtet, dass Ihr kommen würdet. Ich danke Euch für das, was Ihr am Rubindrachenschrein geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12770] = { id = 12770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umverteilung der Ressourcen", description = "Hört zu, {class}!\n\nEure Tage hier sind gezählt. So sehr wir fähige Kämpfer in unseren Reihen brauchen, gibt es Ärger im Norden, der unsere Probleme wie eine sommerliche Sturmwindparade erscheinen lässt.\n\nEs sieht aus, als ob die Geißel ihre Anstrengungen konzentrieren und einen Vorstoß nach Zul'Drak durchführen würde. Wenn Zul'Drak fallen sollte, könnten wir genauso gut einpacken.\n\nIhr könnt Eure Besorgungen hier noch erledigen, aber dann müsst Ihr zur Lichtbresche aufbrechen. Redet mit Samuel, wenn Ihr eine Transportmöglichkeit braucht.\n\nWegtreten.", sourceObjective = "Gryan Starkmantel will, dass Ihr Euch bei Unteroffizier Riannah an der Lichtbresche in Zul'Drak meldet.\n\nIhr könnt wegen einer Transportmöglichkeit zur Lichtbresche bei Samuel Klarbuch vorsprechen.", completion = "Möge das Licht obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12771] = { id = 12771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenschmiede", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Eisenschmiede ankommt. Magni Bronzebart wird es kaum erwarten können, den Kampf nach Nordend zu tragen, und dies wird ihn sicherlich seinem Ziel ein Stück näher bringen.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu König Magni Bronzebart in Eisenschmiede bringt.", progress = "Hallo {name}. Noch nie habe ich einen kräftigeren {race} gesehen! Die Prüfungen der Scherbenwelt haben Euch hart gemacht, Bruder. Ihr seid der Stolz Eures Volkes!", completion = "Bei meinem Barte! Diesem hier wohnt eine Kraft inne, die einer Flotte unserer Flugmaschinen Konkurrenz machen könnte! Ich werde es meinen Kriegspriestern geben und wir werden uns einen Plan ausdenken, mit dem wir diese schrecklichen Nekropolen so schnell wie möglich wieder nach Nordend schicken können... mit uns dicht auf den Fersen!\n\nOh, Muradin, mein Bruder, du musst leben! Bei der Ehre der Bronzebärte: Ich werde dich finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12772] = { id = 12772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "{name}, geehrter {race}, seid willkommen. Möget Ihr im Schein des Lichts baden - möge Eure uralte Weisheit unser Land in diesen Zeiten der Not schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12773] = { id = 12773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Darnassus ankommt. Liefert es bei Tyrande Wisperwind ab - für ihre Priesterinnen wird es einen unerlässlichen Quell der Macht im Kampfe gegen die unheiligen Streitkräfte des Nordens darstellen.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu Tyrande Wisperwind in Darnassus bringt.", progress = "{name}, mein Sohn. Wieder einmal sind wir in einen Konflikt verwickelt, der alles, was wir kennen, in Stücke reißen könnte. Es ist gut, dass ein {class} mit Euren Talenten und Eurer Stärke uns bei der Verteidigung des Weltenbaums zu Hilfe kommt.", completion = "Was ist das? Was für ein Segen! Das Licht, das sie in diesem Artefakt aufgefangen haben, scheint beinahe so hell wie das Licht des Mondes! Unsere Priester werden diese Kraft gegen unsere Feinde einsetzen und des Lichkönigs Invasion wird mit Sicherheit fehlschlagen. Habt Dank, {name}. Unser Weltenbaum wird nun in Sicherheit sein.\n\nAuch spürten wir, dass weit im Norden womöglich ein weiterer Weltenbaum existieren könnte - versteckt in der Nähe des Lichkönigs eigenen Reichs. Der Tag mag vielleicht kommen... an dem wir beide Bäume hüten und eine neue Ära des Friedens einläuten mögen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12774] = { id = 12774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmwind", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Sturmwind ankommt. Der König von Sturmwind ist vor Kurzem zurückgekehrt. Ich bin mir sicher, dass er für dieses Werkzeug dankbar sein wird.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu König Varian Wrynn in Sturmwind bringt.", progress = "{name}, gut Euch zu sehen. Eure Stärke und Euer Können sind wie ein Segen in diesen Zeiten von Kummer und Schmerz.", completion = "Also haben Shattraths heilige Leute erschaffen, was sie versprochen haben! Im Nachhinein würde ich sagen, dass es die richtige Entscheidung war, so viele Priester und Paladine dorthin zu beordern, anstatt sie gegen die Geißel in den Kampf zu schicken. Mit diesen heiligen Waffen werden wir vielleicht dazu imstande sein, den verdammten Lichkönig und seine Dienerschaft zurückzuschlagen!\n\nUnd so ernenne ich Euch hiermit zu Fürst {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12775] = { id = 12775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Bruder, wir wurden wieder gerufen, um gegen die Geißel zu kämpfen. Es ist gut, dass Ihr hier seid - mit Eurer Stärke und der Kraft des Lichtes mögen wir vielleicht doch noch den Sieg davontragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12776] = { id = 12776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Exodar", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher zur Exodar gelangt. Liefert es bei Prophet Velen in der Halle des Lichts ab, auf dass er seine Kräfte gegen die unheiligen Streitkräfte des Nordens einsetzen mag.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt bei Velen in der Exodar abliefert.", progress = "Meine Tochter, die Lande der Menschen und Orcs hatten einen positiven Einfluss auf Euch - eine solche Stärke wohnt Euch nun inne...", completion = "Ah, ich kann sehen, wie die Kraft der Naaru durch diesen Gegenstand leuchtet, als wohnte das Licht selbst in seinem Inneren. So viel Gutes kann mit diesem Werkzeug vollbracht werden; die Nekropolen, die aus den gefrorenen Weiten des Nordens geschickt wurden, werden sicherlich scheitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12777] = { id = 12777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Zu sehen, dass ein nobler {race} wie Ihr uns zu Hilfe eilt, erfüllt mein Herz mit Licht. Seid gesegnet, guter {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12778] = { id = 12778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Scharlachroten Kreuzzugs", description = "Die Falle hat zugeschnappt, Todesritter. Die Armeen von Herdweiler und Tirisfal sind angekommen; gerade rechtzeitig, um noch zu sehen, wie ihre Enklave in Flammen steht! Falls sie jetzt umkehren sollten, werden sie mit dem Rücken zu uns kämpfen müssen.\n\n<Mograine schüttelt den Kopf.>\n\nNein, ihnen bleibt nur eine Wahl, deren Resultat unumgänglich wäre: IHR ENDE!\n\nWährend wir hier noch sprechen, bereiten sie sich auf ihr letztes Gefecht vor.\n\nDer Lichkönig erwartet Eure Rückkehr, Champion. Er ist dort unten bei der Todesbresche und hält Ausschau.", sourceObjective = "Geht zur Todesbresche und sucht den Lichkönig auf.", completion = "Ihr habt mir gut gedient, {name}. Die Lande des Scharlachroten Kreuzzugs wurden von der Geißel gebrandmarkt. Ihr habt für Tod und Vernichtung gesorgt, so weit das Auge reicht, und mir den letzten Rest der Armeen des Scharlachroten Kreuzzugs ans Messer geliefert.\n\n\n\nEs ist nun Zeit, dass Ihr zu Ende bringt, was Ihr begonnen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12779] = { id = 12779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Dinge müssen ein Ende...", description = "Ihr habt unzählige Legionen vernichtet und noch immer verlangt es Eurem dunklen Herzen nach mehr, {name}.\n\n<Der Lichkönig hält inne.>\n\nAlle Dinge müssen ein Ende haben, Todesritter. Das letzte Aufgebot der Armeen des Scharlachroten Kreuzzugs stellt sich uns entgegen. Für sie wird es kein Entrinnen geben... Sie haben keine Wahl. Aus diesem Grund werden sie auch mit einer Wildheit kämpfen, wie Ihr sie noch nie erlebt habt.\n\nStoßt in dieses Horn und ruft einen meiner Wyrm herbei. Klettert auf seinen Rücken und reitet mit ihm in die Schlacht. Mit seiner Hilfe werdet Ihr dem Scharlachroten Kreuzzug ein Ende bereiten.", sourceObjective = "Der Lichkönig hat Euch befohlen, den Scharlachroten Kreuzzug auszuradieren.\n\nBenutzt das Horn der Frostbrut, um einen Frostbrutbezwinger herbeizurufen und mit ihm 150 Scharlachrote Soldaten und 10 Scharlachrote Ballisten zu vernichten. Weicht Geschossen aus, indem Ihr aus ihrer Schusslinie fliegt!", progress = "Tötet sie alle...", completion = "Kniet nieder, Ritter. Hiermit setze ich Euch diesen Helm auf, um Euer schreckenerregendes Aussehen zu vervollkommnen. Jeder, der auch nur wagen sollte, einen Blick auf Euer dunkles Antlitz zu werfen, wird wissen, dass ihn der Tod ereilen wird. Lasst niemanden es wagen, sich gegen unseren König zu stellen, ohne dass er Euren gnadenlosen Zorn zu spüren bekäme, {name}.\n\nEs bleibt nur noch eine letzte Aufgabe...\n\n\n\nDie Kapelle des hoffnungsvollen Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12780] = { id = 12780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind unseres Feindes", description = "So geschmacklos es für uns auch sein mag, mit Todesrittern zusammenzuarbeiten, wir können uns einfach nicht leisten, bei unseren hiesigen Verbündeten wählerisch zu sein.\n\nWir sind zwischen der Geißel und den Drakkari eingeschlossen, die nichts weiter wollen, als uns aus dem Weg zu räumen, damit sie zueinander kommen können.\n\nReist nach Westen zur Schwarzen Wacht. Sprecht dort mit Stefan und seht nach, ob Ihr ihm zu Diensten sein könnt.", sourceObjective = "Unteroffizier Riannah in der Lichtbresche möchte, dass Ihr mit Stefan in der Schwarzen Wacht sprecht und ihm Eure Unterstützung anbietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12781] = { id = 12781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen zu World of Warcraft!\n\nAls besonderen Dank dafür, dass Ihr die World of Warcraft Collector's Edition gekauft habt, erhaltet Ihr diesen Geschenkgutschein. Tauscht ihn bei Siouxsie der Banshee in der Schwarzen Festung ein und Ihr werdet ein Geschenk erhalten: einen kleinen Gefährten, der Euch auf Eurer Suche nach Abenteuern und Ruhm begleiten wird.\n\nNochmals danke. Genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt den Geschenkgutschein der Schwarzen Festung zu Siouxsie der Banshee in der Schwarzen Festung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12782] = { id = 12782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes Exemplar Ihr seid. Wir müssen viele Experimente durchführen und unser Nachschub an Freiwilligen ist fast erschöpft. So, Elfe, wie es schon Euer Name andeutet: Habt Ihr etwas Blut übrig? Frisches Blut ist immer willkommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12783] = { id = 12783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes, robustes Exemplar Ihr seid. Wir haben viele Experimente durchzuführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist in der Tat willkommen und mit dem Zorn in Eurem Blute ließe sich stundenlang forschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12784] = { id = 12784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes Exemplar Ihr seid. Wir müssen viele Experimente durchführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist immer willkommen und ich bin mir sicher, dass jemand Eurer Statur etwas Blut übrig hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[12785] = { id = 12785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Orgrimmar. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Karlov. Er ist bei Thrall in Orgrimmar.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apotheker Karlov in Orgrimmar das Zwei-Seuchen-Hirn bringt.", progress = "Willkommen in Orgrimmar, {name}. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12786] = { id = 12786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerfels", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Donnerfels. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Chaney. Er ist bei Magatha Grimmtotem in Donnerfels.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apotheker Chaney in Donnerfels das Zwei-Seuchen-Hirn bringt.", progress = "Willkommen in Donnerfels, {name}. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12787] = { id = 12787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstadt", description = "Die Zombieseuche war ein versteckter Segen. Auf unserer Suche nach einem Heilmittel haben wir sehr viel über die Geißel und ihre ansteckende Krankheit gelernt. Unsere Forschungen haben uns Waffen gegen sie verliehen. Waffen - und Werkzeuge...\n\nNehmt das hier, es ist der Kopf eines Zombies und er wurde zum Teil von seiner Seuche geheilt, indem wir ihm ein aus unseren neusten Entdeckungen hergestelltes Präparat injiziert haben. Liefert den Kopf beim Apothekermeister Faranell ab. Ich habe eine Liste mit Experimenten, denen der Kopf unterzogen werden soll.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apothekermeister Faranell in Unterstadt das Zwei-Seuchen-Hirn bringt.", progress = "Grüße, {name}. Seid Ihr aus Shattrath gekommen? Habt Ihr Anweisungen von Großapotheker Putress für mich?", completion = "Ah, was für ein ausgezeichnetes Exemplar du doch bist. Die Krankheit - die Krankheiten, wie sie durch dein Gehirn tanzen, müssen dir so erhabene Visionen bescheren. Wir werden lange Nächte miteinander verbringen, werden sprechen, du und ich, und ich werde dir deine Gedanken herauspicken, während ich dir das Fleisch von deinem Schädel abziehe.\n\nHab keine Angst, Kleiner. Dein Opfer wird uns ein unglaubliches Wissen vermitteln. Du bist ein Geschenk für die Verlassenen - du wirst ein neues Zeitalter einläuten; ein Zeitalter, in dem wir von den Völkern dieser Erde respektiert werden. Dein Platz in der Geschichte ist sicher...", sourceObjectiveStatus = "unverified-source-field" }
quests[12788] = { id = 12788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silbermond", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Silbermond. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meiner Assistentin Apothekerin Tepesh. Sie ist bei Lor'themar Theron in Silbermond.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apothekerin Tepesh in Silbermond das Zwei-Seuchen-Hirn bringt.", progress = "Willkommen in Silbermond, {name}. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12789] = { id = 12789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Bresche!", description = "Macht Euch bereit, {class}. Ich entsende Euch zur Lichtbresche nordöstlich von hier.\n\nIch habe Nachricht erhalten, dass die Geißel dazu übergegangen ist, Zul'Drak einzunehmen.\n\n<Valus starrt Euch direkt in die Augen.>\n\nDies wird nicht passieren.\n\nSeht zu, dass die Diener der Geißel dort vernichtet werden. Das Licht verlangt danach.\n\nWegtreten.", sourceObjective = "Kreuzritter Valus bei der Lichtwarte möchte, dass Ihr Euch bei Unteroffizier Riannah in Lichtbresche in Zul'Drak meldet.", completion = "Ausgezeichnet. Valus muss meinen Bericht erhalten haben.\n\nLasst uns an die Arbeit gehen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12790] = { id = 12790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin- und zurückkommen: mit Magie", description = "Nur, falls Ihr es nicht wissen solltet: Ihr könnt den Kristall auf der Plattform hinter mir dazu benutzen, um Euch zur Violetten Wacht im Kristallsangwald unterhalb von Dalaran zu teleportieren.\n\nIm Gegenzug könnt Ihr dann auch den Kristall in der Wache verwenden, um zur Kammer über mir zu gelangen.\n\nTut dies nun für mich.", sourceObjective = "Erzmagierin Celindra am Violetten Tor möchte, dass Ihr den Teleporter zum Kristall der Violetten Wacht und den Teleporter zum Dalarankristall verwendet.", progress = "Ich spüre, dass Ihr noch nicht alle beide Teleportationskristalle verwendet habt.\n\nMacht nichts, lasst Euch Zeit.", completion = "Ausgezeichnet, {class}. Nun wisst Ihr, wie man zum Kristallsangwald gelangt und wie man auch wieder zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12791] = { id = 12791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Hallo, {name}. Ihr wisst womöglich, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran liegt nicht länger unter seiner schützenden Kuppel am Ufer des Lordameresees. Nun schwebt die Insel auf magische Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr nun bereit dazu seid, zur Stadt zu reisen. Sprecht mich wieder an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nSucht Erzmagierin Celindra auf, sobald Ihr dort angekommen seid, und gebt Ihr mein Signet als Beweis dafür, dass wir gesprochen haben.", sourceObjective = "Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab.", progress = "Ich grüße Euch, {class}.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12792] = { id = 12792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wichtigste zuerst", description = "Hört gut zu, {race}!\n\nIn der gesamten Region kriselt es. Überall, wo Ihr hinseht, werdet Ihr Leute finden, die Eure Hilfe gebrauchen könnten.\n\n<Kunz blickt Euch direkt in die Augen.>\n\nDoch niemand braucht Eure Hilfe gerade dringender als Riannah. Die Diener der Geißel haben sich nun zwischen uns gedrängt. Sie und ihre Männer sind also abgeschnitten.\n\nLichtbresche, der Ort, an dem sich ihre Streitkräfte befinden, liegt gleich südwestlich von hier.", sourceObjective = "Kommandant Kunz in der Argentumwacht möchte, dass Ihr Euch bei Unteroffizier Riannah in der Lichtbresche meldet.", completion = "Mein Bericht muss Kunz erreicht haben.\n\nEs ist gut zu wissen, dass er wohlauf ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12793] = { id = 12793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauch am Horizont", description = "Habt Ihr das gehört, {race}?\n\nDas Schlachtengeschrei weit im Westen reicht bis hierher und übertönt selbst unser eigenes.\n\nDie Geißel droht damit, durch die Linien derer zu brechen, die dem sogenannten Argentumkreuzzug angehören. Dies zu verhindern, ist so dringend vonnöten, wie alles andere in der Region.\n\nReist zur Lichtbresche und unterstützt sie bei ihrem Kampf dort. Sprecht mit Maaka und er wird Euch sicher dorthin bringen.", sourceObjective = "Khufu in Zim'Torga möchte, dass Ihr zur Lichtbresche reist und Euch bei Unteroffizier Riannah meldet.\n\nMaaka wird Euch dorthin bringen.", completion = "Möge das Licht obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12794] = { id = 12794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Hallo, {name}. Es ist Euch möglicherweise bekannt, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran befindet sich nun nicht länger unter der schützenden Kuppel an den Ufern des Lordameresees. Nun schwebt die Stadt auf magische Art und Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr bereit seid, zu der Stadt zu reisen. Sprecht mich erneut an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nWenn Ihr dort seid, so sprecht mit der Erzmagierin Celindra und gebt ihr mein Signet als Beweis dafür, dass Ihr von mir kommt.", sourceObjective = "Bringt der Erzmagierin Celindra am Violetten Tor in Dalaran das Signet der Kirin Tor.", progress = "Ich grüße Euch, {class}.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12795] = { id = 12795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbe bekennen", description = "Gerade erst habe ich ein Signalfeuer über der Baumlinie gen Osten gesehen.\n\nDas kann nur bedeuten, dass die Dinge für die Kreuzfahrer in der Argentumwache nicht so glatt laufen.\n\nIch kann unseren Posten hier nicht verlassen, {race}, Ihr jedoch schon. Wenn es die Zeit erlaubt, dann macht Euch auf den Weg zu Kommandant Falstaav und seht nach, ob Ihr ihnen nicht die Arbeit erleichtern könnt.", sourceObjective = "Datura Blutrose an der Schwarzen Wacht möchte, dass Ihr mit Kommandant Falstaav in der Argentumwache sprecht.", completion = "Wie es der Zufall so will, gibt es da etwas, bei dem Ihr uns helfen könnt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12796] = { id = 12796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Hallo, {name}. Ihr wisst womöglich, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran liegt nicht länger unter seiner schützenden Kuppel am Ufer des Lordameresees. Nun schwebt die Insel auf magische Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr nun bereit dazu seid, zur Stadt zu reisen. Sprecht mich wieder an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nSucht Erzmagierin Celindra auf, sobald Ihr dort angekommen seid, und gebt Ihr mein Signet als Beweis dafür, dass wir gesprochen haben.", sourceObjective = "Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab.", progress = "Ich grüße Euch, {class}.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12797] = { id = 12797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück durchs Tor", description = "Ihr sagt die Wahrheit, {race}. Ich kann spüren, wie die Essenz des Sholazarbeckens selbst jetzt, während wir hier miteinander sprechen, durch die untote Seuche allmählich verbraucht wird.\n\nIch habe mich selbst, mein Sein, an diese Rune gebunden, {race}. Bringt sie zu derjenigen, die Euch hierher geschickt hat; denn nur ihre eigene Macht kann mir den Zugang zu ihrem Reich gewähren.", sourceObjective = "Bringt die Omegarune zum Avatar von Freya im Katarakt der Regenrufer im Sholazarbecken.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Gut gemacht.\n\nWehe unseren Feinden. Wehe denjenigen, die dem Lichkönig dienen und den Kreationen der Titanen mit Zerstörung drohen. Wehe - denn der Etymidian ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12798] = { id = 12798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwertkartenset", description = "Jetzt, da Ihr alle Schwertkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", sourceObjective = "Beschwört mithilfe des Schwertkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set der Schwertkarten zusammen zu bekommen! Ausgezeichnet.", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12799] = { id = 12799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister aufsaugen", description = "\"Ihr solltet froh sein, dass er kommt,\" meinten sie. \"Ihr werdet seine Gesellschaft genießen,\" meinten sie...\n\nTja, es ist nicht so, als hätte ich in der Sache irgendeine Wahl. Finkelstein ist der beste Alchemist des Kreuzzugs. Ich nehme einmal an, dass ich mich geehrt fühlen sollte, dass er sich hier bei mir eingerichtet hat. Doch seitdem er hier ist, wurde ich dazu verbannt, verschiedene alchemistische Zutaten zu sammeln.\n\nSagt mir, {race}, was haltet Ihr davon, wenn Ihr mir zur Hand ginget? Gleich südlich von hier gibt es ein paar Teiche, die von Geistern der uralten Trolle heimgesucht werden. Bringt mir ihr Ektoplasma.", sourceObjective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 5 Einheiten uralten Ektoplasmas von den verlorenen Drakkarigeistern in den Teichen von Zha'jin sammelt.", progress = "Guten Tag, {race}. Habt Ihr das Ektoplasma gesammelt, um das Finkelstein gebeten hat?", completion = "Habt Dank, {class}.\n\nDas sollte meinen Männern wertvolle Zeit ersparen.", sourceObjectiveStatus = "unverified-source-field" }
